['Here is a basic implementation of how this could look like in C. Note that actual implementations can vary greatly depending on specific use cases, hardware capabilities, and performance requirements. This code does not perform logging or error handling for brevity:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <errno.h>

typedef struct {
    int offsetSize;
    int keySize;
    int recordSize;
} Config;

typedef struct {
    pthread_mutex_t lock;
    FILE *logFile;
    void **arrays[3];
} Data;

int uniqueValueGenerator(int min, int max) {
    /* Implement your own generator */
    return rand() % (max - min + 1) + min;
}

void *initArray(size_t size, int (*valueGen)(int, int), void **arrayPointer, pthread_mutex_t *lock) {
    if (!arrayPointer || !lock) return NULL;

    *arrayPointer = malloc(sizeof(**arrayPointer) * size);
    if (!*arrayPointer) {
        return NULL;
    }

    pthread_mutex_lock(lock);
    for (int i = 0; i < size; ++i) {
        ((int **)*arrayPointer)[i] = valueGen(-100, 100);
    }
    pthread_mutex_unlock(lock);

    return *arrayPointer;
}

void initDataStructure(Config config, Data *data) {
    if (!data || !config.offsetSize || !config.keySize || !config.recordSize) return;

    pthread_mutex_init(&data->lock, NULL);

    data->arrays[0] = initArray(config.offsetSize, uniqueValueGenerator, &data->arrays[0], &data->lock);
    data->arrays[1] = initArray(config.keySize, uniqueValueGenerator, &data->arrays[1], &data->lock);
    data->arrays[2] = initArray(config.recordSize, uniqueValueGenerator, &data->arrays[2], &data->lock);

    if (!data->arrays[0] || !data->arrays[1] || !data->arrays[2]) {
        fprintf(stderr, "Memory allocation failure\n");
        freeArrays(data->arrays);
        exit(-1);
    }
}

void freeArrays(void **arrays) {
    for (int i = 0; i < 3; ++i) {
        if (arrays[i]) {
            free(arrays[i]);
        }
    }
}
```
Note: This is a simplified example and does not include error handling, logging or thread-safety mechanisms. You might want to use more sophisticated approaches for production code, such as using mutexes for thread-safety, writing log files in case of failures, etc. 
Also please remember to call `freeArrays(data->arrays)` and `pthread_mutex_destroy(&data->lock);` before exiting the program to free up all allocated memory and destroy mutexes respectively. Also don't forget to open and close your logFile in `Data` structure.
