        $this->db = $db;
    }

    public function processUserCommand($postData){
        if(!isset($postData['action'])){
            return json_encode(['status'=> 'error', 'message' => 'Action is required.']);
        }
        $this->validateInput($postData);

        $command = $postData['action'];
        switch ($command) {
            case 'create':
                $result = $this->executeCreateCommand($postData);
                break;
            // add cases for update, delete and batch_update as needed.
            default:
                return json_encode(['status'=> 'error', 'message' => "Invalid action {$command}"]);
        }

        if ($result){
            return json_encode(['status'=> 'success', 'data' => count($postData['additional_data'])]);
        }else{
            return json_encode(['status'=> 'error', 'message' => "Command {$command} failed."]);
        }
    }

    private function validateInput($input){
        if (strlen($input['name']) < 5) {
            throw new Exception('Name must be at least 5 characters long.');
        }

        if (!filter_var($input['email'], FILTER_VALIDATE_EMAIL)) {
            throw new Exception("Invalid email format");
        }

        if (strlen($input['password']) < 8 || strlen($input['password']) > 128) {
            throw new Exception('Password must be between 8 and 128 characters long.');
