```csharp
public class RateLimiter {
    private readonly IMemoryCache _cache;

    public RateLimiter(IMemoryCache memoryCache) {
        _cache = memoryCache;
    }

    public bool IsAllowed(string key, int limit, TimeSpan period) {
        var count = 1;

        if (_cache.TryGetValue(key, out count)) {
            if (count > limit) return false;

            _cache.Set(key, ++count, new MemoryCacheEntryOptions().SetAbsoluteExpiration(period));
        } else {
            _cache.CreateEntry(key);
            _cache.Set(key, count, new MemoryCacheEntryOptions().SetAbsoluteExpiration(period));
        }

        return true;
    }
}
```
