['Here is your JavaScript function:

```javascript
function generateFooterElement(scriptObjects) {
    let footerHTML = "<footer>";

    scriptObjects.forEach((scriptObj, index) => {
        // Handle missing type or properties
        if (!scriptObj.type || typeof scriptObj.type !== 'string') {
            scriptObj.type = "text/javascript";
        }

        // If innerHTML is empty or undefined, skip the script
        if(!scriptObj.innerHTML) return;

        let keyAttr = "";
        if (scriptObj.key && typeof scriptObj.key === 'string') {
            keyAttr = `id="${encodeURIComponent(scriptObj.key)}" `; // Ensure uniqueness and avoid conflicts
        } else {
            keyAttr = `id="script-${index}" `; 
        }

        let asyncAttr = "";
        if (scriptObj.async) {
            asyncAttr = 'async ';
        }

        let deferAttr = "";
        if (scriptObj.defer) {
            deferAttr = 'defer ';
        }

        footerHTML += `<script ${keyAttr}${asyncAttr}${deferAttr}type="${encodeURIComponent(scriptObj.type)}">
                          ${encodeURIComponent(scriptObj.innerHTML)}
                      </script>`; 
    });

    footerHTML += "</footer>";
    return footerHTML;
}
```
This function works by iterating over the script objects array and constructing an HTML string for each valid script object. It handles edge cases such as missing or invalid properties, providing default values where necessary, and ensures that only valid scripts are rendered. Unique IDs are created based on keys if provided to avoid conflicts. The resulting HTML is then enclosed within a `<footer>` tag before being returned.
