// Pause and resume functions
const pause = () => tasks.forEach(task => task.cancel());
const resume = () => tasks = tasks.map(task => limiter.schedule(() => processStream(task.id, db)));

function startDataCollection(streamIds, delay) {
  streamIds.forEach((id) => {
    const randomDelay = Math.floor(Math.random() * delay);
    setTimeout(() => {
      tasks.push({
        id: id,
        cancel: limiter.schedule(() => processStream(id, db))
      });
    }, randomDelay);
  });
}
