class ModuleLoader {
  constructor(baseURL) {
    this.loadedModules = new Map();
    this.failedModuleRequests = new Set();
    this.baseURL = baseURL;
  }

  async loadModule(moduleName, onSuccessCallback, onErrorCallback) {
    if (this.loadedModules.has(moduleName)) {
      return Promise.resolve(this.loadedModules.get(moduleName));
    } else if (this.failedModuleRequests.has(moduleName)) {
      const err = new Error(`Failed to load ${moduleName}. Please try again.`);
      return Promise.reject(err);
    }

    let module;
    try {
      const response = await fetch(this.baseURL + moduleName, { mode: 'cors' });

      if (!response.ok) throw new Error('Network error');

      const text = await response.text();
      module = new Function(`return ${text}`); // Wrap in function to avoid polluting global scope
      this.loadedModules.set(moduleName, module);
    } catch (error) {
      this.failedModuleRequests.add(moduleName);

      if (onErrorCallback) onErrorCallback(error);

      return Promise.reject(error);
    }

    if (onSuccessCallback) onSuccessCallback(module);

    return module;
  }

  generateModulesFromFilenamePattern(filenamePattern, callback) {
    // This function generates the modules based on filename pattern.
    // Implementation depends on how you decide to separate generated modules and their dependencies.
    // You might use a simple string replace or regex-based approach, etc.
