public class CloudNativeService {
    private static final Logger logger = LoggerFactory.getLogger(CloudNativeService.class);
    private PropertiesConfiguration configs;
    private JedisPool pool;
    private EventLoopGroup group;

    public CloudNativeService() {
        Configurations configs = new Configurations();
        try {
            this.configs = configs.properties("settings.properties");
            // Initialize Jedis Pool for Redis based logging 
            pool = new JedisPool(new JedisPoolConfig(), "localhost");

            // Netty Event Loop Group
            group = new NioEventLoopGroup();
        } catch (ConfigurationException e) {
            logger.error("Failed to load properties", e);
        }
    }

    public void startService() throws InterruptedException, ConfigurationException {
        int startupDuration = configs.getInt("service.startup");

        // validate delay range
        if (startupDuration < 0 || startupDuration > 60) {
            logger.error("Startup duration out of range");
            throw new IllegalArgumentException("Startup duration must be between 0 and 60 seconds");
        }

        Thread.sleep(startupDuration * 1000);
    }

    public void stopService() {
        // Clean up resources like Redis pool, Netty event loop group etc.
        if (pool != null) {
            pool.close();
        }
        if (group != null) {
            group.shutdownGracefully().syncUninterruptibly();
        }
    }
}
