["```javascript
async function processOAuthStream(certificatesUrl, privateKeysUrl) {
    const fetchCertificate = async (url) => {
        try {
            const response = await fetchWithTimeout(url);
            return await response.text();
        } catch (error) {
            handleError(error);
        }
    };

    const fetchPrivateKey = async (url) => {
        try {
            const response = await fetchWithTimeout(url);
            return await response.text();
        } catch (error) {
            handleError(error);
        }
    };

    const combinePEMFiles = (certificate, privateKey) => {
        if (!isValidCertificate(certificate)) throw new Error('Invalid certificate');
        if (!isValidPrivateKey(privateKey)) throw new Error('Invalid private key');

        return `${certificate}\n\n${privateKey}`;
    };

    const fetchWithTimeout = async (url, options={}, timeout = 3000) => {
        return Promise.race([
            fetch(url, options),
            new Promise((_, reject) => setTimeout(() => reject(new Error('Request timed out')), timeout))
        ]);
    };

    const handleError = (error) => {
        if (error instanceof TypeError && error.message === 'Network request failed') {
            throw new Error('Failed to fetch data from the server');
        } else if (error.message === 'Request timed out') {
            throw error;
        } else {
            console.log(error);
        }
    };

    const isValidCertificate = (certificate) => /^-+BEGIN CERTIFICATE-+([a-zA-Z0-9+\/=\r\n]+)-+END CERTIFICATE-+$/m.test(certificate);

    const isValidPrivateKey = (privateKey) => /^-----BEGIN PRIVATE KEY-----\s*([a-zA-Z0-9+\/=]{64}\s*)*\s*-----END PRIVATE KEY-----$/m.test(privateKey);

    const certificatePromise = fetchCertificate(certificatesUrl);
    const privateKeyPromise = fetchPrivateKey(privateKeysUrl);

    const [certificate, privateKey] = await Promise.all([certificatePromise, privateKeyPromise]);

    return combinePEMFiles(certificate, privateKey);
}
```
"]

