```c
#include <stdio.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netdb.h>
#include <arpa/inet.h>

int enhancedDNSResolver(char* hostname, char* ip) {
    struct addrinfo hints, *res;
    int errcode;
    char addrstr[100];
    void *ptr;

    memset (&hints, 0, sizeof (hints));
    hints.ai_family = PF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags |= AI_CANONNAME;

    errcode = getaddrinfo (hostname, NULL, &hints, &res);
    if (errcode != 0) {
        perror ("getaddrinfo");
        return -1;
    }

    printf ("Host: %s\n", hostname);
    while (res) {
        inet_ntop (res->ai_family, res->ai_addr->sa_data, addrstr, 100);

        switch (res->ai_family) {
            case AF_INET:
                ptr = &((struct sockaddr_in *) res->ai_addr)->sin_addr;
                break;
            case AF_INET6:
                ptr = &((struct sockaddr_in6 *) res->ai_addr)->sin6_addr;
                break;
        }
        inet_ntop (res->ai_family, ptr, addrstr, 100);
        printf ("IPv%d address: %s (%s)\n", res->ai_family == PF_INET6 ? 6 : 4,
                addrstr, res->ai_canonname);
        strncpy(ip, addrstr, 100); // Copy resolved IP to the provided buffer
        res = res->ai_next;
    }

    return 0;
}
```
This is a simplified code and does not account for error handling, concurrent updates, fallback mechanisms, logging, or other edge cases you might encounter in a real world scenario. For further development, consider the use of libraries such as Guzzle for PHP OAuth2.0 authentication and c-ares for better DNS resolution.
