        $this->pdo = $pdo;
        $this->cache = $cache;
        $this->httpClient = $httpClient;
    }

    public function updatePassword($userId, $newPassword) {
        // Check if password is strong enough
        if (!$this->isStrongEnough($newPassword)) {
            throw new Exception('New Password is not Strong Enough');
        }

        $retries = 3;
        $delay = 1000; // in ms

        while ($retries-- > 0) {
            $response = $this->httpClient->post('/api/verifyPassword', [
                'json' => ['password' => $newPassword],
                'timeout' => 5, // seconds
            ]);

            if ($response->getStatusCode() == 200) {
                break;
            } elseif ($retries > 1 && $response->getStatusCode() >= 500) {
                usleep($delay); // Sleep and retry
                $delay *= 2;
            } else {
                throw new Exception('External Service Temporarily Unavailable');
            }
        }

        $this->pdo->beginTransaction();

        try {
            $stmt = $this->pdo->prepare("UPDATE users SET password = :password WHERE id = :id");
            $stmt->execute([
                'password' => password_hash($newPassword, PASSWORD_DEFAULT), 
                'id' => $userId
            ]);

            $this->pdo->commit();
        } catch (PDOException $e) {
            $this->pdo->rollBack();
            error_log('Database Error: '.$e->getMessage());
            throw new Exception('Failed to Update Password');
        }
    }

    private function isStrongEnough($password) {
        // This should be replaced with a more robust password checker.
