#include <stdio.h>
#include <syslog.h>

typedef struct {
    int id;
    time_t responseTime;
} Connection;

typedef struct {
    Connection* connections;
    int size;
    int capacity;
} ConnectionPool;

void initConnectionPool(ConnectionPool *pool, int initialCapacity) {
    pool->connections = (Connection*) malloc(sizeof(Connection) * initialCapacity);
    pool->capacity = initialCapacity;
    pool->size = 0;
}

void addToConnectionPool(ConnectionPool *pool, Connection connection) {
    if (pool->size == pool->capacity) {
        // If the array is full, expand it by doubling its capacity
        pool->capacity *= 2;
        pool->connections = realloc(pool->connections, sizeof(Connection) * pool->capacity);
    }
    pool->connections[pool->size++] = connection;
}

