['Here's a simple implementation of this concept:

```cpp
#include <chrono>
#include <iostream>
#include <vector>
#include <mutex>
#include <thread>

class Character {
public:
    struct Attack {
        std::string name;
        int cooldown;
        std::chrono::steady_clock::time_point lastUsed = std::chrono::steady_clock::now(); 

        Attack(std::string n, int c) : name(n), cooldown(c) {}
    };

private:
    std::vector<Attack> attacks;
    std::mutex mtx;
    std::chrono::steady_clock::time_point lastSelectionTime = std::chrono::steady_clock::now();

public: 
    Character() {
        // Initialize the character's attack set (you can expand this in the future)
        attacks.push_back(Attack("Basic Attack", 9));
        attacks.push_back(Attack("Strong Attack", 12));
        attacks.push_back(Attack("Special Attack", 30));
        attacks.push_back(Attack("Ultimate Attack", 60));
    }

    void offensiveStrategy() {
        std::lock_guard<std::mutex> lock(mtx); // Lock the mutex to ensure thread safety

        if (std::chrono::duration_cast<std::chrono::seconds>(std::chrono::steady_clock::now() - lastSelectionTime).count() < 30) {
            return;  // Attacks are still on cooldown, do not select a new one.
        }

        std::vector<Attack*> availableAttacks;

        for (auto& attack : attacks) {
            if (std::chrono::duration_cast<std::chrono::seconds>(std::chrono::steady_clock::now() - attack.lastUsed).count() > attack.cooldown) {
                availableAttacks.push_back(&attack); // Attack is not on cooldown, add it to the list of possible selections
            } 
        }

        if (availableAttacks.empty()) {
            return; // No attacks are off cooldown, do not select a new one yet.
        }

        Attack* selected = availableAttacks[rand() % availableAttacks.size()];

        lastSelectionTime = std::chrono::steady_clock::now();
        selected->lastUsed = lastSelectionTime;

        // print attack history, keep only the last three attacks in the vector
        if (attacks.size() > 3) {
            attacks.erase(attacks.begin()); 
        }
        attacks.push_back(*selected);

        for (auto& attack : attacks) {
            std::cout << "Attack: " << attack.name << "\n";
        }
    }
};
```

In this implementation, I've created a `Character` class with an `offensiveStrategy()` function that selects an attack at random from the list of available attacks (those not on cooldown) and then updates the last used time for that attack. The `lastSelectionTime` variable is also updated to ensure we are not selecting another attack too soon.

The `Attack` struct holds the name of the attack, its cooldown duration in seconds, and the time it was last used (initialized to current time).

This solution can easily be extended with more attacks by adding new `Attacks` to the `attacks` vector. 

Please note: This code assumes that there is a single instance of Character class which is shared among multiple threads/tasks. If you have multiple instances of Character, you might want to use mutexes for each Character instead of using one mutex for all characters.
']

['Here is a basic implementation in C#:

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class DynamicRandomSequenceGenerator
{
    private Random _random;
    private int _rangeStart, _rangeEnd;
    private HashSet<int> _generatedNumbers = new HashSet<int>();

    public DynamicRandomSequenceGenerator(int rangeStart, int rangeEnd)
    {
        if (rangeStart >= rangeEnd)
            throw new ArgumentException("Invalid range: start value should be less than end value");

        _random = new Random();
        _rangeStart = rangeStart;
        _rangeEnd = rangeEnd;
    }

    public int GenerateNextInteger(bool inclusive)
    {
        if (inclusive) _rangeEnd++;

        var maxAttempts = 10 * (_rangeEnd - _rangeStart);
        for (var attempt=0; attempt<maxAttempts; attempt++)
        {
            var nextNumber = _random.Next(_rangeStart, _rangeEnd);

            if (!_generatedNumbers.Contains(nextNumber))
            {
                _generatedNumbers.Add(nextNumber);
                return nextNumber;
            }
        }

        throw new Exception("Failed to generate a unique number within the given range and maximum attempts");
    }

    public float GenerateNextFloat(bool inclusive)
    {
        if (inclusive) _rangeEnd++;

        var maxAttempts = 10 * (_rangeEnd - _rangeStart);
        for (var attempt=0; attempt<maxAttempts; attempt++)
        {
            double sample = _random.NextDouble();
            var scaledSample = (sample * (_rangeEnd-_rangeStart)) + _rangeStart;
            var nextNumber = (int) Math.Floor(scaledSample);

            if (!_generatedNumbers.Contains(nextNumber))
            {
                _generatedNumbers.Add(nextNumber);
                return (float) scaledSample;
            }
        }

        throw new Exception("Failed to generate a unique number within the given range and maximum attempts");
    }

    public List<int> GenerateSequenceOfIntegers(bool inclusive, int length)
    {
        var sequence = new List<int>();
        for (var i=0; i<length; i++) 
            sequence.Add(GenerateNextInteger(inclusive));

        return sequence;
    }

    public void SetSeed(int seed) => _random = new Random(seed);
}
```
This class generates a random integer or float within the given range. It uses a hash set to keep track of previously generated numbers, ensuring that each number is unique. If it fails to generate a unique number within a certain maximum number of attempts, it throws an exception. The sequence generation method repeatedly calls the single-number generation method to build a list. Finally, you can change the seed for reproducibility using the `SetSeed` method.
']

["Here is a basic implementation in JavaScript using Promises and async/await syntax to manage asynchronous operations. 

```javascript
async function asyncReduce(streams, initialValue, callback) {
    const finalValues = [];
    let errorOccurred = false;

    for (let i = 0; i < streams.length; i++) {
        try {
            let accumulator = initialValue;
            for (const num of streams[i]) {
                accumulator = await callback(accumulator, num, i);
            }
            finalValues[i] = accumulator;
        } catch (error) {
            errorOccurred = true;
            console.log(`Error in stream ${i}: ${error}`);
        }
    }

    if (errorOccurred) {
        throw new Error('One or more reductions failed');
    } else {
        return finalValues;
    }
}
```

Here's a usage example of the `asyncReduce` function.

```javascript
const streams = [[1, 2, 3], [4, 5, 6]];
const initialValue = 0;

(async () => {
    try {
        const result = await asyncReduce(streams, initialValue, (accumulator, num, index) => {
            return new Promise((resolve, reject) => {
                setTimeout(() => {
                    if (typeof num !== 'number') {
                        reject('Invalid data type');
                    } else {
                        resolve(accumulator + num);
                    }
                }, 1000 * index); // simulate async delay based on stream index
            });
        });

        console.log(result); // [6, 15]
    } catch (error) {
        console.error('Error:', error);
    }
})();
```
In this example, we have two streams: [1,2,3] and [4,5,6]. The initial value for the reduction is 0. Our callback function simulates an asynchronous delay based on stream index (to demonstrate concurrency). It validates that each number in a stream is indeed a number and then adds it to the accumulator before resolving with the new accumulated value.
"]

