#include <stdlib.h>
#include <string.h>

char *processStringWithSizeLimit(const char *str, int limit) {
    size_t len = strlen(str);

    if (limit < 0 || limit <= len) {
        limit--; // account for null terminator

        char *newStr = malloc((limit + 2) * sizeof(char)); // +2 to account for '/' or '...', '\0'

        strncpy(newStr, str, limit);
        newStr[limit] = '\0';

        if (len > limit) {
            strcat(newStr, "...");
        } else {
            strcat(newStr, "/");
        }

        return newStr;
    } else {
        char *newStr = malloc((len + 2) * sizeof(char)); // +2 to account for '/' or '...', '\0'

        strcpy(newStr, str);

        if (str[len - 1] != '/') {
            strcat(newStr, "/");
        }

        return newStr;
    }
}
```
