using System;
using System.Security.Cryptography;
using System.IO;
using System.Threading;
using System.Text;
using Serilog; // or any other logging framework

public interface IDecrypter
{
    string Decrypt(byte[] encryptedData, byte[] key, byte[] iv);
}

public class AesCbcDecrypter : IDecrypter
{
    public string Decrypt(byte[] encryptedData, byte[] key, byte[] iv)
    {
        using (Aes aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;

            ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

            using (MemoryStream msDecrypt = new MemoryStream())
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Write))
                {
                    csDecrypt.Write(encryptedData, 0, encryptedData.Length);
                    csDecrypt.Close();
                    byte[] decryptedData = msDecrypt.ToArray();

                    return Encoding.UTF8.GetString(decryptedData);
                }
            }
        }
    }
}

public class HmacSha256Verifier : IDecrypter
{
    private readonly AesCbcDecrypter _decrypter;

    public HmacSha256Verifier(AesCbcDecrypter decrypter)
    {
        _decrypter = decrypter;
    }

    public string Decrypt(byte[] encryptedData, byte[] key, byte[] iv)
    {
        // Extract HMAC from the input data
        int hmacSize = 32; // SHA-256 hash size in bytes
        var receivedHmac = new ArraySegment<byte>(encryptedData, 0, hmacSize).ToArray();

        using (var hmac = new HMACSHA256(key))
        {
            // Calculate HMAC for the decryption input data
            byte[] calculatedHmac = hmac.ComputeHash(encryptedData, hmacSize, encryptedData.Length - hmacSize);

            if (!CompareByteArrays(receivedHmac, calculatedHmac))
                throw new CryptographicException("The received message has been tampered with!");
        }

        // Decrypt the data if HMAC is valid
        return _decrypter.Decrypt(encryptedData, key, iv);
    }

    private static bool CompareByteArrays(byte[] array1, byte[] array2)
    {
        if (array1.Length != array2.Length)
            return false;

        for (int i = 0; i < array1.Length; i++)
        {
            if (array1[i] != array2[i])
                return false;
        }

        return true;
    }
}

