import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.*;

public class SerializationUtil {
    private static final Logger logger = Logger.getLogger(SerializationUtil.class.getName());

    // Caching frequently accessed objects to improve performance
    private static Map<String, Object> objectCache = new ConcurrentHashMap<>();

    public static <T> T deserializeObject(byte[] data) throws IOException, ClassNotFoundException {
        try (ByteArrayInputStream bais = new ByteArrayInputStream(data);
             ObjectInputStream ois = new ObjectInputStream(bais)) {
            // Fetch additional metadata from an external REST API
            URL url = new URL("http://example.com/api");
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("GET");

            int status = conn.getResponseCode();
            if(status != 200){
                logger.severe("Failed to fetch metadata from API with code: " + status);
                throw new IOException("Failed to get response from API.");
            }

            InputStreamReader in = new InputStreamReader((InputStream) conn.getContent()); 
            BufferedReader buff = new BufferedReader(in);
            StringBuilder metadataStr = new StringBuilder();
            String line;

            while ((line=buff.readLine()) != null){
                metadataStr.append(line);
            }

            Map<String, Object> metadata = parseMetadata(metadataStr.toString()); // Assuming metadata is in JSON format

            // Implement a versioning strategy to handle backward compatibility gracefully
            if (metadata.containsKey("version")) {
                int version = Integer.parseInt((String) metadata.get("version"));
                switch (version){
                    case 1:
                        return readObject(ois, ClassVersionOne.class);
                    case 2:
                        return readObject(ois, ClassVersionTwo.class);
                    default:
                        logger.severe("Unsupported version: " + version);
                        throw new IOException("Unsupported class version.");
                }
            } else {
                logger.severe("No version information found in metadata");
                throw new IOException("Failed to get version from metadata.");
            }
        } catch (MalformedURLException | ProtocolException e) {
            logger.log(Level.SEVERE, "Error fetching external data", e);
            throw new IOException("Failed to fetch external data.", e);
        }
    }

    private static <T> T readObject(ObjectInputStream ois, Class<T> clazz) throws IOException, ClassNotFoundException {
        String key = clazz.getName();
        if (objectCache.containsKey(key)) {
            logger.info("Returning cached object of class " + key);
            return clazz.cast(objectCache.get(key)); // Cast is safe as we know the cache type
        } else {
            T obj = clazz.cast(ois.readObject());
            objectCache.put(key, obj);
            logger.info("Cached new object of class " + key);
            return obj;
        }
    }

    // Assuming metadata is in JSON format
    private static Map<String, Object> parseMetadata(String json){
