use std::collections::HashMap;
use tokio::sync::watch::{self, Receiver};
use tokio::time::Instant;
use tokio::task::spawn_blocking;
use log::LevelFilter;
use env_logger::Builder;
use tokio::runtime::Handle;
use std::error::Error;
use futures::stream::StreamExt;
use std::process;

type TaskResult = Result<String, Box<dyn Error>>;

fn main() {
    Builder::new().filter_level(LevelFilter::Info).init();

    let (tx, mut rx) = watch::channel(10);

    let handles = vec![spawn_task(&tx), spawn_task(&tx), spawn_task(&tx)];

    tokio::run(async {
        while let Some((result, _)) = rx.next().await {
            match result {
                TaskResult::Ok(_) => info!["Success"],
                TaskResult::Err(e) => error!["Error: {}", e],
            }
        }
    });
}

fn spawn_task(tx: &watch::Sender<TaskResult>) -> Handle {
    tokio::spawn(async move {
        let start = Instant::now();
        loop {
            let result = spawn_blocking(|| run_task()).await;
            tx.send((result, start)).unwrap();
        }
    })
}

fn run_task() -> TaskResult {
    // Insert your task logic here
    process::exit(0)
