// A global semaphore to protect concurrent access
static sem_t mutex;

void initializeAndConfigurePhyMeasurements(int measurementCount) {
    // Initialize the semaphore
    if (sem_init(&mutex, 0, 1) == -1) {
        perror("Semaphore initialization failed");
        exit(EXIT_FAILURE);
    }

    PhyMeasurementObject* measurements = malloc(sizeof(PhyMeasurementObject) * measurementCount);
    if (measurements == NULL) {
        perror("Failed to allocate memory for measurements");
        exit(EXIT_FAILURE);
    }

    // Initialize and configure each measurement object in a separate thread
    pthread_t threads[measurementCount];
    int i;
    for (i = 0; i < measurementCount; ++i) {
        if (pthread_create(&threads[i], NULL, initializeMeasurementObjectThread, &measurements[i]) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    // Join all threads and handle any errors that might occur
    for (i = 0; i < measurementCount; ++i) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Failed to join thread");
            exit(EXIT_FAILURE);
        }
    }

    // At this point, all measurements are initialized and configured. You can now use them in your code safely. 
    // Note: The semaphore is not destroyed here, as it's a global resource that should persist for the duration of your program. 
}

