['Here is an example of how you could implement this in C using the `libconfig` library to parse configuration files, the `syslog` library for logging facilities, and the `pthreads` library for handling threading operations. Note that error checking has been removed for brevity but should be added in a production-level codebase.

```c
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <pthread.h>
#include <libconfig.h>

// Define your log levels here
enum LogLevel {DEBUG, INFO, WARNING, ERROR};

typedef struct Logger {
    int log_level;
    pthread_mutex_t mutex;
} Logger;

void* initialize(char* config_file_path, enum LogLevel log_level, char* external_data_source) {
    // Create a new logger object
    Logger* logger = malloc(sizeof(Logger));

    // Initialize logging facilities using syslog
    openlog("ApplicationName", LOG_PID | LOG_CONS, LOG_USER);

    // Configure logging based on the provided log level
    setlogmask(LOG_UPTO(log_level));

    logger->log_level = log_level;

    // Parse configuration file and set options
    config_t cfg;
    config_init(&cfg);

    if(!config_read_file(&cfg, config_file_path)) {
        syslog(LOG_ERR, "Error opening configuration file: %s:%d - %s", config_error_file(&cfg), 
               config_error_line(&cfg), config_error_text(&cfg));
        exit(EXIT_FAILURE);
    }

    // Initialize mutex for thread-safe logging
    if (pthread_mutex_init(&logger->mutex, NULL) != 0) { 
        syslog(LOG_ERR,"Failed to initialize mutex"); 
        exit(EXIT_FAILURE); 
    } 

    // Clean up and return the logger object pointer
    config_destroy(&cfg);

    return (void*)logger;
}

int logMessage(Logger* logger, int level, const char *message) {
    pthread_mutex_lock(&logger->mutex);
    syslog(level, "%s", message);
    pthread_mutex_unlock(&logger->mutex);

    return 0;
}
```
In this example, `initialize` function takes a configuration file path (`config_file_path`), a log level (`log_level`), and an external data source identifier as parameters. It then initializes logging facilities using syslog library with the provided log level, parses the configuration file, initializes a mutex for thread-safe logging operations, and returns the logger object pointer. 

The `logMessage` function is used to log messages in a thread-safe manner. It locks the mutex before writing the message and unlocks it after. This ensures that multiple threads can write their logs concurrently without corrupting each other's output.
']

