// Custom allocator
void *custom_alloc(size_t size) {
    assert(size <= INT_MAX); // Check for integer overflow
    if (size == 0) return NULL;

    void *ptr = malloc(size);
    if (!ptr) {
        printf("Memory allocation failed!");
        exit(EXIT_FAILURE);
    }

    memset(ptr, 0, size); // Initialize allocated memory to zero
    return ptr;
}

void *custom_realloc(void *ptr, size_t newSize) {
    assert(newSize <= INT_MAX); // Check for integer overflow

    void *newPtr = realloc(ptr, newSize);
    if (!newPtr && newSize != 0) {
        printf("Memory allocation failed!");
        free(ptr);
        exit(EXIT_FAILURE);
    }

    return newPtr;
}

void custom_free(void *ptr) {
    free(ptr);
}

// Thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

record* allocateAndInitRecordArray(int size, int (*genValue)(void), float (*genScore)(void)) {
    pthread_mutex_lock(&mutex); // Lock to ensure thread safety

    record* array = custom_alloc(size * sizeof(record));
    if (!array) {
