["Here is a basic C implementation using a LRU (Least Recently Used) Cache for your scenario. This code doesn't cover all the aspects you mentioned, but it should give you a good starting point for developing a more robust solution. For example, this program doesn't implement network communication and data corruption handling, which is crucial in real-world applications. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct CacheNode {
    float* data;
    size_t size;
    struct CacheNode *prev, *next;
} CacheNode;

CacheNode* head = NULL;
CacheNode* tail = NULL;
int cacheSize = 10; // define your own appropriate cache size. 
pthread_mutex_t lock;

void cacheData(float data[], size_t n) {
    pthread_mutex_lock(&lock);

    CacheNode* node = (CacheNode*)malloc(sizeof(CacheNode));
    node->data = malloc(n * sizeof(float));
    for (int i = 0; i < n; ++i) {
        node->data[i] = data[i];
    }
    node->size = n;
    node->next = head;
    node->prev = NULL;

    if(head != NULL){
        head->prev = node;
    }
    head = node;

    if(tail == NULL){
        tail = head;
    }

    // Check if we exceeded the cache size and remove least recently used item. 
    if((int)CacheNode_size() > cacheSize){
        CacheNode* temp = tail;
        tail = tail->prev;
        if(tail != NULL){
            tail->next = NULL;
        }

        free(temp->data); 
        free(temp);
    }

    pthread_mutex_unlock(&lock);
}

size_t CacheNode_size(){
    size_t count = 0;
    CacheNode* temp = head;
    while(temp){
        count += temp->size; 
        temp = temp->next;
    }

    return count;
}

float findSmallest(CacheNode *node) {
    float min_value = node->data[0];

    for (int i = 1; i < node->size; ++i) {
        if (node->data[i] < min_value) {
            min_value = node->data[i];
        }
    }

    return min_value;
}

float findLargest(CacheNode *node) {
    float max_value = node->data[0];

    for (int i = 1; i < node->size; ++i) {
        if (node->data[i] > max_value) {
            max_value = node->data[i];
        }
    }

    return max_value;
}
``` 

