    if (head == NULL) return NULL;

    pthread_mutex_lock(&lock); // thread-safe operation

    NFAPI_MESSAGE_T *msg = head->message; 

    removeMessage();

    pthread_mutex_unlock(&lock); // thread-safe operation

    return msg;
}
