Please note that the implementation may need some adjustment based on the specific application needs, as well as performance testing to ensure it meets latency constraints. Also remember to replace the hardcoded values with your own ones. 

```C
#include <openssl/evp.h>
#include <openssl/aes.h>
#include <openssl/rand.h>
#include <string.h>

#define SALT_SIZE 8
#define IV_LEN EVP_MAX_IV_LENGTH

typedef struct {
    unsigned char *key;
    unsigned char iv[IV_LEN];
} EncryptionKeys;

// Helper function to derive key and IV from password
int deriveKeyAndIv(const char* password, const unsigned char* salt, int iterations, int keyLength, EncryptionKeys* keys) {
    // Initialize OpenSSL context
    EVP_MD_CTX *mdctx = EVP_MD_CTX_new();
    if (!EVP_DigestInit_ex(mdctx, EVP_sha256(), NULL)) return 0;

    unsigned char key[keyLength];
    int currentIterations = 0;

    // Derive the key and IV using PBKDF2
    while (currentIterations <= iterations) {
        if (!EVP_DigestUpdate(mdctx, password, strlen(password))) return 0;
        if (!EVP_DigestUpdate(mdctx, salt, SALT_SIZE)) return 0;

        unsigned char out[EVP_MAX_MD_SIZE];
        unsigned int outLen = 0;
        if (!EVP_DigestFinal_ex(mdctx, out, &outLen)) return 0;
        memcpy(key + currentIterations * EVP_MAX_MD_SIZE, out, outLen);
        ++currentIterations;
    }

    // Assign derived key and IV to the struct
    keys->key = malloc(keyLength);
    memcpy(keys->key, key, keyLength);
    RAND_bytes(keys->iv, IV_LEN);

    EVP_MD_CTX_free(mdctx);

    return 1;
}

// Function to encrypt/decrypt data using AES-256-CBC cipher
int processDataBlock(const unsigned char* in, size_t inLen, unsigned char* out, EncryptionKeys* keys, int operation) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

    if (!EVP_CipherInit_ex(ctx, EVP_aes_256_cbc(), NULL, keys->key, keys->iv, operation)) return 0;

    int outLen = 0;
    if (!EVP_CipherUpdate(ctx, out, &outLen, in, inLen)) return 0;

    EVP_CIPHER_CTX_free(ctx);

    return outLen;
}

// Function to initialize an AES-256-CBC cipher with PBKDF2 derived key and IV.
int initAesEncryption(const char* password, EncryptionKeys* keys) {
    unsigned char salt[SALT_SIZE];

    // Generate a random salt value for PBKDF2
    RAND_bytes(salt, SALT_SIZE);

    if (!deriveKeyAndIv(password, salt, 10000, 32, keys)) return 0; // Assuming key length is 32 bytes. Adjust this value as per your needs.

    return 1;
}
```

