['Here's a basic structure for your function:

```c
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>
#include <pthread.h>

// Assuming there is a graph database API that we're using
extern int add_vertex(int properties[], size_t n);
extern int add_edge(int vertex1, int vertex2, int properties[], size_t n);

static volatile sig_atomic_t child_exit = 0;
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void handle_sigterm(int signal) {
    if (signal == SIGTERM && !child_exit) {
        _exit(EXIT_SUCCESS);
    }
}

void* exec_cmd(void *arg) {
    char **command = (char **) arg;
    pthread_mutex_lock(&lock);
    if (!fork()) {
        struct sigaction action;
        action.sa_handler = handle_sigterm;
        sigemptyset(&action.sa_mask);
        action.sa_flags = 0;
        sigaction(SIGTERM, &action, NULL);

        if (execvp(*command, command) < 0) {
            perror("exec failed");
            _exit(EXIT_FAILURE);
        }
    } else {
        int status = 0;
        wait(&status);
        child_exit = WIFEXITED(status);
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

int add_to_graph(char *command[], int properties[], size_t n) {
    signal(SIGCHLD, SIG_IGN);

    pthread_t thread;
    if (pthread_create(&thread, NULL, exec_cmd, command)) {
        return 0; // failed to start thread
    }

    int result = add_vertex(properties, n) && add_edge(0, 1, properties, n);

    pthread_join(thread, NULL);

    signal(SIGCHLD, SIG_DFL);

    return child_exit && result;
}
```

Please replace the `add_vertex` and `add_edge` functions with your actual graph database API calls. 

