["Here's how you might approach this task using the `axios` library for HTTP requests and the built-in ES6 `Promise` object to handle async operations:

```javascript
const axios = require('axios');
const { URL } = require('url');

class CloudStorageUploader {
  constructor(apiUrl, supportedFileTypes) {
    this.apiUrl = apiUrl;
    this.supportedFileTypes = new Set(supportedFileTypes);
    // you can add more properties here to track progress and other data if needed
  }

  async uploadFiles(filesToUpload) {
    const promises = filesToUpload.map(file => this._uploadSingleFile(file));

    return Promise.allSettled(promises).then((results) => {
      // filter and map the results to get only successful URLs
      const successUrls = results
        .filter(result => result.status === 'fulfilled')
        .map(result => result.value);

      if (successUrls.length < filesToUpload.length) {
        // some uploads failed, reject the promise with details
        const errors = results
          .filter(result => result.status !== 'fulfilled')
          .map(result => `Failed to upload file: ${result.reason}`);

        return Promise.reject(errors);
      }

      // all files uploaded successfully, resolve the promise with URLs
      return Promise.resolve(successUrls);
    });
  }

  async _uploadSingleFile({ url, size, urgent }) {
    const fileUrl = new URL(url);

    if (!this.supportedFileTypes.has(fileUrl.pathname.split('.').pop())) {
      throw new Error(`Unsupported file type: ${fileUrl.pathname}`);
    }

    // use `axios` to upload the file
