public class CommandExecutor {
    private final String FILE_PATH = "path/to/file";
    private final String COMMAND = "command_to_execute";
    private final String WORKING_DIRECTORY = "working_directory";

    private ExternalAPIClient apiClient;
    private ExecutorService executorService;

    public CommandExecutor() {
        this.apiClient = new ExternalAPIClient();
        this.executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    }

    public void executeCommands(int commandCount) throws IOException, InterruptedException, ExecutionException {
        File file = new File(FILE_PATH);

        if (file.exists()) {
            if (!file.delete()) {
                throw new IOException("Failed to delete file: " + FILE_PATH);
            }
        }

        List<Future<NFAPI_CRC_INDICATION_PDU_T>> futures = new ArrayList<>();

        for (int i = 0; i < commandCount; ++i) {
            NFAPI_CRC_INDICATION_PDU_T pdu = createPDUTag(apiClient.fetchData());

            Process process = Runtime.getRuntime().exec(COMMAND, null, new File(WORKING_DIRECTORY));
            Future<NFAPI_CRC_INDICATION_PDU_T> future = executorService.submit(() -> {
                int exitCode = process.waitFor();

                if (exitCode != 0) {
                    throw new IOException("Command execution failed with code: " + exitCode);
                }

                return pdu;
            });

            futures.add(future);
        }

        for (Future<NFAPI_CRC_INDICATION_PDU_T> future : futures) {
            System.out.println("Processed: " + future.get());
        }
    }

