// Structure representing the configuration file
typedef struct {
    int offset_size;
    int key_size;
    int record_size;
} Config;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // Lock for thread safety
FILE* errlog = NULL; // Error log file handle
sqlite3 *db; // Database connection
char *zErrMsg = 0; // SQL error message
int rc; // Return code from SQL operations

// Function to load the configuration
Config* load_config(const char* filename) {
    Config* config = malloc(sizeof(Config));

    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        pthread_mutex_lock(&lock);
        fprintf(errlog, "Failed to open configuration file\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Parse the config file and fill the Config structure
    fscanf(file, "%d %d %d", &config->offset_size, &config->key_size, &config->record_size);

    fclose(file);
    return config;
}

// Function to initialize an array with unique values within a given range
int* init_array(int size, int min, int max) {
    // ... code here for generating and initializing the array safely
}

void *startup_routine() {
    pthread_mutex_lock(&lock);

    Config* config = load_config("config.txt");
    if (config == NULL) {
        return NULL; // Exit on error
    }

    int* offset_array = init_array(config->offset_size, 1, 10);
    int* key_array = init_array(config->key_size, 1, 10);
    int* record_array = init_array(config->record_size, 1, 10);

    // SQL query and its parameters
    char *sql = "SELECT name, city, address FROM Employees WHERE supervisorID=?";

    rc = sqlite3_open("employee.db", &db);
    if(rc) {
        pthread_mutex_lock(&lock);
        fprintf(errlog, "Can't open database: %s\n", sqlite3_errmsg(db));
        pthread_mutex_unlock(&lock);
        return NULL; // Exit on error
    } 

    rc = sqlite3_prepare_v2(db, sql, -1, &stmt, 0);
    if(rc != SQLITE_OK) {
        pthread_mutex_lock(&lock);
        fprintf(errlog, "SQL error: %s\n", zErrMsg);
        sqlite3_free(zErrMsg);
        pthread_mutex_unlock(&lock);
        return NULL; // Exit on error
    } 

    // Bind parameter and execute the SQL query
    int supervisorID = getenv("supervisorID");
    sqlite3_bind_int(stmt, 1, supervisorID);
    rc = sqlite3_step(stmt);

    if(rc != SQLITE_ROW) {
        pthread_mutex_lock(&lock);
        fprintf(errlog, "No such data\n");
        pthread_mutex_unlock(&lock);
        return NULL; // Exit on error
    } 

    // Display the SQL query and result set
    printf("SQL Query: %s %d\n", sql, supervisorID);
    printf("Result Set: %s | %s | %s\n", sqlite3_column_text(stmt, 0), sqlite3_column_text(stmt, 1), sqlite3_column_text(stmt, 2));

    // Cleanup resources and exit safely
    free(config);
    free(offset_array);
    free(key_array);
    free(record_array);
    sqlite3_finalize(stmt);
    sqlite3_close(db);
    pthread_mutex_unlock(&lock);

    return NULL; // End the thread
}
```

This is a simplified example and real-world implementations will require much more comprehensive handling of errors, potential inconsistencies, and concurrency issues. For instance, you might want to use a connection pool to manage database connections for better performance under high load, and employ strategies for memory fragmentation minimization to optimize data retrieval speed. Also, consider using secure methods like hashed passwords or access tokens to enhance the security of your application.
