```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#define MAX_MEMORY 1024*1024 // Specify the maximum memory limit in bytes
typedef struct NFAPI_RRC_MESSAGE_T {
    int UEID;
    void *PDCP_PDU;
} NFAPI_RRC_MESSAGE_T;

typedef struct dynamicArray {
    NFAPI_RRC_MESSAGE_T **array;
    size_t used;
    size_t size;
    pthread_mutex_t lock;
} dynamicArray;

void initArray(dynamicArray *a, size_t initialSize) {
    a->array = (NFAPI_RRC_MESSAGE_T **)malloc(initialSize * sizeof(NFAPI_RRC_MESSAGE_T*));
    a->used = 0;
    a->size = initialSize;
    pthread_mutex_init(&a->lock, NULL);
}
void insertArray(dynamicArray *a, NFAPI_RRC_MESSAGE_T *element) {
    if (pthread_mutex_lock(&a->lock)) {
        perror("Failed to acquire lock");
        return;
    }
    if (a->used == a->size) {
        a->size *= 2;
        if ((a->array = (NFAPI_RRC_MESSAGE_T **)realloc(a->array, a->size * sizeof(NFAPI_RRC_MESSAGE_T*))) == NULL){
            perror("Failed to reallocate memory");
            pthread_mutex_unlock(&a->lock);
            return;
        } 
    }
    if (a->used * sizeof(NFAPI_RRC_MESSAGE_T) > MAX_MEMORY){
       printf("Maximum memory limit reached.\n");
       pthread_mutex_unlock(&a->lock);
       return;
    }

    a->array[a->used++] = element;
    if (pthread_mutex_unlock(&a->lock)) {
        perror("Failed to release lock");
        return;
    }
}
NFAPI_RRC_MESSAGE_T *getByUEID(dynamicArray *a, int UEID) {
    for (int i = 0; i < a->used; i++) {
        if (a->array[i]->UEID == UEID){
            return a->array[i];
        }
    }
    printf("No message with the given UE ID found.\n");
    return NULL; 
}
void updateByUEID(dynamicArray *a, int UEID, void* newPDCP_PDU) {
    for (int i = 0; i < a->used; i++) {
        if (a->array[i]->UEID == UEID){
            a->array[i]->PDCP_PDU = newPDCP_PDU;
            return;
        }
    }
    printf("No message with the given UE ID found.\n");
}
