["Here is a sample code block that fulfills your requirements. The function `loadFilesAndHashPassword` takes an array of file names, an optional config object, and a callback function to handle errors. It manages loading files in parallel but ensures they are only loaded once using a Set to keep track of already loaded files:

```javascript
import crypto from 'crypto';
const loadedFiles = new Set();

function loadAndExecute(file) {
    return new Promise((resolve, reject) => {
        if (loadedFiles.has(file)) {
            resolve();
            return;
        }
        const scriptTag = document.createElement('script');
        scriptTag.src = file;
        scriptTag.onload = () => {
            loadedFiles.add(file);
            resolve();
        };
        scriptTag.onerror = reject;
        document.head.appendChild(scriptTag);
    });
}

function generateRandomString(length, charset) {
    let result = '';
    const charactersLength = charset.length;
    for (let i = 0; i < length; i++) {
        result += charset.charAt(Math.floor(Math.random() * charactersLength));
    }
    return result;
}

function hashPasswordWithRandomString(password, config = {}) {
    const {
        length = 32,
        charset = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789',
        algorithm = 'sha256'
    } = config;
    const randomString = generateRandomString(length, charset);
    const hashedPassword = crypto.createHmac(algorithm, randomString).update(password).digest('hex');
    return {hashedPassword, randomString};
}

function loadFilesAndHashPassword(files, config, callback) {
    Promise.allSettled(files.map(file => loadAndExecute(file)))
        .then(() => {
            const {password, ...restConfig} = config;
            if (!password) throw new Error('Missing password');
            const result = hashPasswordWithRandomString(password, restConfig);
            callback(null, result);
        })
        .catch((error) => {
            console.log(`Failed to load file: ${files} - Reason: ${error}`);
            callback(error);
        });
