            return;

        var fileContent = await this.httpClient.GetStringAsync(url);
        this.fileCache[url] = fileContent;
    }

    public List<int> GenerateRandomNumbersWithinRange(int start, int end, bool includeEndpoints)
    {
        if (start > end)
            throw new ArgumentException("Invalid range inputs!");

        var numbers = new List<int>();
        var randomNumberGenerator = new Random.RandomNumberGenerator();

        while(numbers.Count < end - start + 1)
        {
            int number = randomNumberGenerator.GenerateRandomInt(start, includeEndpoints ? end : end - 1);

            if (!numbers.Contains(number))
                numbers.Add(number);
        }

        return numbers;
    }

    public override string ToString()
