```c
#include <stdio.h>
#include <pthread.h>

typedef struct {
    // structure definition...
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;  // mutex for thread safety

// Function to add a new element to the array.
void addElement(NFAPI_CRC_INDICATION_PDU_T* arr, size_t *size, NFAPI_CRC_INDICATION_PDU_T newElem) {
    pthread_mutex_lock(&lock);  // acquire lock

    // Check if RNTI is unique.
    for (int i = 0; i < *size; i++) {
        if (arr[i].RNTI == newElem.RNTI) {
            printf("Error: Attempted to add a structure with a non-unique RNTI.\n");
            pthread_mutex_unlock(&lock);  // release lock
            return;
        }
    }

    // Reallocate array and add new element.
    arr = realloc(arr, (*size + 1) * sizeof(*arr));
    arr[*size] = newElem;
    (*size)++;

    printf("Added element with RNTI %d.\n", newElem.RNTI);  // Logging operation

    pthread_mutex_unlock(&lock);  // release lock
}

// Function to update an existing element in the array.
void updateElement(NFAPI_CRC_INDICATION_PDU_T* arr, size_t size, NFAPI_CRC_INDICATION_PDU_T newElem) {
    pthread_mutex_lock(&lock);  // acquire lock

    for (int i = 0; i < size; i++) {
        if (arr[i].RNTI == newElem.RNTI) {
            arr[i] = newElem;  // Update element.

            printf("Updated element with RNTI %d.\n", newElem.RNTI);  // Logging operation

            break;
        }
    }

    pthread_mutex_unlock(&lock);  // release lock
}

// Function to remove an element from the array.
void removeElement(NFAPI_CRC_INDICATION_PDU_T* arr, size_t *size, int rnti) {
    pthread_mutex_lock(&lock);  // acquire lock

    for (int i = 0; i < *size; i++) {
        if (arr[i].RNTI == rnti) {
            memmove(arr + i, arr + i + 1, (*size - i - 1) * sizeof(*arr));  // Shift elements.

            printf("Removed element with RNTI %d.\n", rnti);  // Logging operation

            break;
        }
    }

    (*size)--;
    arr = realloc(arr, *size * sizeof(*arr));  // Resize array.

    pthread_mutex_unlock(&lock);  // release lock
}
```
