void generateData(double** doubles, char** bytes, Data** objects, 
                  size_t count, RNGFunc rng, 
                  float minValue, float maxValue) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    *doubles = (double*) malloc(count * sizeof(double));
    if(*doubles == NULL) exit(1);

    *bytes = (char*) calloc(count, 1); // Allocate and initialize to zero
    if(*bytes == NULL) exit(2);

    *objects = (Data*) malloc(count * sizeof(Data));
    if(*objects == NULL) exit(3);

    for(size_t i = 0; i < count; ++i){
        float value;
        do {
            pthread_mutex_lock(&lock); // Lock to ensure thread safety
            value = rng(minValue, maxValue); 
            pthread_mutex_unlock(&lock); // Unlock after we are done with it
        } while (checkIfExists(*objects, i, value)); // Ensure no two objects have the same float value

        (*doubles)[i] = (double) value;
        (*bytes)[i] = (char) value;
        (*objects)[i].value = value;
        (*objects)[i].index = i;
    }
}
```

