#include <stdexcept>

std::mutex mtx;
std::condition_variable cv;
std::atomic<bool> ready(false);
std::vector<int> data;
std::thread workerThread;

// Assuming input stream as a vector of integers.
void readDataFromNetwork(const std::vector<int>& stream) {
    std::lock_guard<std::mutex> lg(mtx); // Ensure thread-safety.

    for (auto num : stream) {
        if (!ready && num < 0) { // Assume malformed data as negative integers.
            throw std::runtime_error("Malformed data encountered!");
        } else {
            data.push_back(num);
        }
    }

    ready = true;
    cv.notify_all();
}

// Assuming network latency as a vector of integers for simplicity here.
void workerThreadFunction() { 
    std::unique_lock<std::mutex> ul(mtx); // Ensure thread-safety.

    cv.wait(ul, [](){ return ready.load(); }); // Wait until data is ready.

    int max = *max_element(data.begin(), data.end()); 
    double average = std::accumulate(data.begin(), data.end(), 0) / (double) data.size();

    ul.unlock(); // Unlock mutex before proceeding.
    processData(max, average); // Assuming a function that processes the max and average values.
}

void startProcessing() {
    workerThread = std::thread(workerThreadFunction); 
}
```
