    ++queryCount;

    if (difftime(time(NULL), startTime) > 60.0) {  // Reset every minute. Adjust as needed.
        queryCount = 1;
        startTime = time(NULL);
    } else if (queryCount > 100) {  // Rate limit: max 100 queries per minute. Adjust as needed.
        pthread_mutex_unlock(&lock);
        return CURLE_COULDNT_RESOLVE_HOST;
    }

    pthread_mutex_unlock(&lock);

    // Perform the request and check the response.
    CURLcode res = curl_easy_perform(curl);

    if (res != CURLE_OK) {
