["This task is quite complex and the provided instructions are rather high-level and broad. It's not clear how much of this work should be implemented here in one block due to a lack of details. However, I can provide an example of how you might allocate memory for your arrays, manage concurrency, initialize records with random values, and release allocated memory safely:

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record *records;
    pthread_mutex_t lock;
    size_t allocated;
} ArrayContainer;

ArrayContainer* allocateArrays(size_t size) {
    if (size <= 0 || size > SIZE_MAX / 3 / sizeof(long)) return NULL; // validate sizes

    ArrayContainer *container = malloc(sizeof(*container));
    if (!container) return NULL; // allocation failed

    container->offsets = malloc(size * sizeof(*container->offsets));
    container->keys = malloc(size * sizeof(*container->keys));
    container->records = malloc(size * sizeof(*container->records));

    if (!container->offsets || !container->keys || !container->records) { // allocation failed
        freeArrays(container);
        return NULL;
    }

    container->allocated = size;
    pthread_mutex_init(&container->lock, NULL); // initialize mutex

    srand(time(NULL)); // seed random number generator
    for (size_t i = 0; i < size; ++i) {
        container->records[i].value = rand(); // random value in [0, RAND_MAX]
    }

    return container;
}

void freeArrays(ArrayContainer *container) {
    if (!container) return; // NULL pointer check

    pthread_mutex_lock(&container->lock); // lock mutex before cleaning up

    free(container->offsets);
    container->offsets = NULL; // clear pointers to prevent dangling references after free

    free(container->keys);
    container->keys = NULL;

    free(container->records);
    container->records = NULL;

    pthread_mutex_unlock(&container->lock); // unlock mutex before destroy to prevent undefined behavior
    pthread_mutex_destroy(&container->lock);

    free(container);
}
```

In this code, `allocateArrays` dynamically allocates and initializes the arrays using `malloc`. It also uses a mutex for thread synchronization. The `freeArrays` function safely releases all allocated memory by locking the mutex before freeing the arrays and destroying the mutex afterwards to prevent undefined behavior when destroying a locked mutex.

Please specify in more detail what you want this function to do if you need it to include features like real-world usage patterns, efficient memory management or flexible data types for offsets and keys.
