['Here is a basic implementation in C language for your task. It uses standard libraries for dynamic memory allocation (malloc, realloc), rand function for random shuffling and time function for random seed generation. This is just one possible solution, it can be optimized based on specific requirements or constraints.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    double num;
    char *str;
} dataRecord;

void shuffle(dataRecord *array, int n) {
    if (n > 1) {
        srand(time(NULL));

        for (int i = 0; i < n - 1; ++i) {
            size_t rnd = (size_t) rand();
            size_t j = i + rnd / (RAND_MAX / (n - i) + 1);

            dataRecord t = array[j];
            array[j] = array[i];
            array[i] = t;
        }
    }
}

dataRecord* allocateArray(int numElements, int sizeOfStruct) {
    dataRecord *array = (dataRecord*) malloc(numElements * sizeOfStruct);

    if (!array) {
        printf("Memory allocation failed!\n");
        exit(-1);
    }

    // Initialize with default values.
    for (int i = 0; i < numElements; ++i) {
        array[i].num = 0.0;
        array[i].str = NULL;
    }

    return array;
}

void freeArray(dataRecord *array, int sizeOfStruct) {
    for (int i = 0; i < sizeOfStruct; ++i) {
        if (array[i].str != NULL) {
            free(array[i].str);
        }
    }

    free(array);
}

void updateElement(dataRecord *element, double newNum, char* newStr) {
    if (newStr && strlen(newStr) > 0) {
        // Allocate and copy the string.
        element->str = (char*) malloc(sizeof(char) * (strlen(newStr) + 1));

        if (!element->str) {
            printf("Memory allocation failed for string!\n");
            exit(-2);
        }

        strcpy(element->str, newStr);
    } else {
        element->str = NULL;
    }

    element->num = newNum;
}

int main() {
    const int numElements = 10;
    dataRecord *array = allocateArray(numElements, sizeof(dataRecord));

    // Update elements.
    for (int i = 0; i < numElements; ++i) {
        updateElement(&array[i], i + 0.5, "Hello");
    }

    shuffle(array, numElements);

    freeArray(array, numElements);

    return 0;
}
```

This code does not implement dynamic resizing of the array due to its complexity and potential implications on cache performance. To support this feature would require implementing a separate structure that holds both an array and its current capacity and size information and providing functions for checking if the array is full or needs to be expanded, reallocating memory when necessary, copying old data over after resizing etc.
