    private static final String POKEMON_API = "https://pokeapi.co/api/v2/pokemon";

    @Autowired
    private RestTemplate restTemplate;

    public Map<String, List<String>> getPokemonWeaknesses() {
        HttpHeaders headers = new HttpHeaders();
        headers.setAccept(Arrays.asList(MediaType.APPLICATION_JSON));

        HttpEntity<String> entity = new HttpEntity<>(headers);

        ResponseEntity<PokemonResponse[]> response 
            = restTemplate.exchange(POKEMON_API, HttpMethod.GET, entity, PokemonResponse[].class);

        List<PokemonResponse> pokemons = Arrays.asList(response.getBody());

        Map<String, List<String>> weaknessesMap = new HashMap<>();

        for (PokemonResponse p : pokemons) {
            String weaknesses;

            // Switch case based on Pokemon's type to determine its weaknesses.
            switch(p.getType()) {
                case "fire": 
                    weaknesses = "water, ground, rock";
                    break;
                case "water": 
                    weaknesses = "electric, grass";
                    break;
                //... Add more cases here based on Pokemon types.
                default: 
                    weaknesses = "unknown";
            }

            weaknessesMap.put(p.getName(), Arrays.asList(weaknesses.split(",")));
        }

        return weaknessesMap;
    }
}
