public class SqlExecutor
{
    private static readonly Logger logger = LogManager.GetCurrentClassLogger();

    public void ExecuteCommand(string connectionString, string commandText, Dictionary<string, object> parameters)
    {
        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            connection.Open();
            using (SqlTransaction transaction = connection.BeginTransaction())
            {
                try
                {
                    using (SqlCommand command = new SqlCommand(commandText, connection, transaction))
                    {
                        foreach (var parameter in parameters)
                        {
                            command.Parameters.AddWithValue(parameter.Key, parameter.Value);
                        }

                        // log the SQL command and its parameters for auditing purposes
                        logger.Info("SQL Command: {0}, Parameters: {1}", commandText, SanitizeParametersForLogging(parameters));

                        command.ExecuteNonQuery();
                    }

                    transaction.Commit();
                }
                catch (SqlException ex)
                {
                    logger.Error("SQL Error: ", ex);
                    transaction.Rollback();
                }
            }
        }
    }

    private Dictionary<string, object> SanitizeParametersForLogging(Dictionary<string, object> parameters)
    {
        // replace this with your actual logic for sanitizing parameters
        return parameters; 
    }
}
```
This code uses ADO.NET SqlClient to execute SQL commands. Parameters are added one by one using the AddWithValue method of the command object, which automatically handles type checking and conversion. The ExecuteNonQuery method is used for executing non-query commands like INSERT or UPDATE, returning the number of affected rows.

Logging is performed via NLog in this example, but you should replace it with your actual logging framework. Error handling catches SQL exceptions and rolls back the transaction to maintain atomicity in case of failure.

