// Assuming we have already defined the regex patterns for all books in the old testament
let OLD_TESTAMENT_BOOKS = {
    "Genesis": /\bgenesis\b/i,
    // ... rest of books
};

class BibleBookProcessor {
  constructor() {
    this.cache = {};
    this.logger = console; // replace with your logger, like 'winston'
  }

  processDocument(document) {
    if (this.cache[document]) return this.cache[document];

    let result = {};
    for (let book in OLD_TESTAMENT_BOOKS) {
      let count = (document.match(OLD_TESTAMENT_BOOKS[book]) || []).length;
      if (count > 0) result[book] = count;
