["This is a complex task that requires careful consideration of different aspects like concurrency, memory management, and API integration. Here's a simple implementation using Node.js streams to handle high throughput data, a Set for deduplication, and native promises for asynchronous operations:

```javascript
const fetch = require('node-fetch');
const { Transform } = require('stream');
let currentData = new Set();
let isPaused = false;

class DataProcessor extends Transform {
    constructor(uniqueId, deduplicationInterval) {
        super({ objectMode: true });
        this.uniqueId = uniqueId;
        this.deduplicationInterval = deduplicationInterval * 1000; // convert to milliseconds
        setInterval(() => this.currentData.clear(), this.deduplicationInterval);
    }

    _transform(chunk, encoding, callback) {
        if (!isPaused && !this.currentData.has(chunk[this.uniqueId]) && Date.now() - chunk.timestamp < this.deduplicationInterval) {
            this.push(chunk);
            this.currentData.add(chunk[this.uniqueId]);
        }
        callback();
    }
}

class APIStreamer {
    constructor(url, uniqueId, deduplicationInterval, bufferSize) {
        this.url = url;
        this.uniqueId = uniqueId;
        this.deduplicationInterval = deduplicationInterval;
        this.bufferSize = bufferSize;
    }

    fetchData() {
        return new Promise((resolve, reject) => {
            if (!isPaused) {
                fetch(this.url)
                    .then(response => response.json())
                    .then(data => {
                        const processor = new DataProcessor(this.uniqueId, this.deduplicationInterval);
                        data.pipe(processor).on('error', reject).on('end', resolve);
                    })
                    .catch(reject);
            } else {
                setTimeout(() => this.fetchData().then(resolve).catch(reject), 1000); // wait and try again if paused
            }
        });
    }

    pause() {
        isPaused = true;
    }

    resume() {
        isPaused = false;
    }
}
```

You would need to integrate with an external database and handle potential network disruptions based on your exact requirements, which are not covered by this simplified implementation. Please note that Node.js streams may not be optimal for real-time applications due to backpressure management. For such use cases, you should consider using a more sophisticated solution or an existing stream processing library. Also, the decision about buffer size and deduplication interval must be made based on your requirements and testing different configurations to find the best balance between efficiency and data fidelity.
