["Here is a simple implementation using JavaScript with async/await and Promises, which allows handling up to 10 concurrent requests efficiently by using Promise.all():

```js
const fetch = require('node-fetch'); // Assuming we're in a Node environment here.

class DOMTraverser {
    constructor(apiUrl) {
        this.cache = new Map(); // Cache to avoid unnecessary API calls
        this.apiUrl = apiUrl; 
    }

    async getMetadataForElement(element) {
        const cacheKey = `${this.apiUrl}/${element.id}`;

        if (this.cache.has(cacheKey)) return this.cache.get(cacheKey); // Return from cache if available

        try {
            const response = await fetch(cacheKey);

            if (!response.ok) throw new Error('Failed to fetch metadata');

            const data = await response.json();

            this.cache.set(cacheKey, data); // Store in cache for subsequent requests

            return data; 
        } catch (err) {
            console.error(`Error fetching metadata: ${err}`);
            return null; // Return null if fetch fails or times out
        }
    }

    async getElementsWithMetadata(selector, depth = 0) {
        const elements = Array.from(document.querySelectorAll(selector)); 

        // If we have exhausted the maximum depth, return elements without metadata
        if (depth >= 10 || elements.length === 0) return Promise.all(elements.map(element => element));

        // Retrieve metadata in parallel for each element 
        const promises = elements.map((element) => 
            this.getMetadataForElement(element).then((metadata) => {
                if (metadata) {
                    element.metadata = metadata;
                    return element;
                } else {
                    console.error('Failed to fetch metadata'); 
                    return null; // Return null for elements where fetching metadata failed
                }
            })
        );

        const results = await Promise.all(promises);

        return results.filter((element) => element !== null); // Remove any elements where fetching metadata failed
    }
}
```

Please note that this is a very simple implementation, and does not handle many edge cases (like what happens if the API starts returning errors for valid requests due to overload). It also assumes an external API which can fetch additional metadata for each element by its id. Please replace 'node-fetch' with your preferred way of making HTTP requests in Node or browser environments.
