```java
import android.graphics.Bitmap;
import android.util.LruCache;

public class BitmapCache {
    private LruCache<String, Bitmap> memoryCache;

    public BitmapCache(int maxMemory) {
        int cacheSize = maxMemory / 8;

        memoryCache = new LruCache<String, Bitmap>(cacheSize) {
            @Override
            protected int sizeOf(String key, Bitmap bitmap) {
                return bitmap.getByteCount() / 1024;
            }
        };
    }

    public void addBitmapToMemoryCache(String key, Bitmap bitmap) {
        if (getBitmapFromMemCache(key) == null) {
            memoryCache.put(key, bitmap);
        }
    }

    public Bitmap getBitmapFromMemCache(String key) {
        return memoryCache.get(key);
    }
}
```
This code uses Android's LruCache class to implement a basic caching mechanism for theme bitmaps in an Android application. When a bitmap is added, the `addBitmapToMemoryCache()` method checks if it already exists in the cache before adding it. The `getBitmapFromMemCache()` method retrieves a bitmap from the cache if it's available.

