public final class ByteUtils {
    private ByteUtils() {} // Prevents instantiation

    public static byte[] copyBytes(byte[] source, int count) throws IOException {
        if (source.length < count) throw new IOException("Not enough data to copy");

        byte[] destination = new byte[count];
        System.arraycopy(source, 0, destination, 0, count);
        return destination;
    }
}
