```rust
use std::time::{Instant, Duration};
use std::os::unix::io::RawFd;
use libc::getrusage;
use libc::RUSAGE_SELF;
use libc::size_t;
use rustc_driver::catch_with_exit_code;
use log::error;

fn compile() -> Result<i32, String> {
    let before = measure_resident_set_size();

    // Assume a function `compile_rust` which handles the actual compilation process.
    let start = Instant::now();
    let exit_code: i32;
    catch_with_exit_code(|| {
        compile_rust()?;
        Ok(0)
    }).map_err(|e| {
        error::<sync::Mutex<Vec<String>>>(&format::args());
        1
    })?;
    let duration = start.elapsed();

    let after = measure_resident_set_size();
    println::<i32>(&format::args(), (after - before));
    Ok(exit_code)
}

fn measure_resident_set_size() -> size_t {
    unsafe {
        let mut usage: libc::rusage;
        assert_eq::<i32, i32>(getrusage(RUSAGE_SELF, &mut usage), 0);
        usage.ru_maxrss
    }
}
```

In this example code, we measure the RSS before and after the compilation process, then calculate the elapsed time during compilation. Note that `catch_with_exit_code` is used to catch any errors that occur during compilation and return an exit code accordingly. This function returns a `Result<i32, String>`, where `i32` represents the exit code of the subprocess, and `String` represents possible error messages.

The `measure_resident_set_size` function measures the resident set size (RSS) using the Linux system call `getrusage` with the flag `RUSAGE_SELF`. It returns a `size_t`, which is an unsigned integer type that can hold a memory address or the result of `sizeof` operator.

