["Here's a basic implementation of how you could handle this with PHP using a combination of session variables, IP address tracking and token generation. Note that this is an oversimplified example and may need adjustments based on specific requirements.

```php
<?php
class TokenGenerator {
    private $session; // Session Object to store the data

    public function __construct() {
        session_start();
        $this->session = &$_SESSION['token'];

        if (!isset($this->session['requests'])) {
            $this->session['requests'] = 0;
            $this->session['lastRequestTime'] = time();
        } 
    }

    public function generateToken() {
        $ip = $_SERVER['REMOTE_ADDR'];

        if ($this->session['lastRequestIP'] === $ip) {
            $this->session['requests']++;

            // If more than 10 requests in less than a second, block further requests
            if ($this->session['requests'] > 10 && time() - $this->session['lastRequestTime'] < 1) {
                throw new Exception('Too many requests from this IP');
            }
        } else {
            $this->session['requests'] = 1;
            $this->session['lastRequestIP'] = $ip;
            $this->session['lastRequestTime'] = time();
        }

        // Generate unique token (simple example)
        $token = md5(uniqid(rand(), true));

        return $token;
    }
}
