function processLogStream(logEntries, filterCallback, aggregationCallback) {
  return new Promise((resolve, reject) => {
    try {
      const relevantEntries = logEntries.filter(entry => filterCallback(entry));
      const summaryObject = relevantEntries.reduce((summary, entry) => {
        return aggregationCallback(summary, entry);
      }, {});
      resolve(summaryObject);
    } catch (error) {
      reject(error);
    }
  });
}
