void processFileNames(char *configFileName, char *newExtension) {
    FILE *file = fopen(configFileName, "r");
    if (file == NULL) {
        printf("Failed to open config file\n");
        return;
    }

    char line[MAX_PATH];
    while (fgets(line, sizeof(line), file)) {
        // Remove trailing newline character
        int len = strlen(line);
        if (line[len-1] == '\n') 
            line[--len] = 0;

        // Count the number of uppercase letters
        int upperCaseCount = 0;
        for (int i=0; i<len; ++i) {
            if(isupper((unsigned char)line[i])) 
                ++upperCaseCount;
        }

        // Construct new filename
        len = strlen(line);
        char *newFileName = malloc(MAX_PATH);
        if (snprintf(newFileName, MAX_FILENAME - strlen(newExtension), "%s%d", line, upperCaseCount) < 0 ||
            strcat(newFileName, newExtension) == NULL) { 
             printf("Failed to create new filename for %s\n", line);
        } else if (strlen(newFileName) > MAX_FILENAME - 1){
            printf("New filename exceeded limit: %s\n", newFileName);
        } else {
            // Do something with the newly created file, like changing its extension or moving it to another directory
            printf("Processing file: %s\n", newFileName);
        }

        free(newFileName); 
    }

    fclose(file);
}
