['Here's an outline of a Java program that implements all your requirements. Due to complexity of external service interaction, it won't be able to handle that part directly but you can use `ProcessBuilder` or Apache commons-exec library for executing commands in Java which will give you the ability to redirect input/output streams:

```java
import java.io.*;
import java.util.*;
import java.nio.file.*;
import java.time.*;
import org.apache.commons.configuration2.*;
import org.yaml.snakeyaml.*;

public class BatchProcessor {
    private static final String CONFIG_FILE = "config.yml";
    private static final String COMMAND_LOG_FILE = "command_log.txt";
    private static final String PROPERTIES_FILE = "env-variables.properties";
    private static final Duration TIMEOUT = Duration.ofSeconds(60);

    public static void main(String[] args) {
        if (args.length < 1) {
            System.out.println("Please provide the number of input files as a command-line argument.");
            return;
        }

        int n = Integer.parseInt(args[0]);
        deleteConfigFile();
        Properties properties = loadProperties();

        for (int i = 1; i <= n; i++) {
            String inputFileName = "input" + i + ".txt";
            runBatchProcessingCommand(inputFileName, properties);
        }
    }

    private static void deleteConfigFile() {
        try {
            Files.deleteIfExists(Paths.get(CONFIG_FILE));
        } catch (IOException e) {
            System.err.println("Failed to delete " + CONFIG_FILE);
            e.printStackTrace();
        }
    }

    private static Properties loadProperties() {
        try (InputStream input = new FileInputStream(PROPERTIES_FILE)) {
            Properties properties = new Properties();
            properties.load(input);
            return properties;
        } catch (IOException e) {
            System.err.println("Failed to load " + PROPERTIES_FILE);
            e.printStackTrace();
            return null;
        }
    }

    private static void runBatchProcessingCommand(String inputFileName, Properties properties) {
        Instant startTime = Instant.now();
        ProcessBuilder pb = new ProcessBuilder("command", "--option", inputFileName);
        Map<String, String> envVars = pb.environment();
        if (properties != null) {
            for (Map.Entry<Object, Object> entry : properties.entrySet()) {
                envVars.put(entry.getKey().toString(), entry.getValue().toString());
            }
        }

        try {
            Process process = pb.start();

            BufferedReader outputReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            writeLogs("batch_output.log", outputReader);
            writeLogs("batch_error.log", errorReader);

            if (!process.waitFor(TIMEOUT.toMillis(), TimeUnit.MILLISECONDS)) {
                process.destroy();
            }

            Instant endTime = Instant.now();
            long duration = Duration.between(startTime, endTime).toMillis();
            int exitStatus = process.exitValue();

            writeCommandLog(pb.command(), startTime, endTime, exitStatus, duration);
        } catch (IOException | InterruptedException e) {
            System.err.println("Failed to run batch processing command: " + pb.command());
            e.printStackTrace();
        }
    }

    private static void writeLogs(String fileName, BufferedReader reader) throws IOException {
        try (PrintWriter writer = new PrintWriter(new FileWriter(fileName, true))) {
            String line;
            while ((line = reader.readLine()) != null) {
                writer.println(LocalDateTime.now() + " - " + line);
            }
        }
    }

    private static void writeCommandLog(List<String> command, Instant startTime, Instant endTime, int exitStatus, long duration) throws IOException {
        try (PrintWriter writer = new PrintWriter(new FileWriter(COMMAND_LOG_FILE, true))) {
            writer.println("Command: " + String.join(" ", command));
            writer.println("Start time: " + startTime);
            writer.println("End time: " + endTime);
            writer.println("Exit status: " + exitStatus);
            writer.println("Duration: " + duration + " ms");
        }
    }
}
```
To handle external service interactions, you would have to use a library such as `OkHttp` or Apache HttpClient to make HTTP requests and handle response/errors in an appropriate way. 

