['Here is an example implementation that satisfies your requirements. Note that this is just a basic template, you might need to adjust it according to your specific needs and the libraries you are using for database connections, network callbacks etc. Also please note that Union-Find operations are not optimized in this code but they should be done correctly to prevent performance degradation with large inputs.

```cpp
#include <chrono>
#include <iostream>
#include <unordered_map>

struct UserSettings { bool isInitialized; };  // Replace with actual user settings object and fields
struct DatabaseConnection { bool isActive; std::string databaseName; };  // Replace with actual database connection object and fields
using NetworkCallback = void (*)();  // Replace with actual network callback function type

enum class ErrorCode {
    UserSettingsNotInitialized,
    DatabaseNotConnected,
    CallbackFunctionIsNull,
};

struct ConfigStructure {
    UserSettings* userSettings;
    DatabaseConnection* databaseConnection;
    NetworkCallback networkCallback;
};

ErrorCode validateConfiguration(ConfigStructure* config) {
    if (!config->userSettings->isInitialized) return ErrorCode::UserSettingsNotInitialized;
    if (!config->databaseConnection->isActive || config->databaseConnection->databaseName != "CorrectDatabase") 
        return ErrorCode::DatabaseNotConnected;
    if (config->networkCallback == nullptr) return ErrorCode::CallbackFunctionIsNull;

    return {};  // No error code means success
}

int find(std::unordered_map<int, int>& parent, int i) {
    if (parent[i] != i) parent[i] = find(parent, parent[i]);
    return parent[i];
}

void unionSet(std::unordered_map<int, int>& parent, std::unordered_map<int, int>& rank, int x, int y) {
    int xRoot = find(parent, x);
    int yRoot = find(parent, y);

    if (rank[xRoot] < rank[yRoot]) parent[xRoot] = yRoot;
    else if (rank[xRoot] > rank[yRoot]) parent[yRoot] = xRoot;
    else {
        parent[yRoot] = xRoot;
        ++rank[xRoot];
    }
}

int countDisjointPairs(const ConfigStructure* config, const std::vector<int>& arr) {
    if (auto errorCode = validateConfiguration(config); errorCode != ErrorCode{}) return static_cast<int>(errorCode);

    auto startTime = std::chrono::high_resolution_clock::now();  // Start measuring time

    std::unordered_map<int, int> parent;
    std::unordered_map<int, int> rank;

    for (int i : arr) {
        if (!parent.count(i)) {
            parent[i] = i;
            rank[i] = 0;
        }

        unionSet(parent, rank, i, i + 1);  // Assuming pairs are adjacent numbers
    }

    auto endTime = std::chrono::high_resolution_clock::now();  // Stop measuring time
    int durationMs = std::chrono::duration<double, std::milli>(endTime - startTime).count();

    std::cout << "Duration: " << durationMs << " ms" << '\n';
    return parent.size() + rank.size() / 2;  // Assuming each pair as counted twice (as a root and as a child)
}
```
The code above assumes that you are checking for pairs of consecutive numbers in the array, which may not always be correct depending on your specific use case. Please adjust it according to your needs.
