['Here is a basic example in C using cJSON library for JSON parsing and validation. This function does not handle external services outages or network connectivity issues as these are system-level concerns and should be handled separately by the application code. The same applies to error handling strategy, it's up to you to decide how you want to present errors to the end user:

```c
#include <ctype.h>
#include <stdbool.h>
#include "cJSON.h"

enum { MAX_TOKEN_LEN = 8192, MAX_LIFETIME = 86400 };  // arbitrary values

bool validateToken(const char* jsonStr) {
    cJSON *json = cJSON_Parse(jsonStr);
    if (json == NULL) {
        const char *errorPtr = cJSON_GetErrorPtr();
        if (errorPtr != NULL) {
            fprintf(stderr, "Failed to parse JSON: %s\n", errorPtr);
        } else {
            fprintf(stderr, "Unknown JSON parsing error.\n");
        }
        return false;
    }

    cJSON *accessToken = cJSON_GetObjectItemCaseSensitive(json, "access_token");
    if (cJSON_IsString(accessToken) && strlen(accessToken->valuestring) >= 16) {
        for (const char* ptr = accessToken->valuestring; *ptr != '\0'; ++ptr) {
            if (!isalnum(*ptr)) {
                fprintf(stderr, "Access token contains non-alphanumeric characters.\n");
                cJSON_Delete(json);
                return false;
            }
        }
    } else {
        fprintf(stderr, "Invalid or missing access token.\n");
        cJSON_Delete(json);
        return false;
    }

    cJSON *expiresIn = cJSON_GetObjectItemCaseSensitive(json, "expires_in");
    if (cJSON_IsNumber(expiresIn) && expiresIn->valueint <= MAX_LIFETIME) {
        // valid token, handle accordingly
    } else {
        fprintf(stderr, "Invalid or missing expiry time.\n");
        cJSON_Delete(json);
        return false;
    }

    cJSON *tokenType = cJSON_GetObjectItemCaseSensitive(json, "token_type");
    if (cJSON_IsString(tokenType) && strcasecmp(tokenType->valuestring, "Bearer") == 0) {
        // valid token type, handle accordingly
    } else {
        fprintf(stderr, "Invalid or missing token type.\n");
        cJSON_Delete(json);
        return false;
    }

    cJSON *refreshToken = cJSON_GetObjectItemCaseSensitive(json, "refresh_token");
    if (cJSON_IsString(refreshToken) && strlen(refreshToken->valuestring) >= 16) {
        for (const char* ptr = refreshToken->valuestring; *ptr != '\0'; ++ptr) {
            if (!isalnum(*ptr) && (*ptr != '_')) {  // additional check for underscores
                fprintf(stderr, "Refresh token contains non-alphanumeric characters.\n");
                cJSON_Delete(json);
                return false;
            }
        }
    } else if (cJSON_IsNull(refreshToken)) {
        // optional field not provided, handle accordingly
    } else {
        fprintf(stderr, "Invalid or too short refresh token.\n");
        cJSON_Delete(json);
        return false;
    }

    cJSON_Delete(json);  // delete json object after processing it

    return true;  // if no error occurred till this point, the token is valid
}
```
In a production system, you may want to use more sophisticated logging mechanisms such as syslog or writing to a file. You could also consider adding timeouts for handling slow network connections and external services outages. For optimizing performance, ensure that the JSON library provides an efficient parsing mechanism and optimize your C code accordingly.
