['Here is your requested C# class. This implementation uses a simplified structure to handle key rotation and log encryption attempts. It does not use an external logging framework or configuration manager as those can be quite complex to setup and integrate with this basic class, but should provide a good starting point for integrating these systems if needed:

```csharp
using System;
using System.Collections.Generic;
using System.Text;
using System.Security.Cryptography;
using System.Linq;

public class TripleDESDecryptionManager
{
    private Dictionary<string, TripleDES> keys = new Dictionary<string, TripleDES>();
    public string LastError { get; private set; }

    // Add a key to the rotation
    public void AddKey(byte[] key)
    {
        if (key.Length != 24) throw new ArgumentException("Key must be exactly 192 bits (24 bytes) long");

        var des = TripleDES.Create();
        des.Key = key;
        des.IV = new byte[8]; // A null IV is valid but not secure, so we use a zeroed IV here for simplicity
        keys[Convert.ToBase64String(key)] = des;
    }

    // Decrypt a message
    public string DecryptMessage(string base64EncodedMessage)
    {
        foreach (var key in keys.Values)
        {
            try
            {
                using (ICryptoTransform decryptor = key.CreateDecryptor())
                {
                    byte[] bytesToDecode = Convert.FromBase64String(base64EncodedMessage);
                    byte[] decryptedBytes = decryptor.TransformFinalBlock(bytesToDecode, 0, bytesToDecode.Length);

                    string decryptedData = Encoding.UTF8.GetString(decryptedBytes);

                    Logger.LogInfo($"Successfully decrypted a message using key {Convert.ToBase64String(key.Key)}");
                    return decryptedData;
                }
            }
            catch (Exception e)
            {
                LastError = $"Failed to decrypt message with exception: {e}";
                Logger.LogError(LastError);
            }
        }

        LastError = "Could not decrypt the message using any available key";
        return null;
    }

    // The following methods should be implemented based on an external logging framework you use
    static class Logger 
    {
        public static void LogInfo(string info)
        {
            Console.WriteLine($"INFO: {info}");
        }

        public static void LogError(string error)
        {
            Console.WriteLine($"ERROR: {error}");
        }
    }

    // A sample implementation of a configuration manager, should be replaced with actual integration details 
    static class ConfigManager
    {
        public static string[] GetKeys()
        {
            return new[] {"your", "keys", "go", "here"};
        }
    }
}
```

To use this class, you would do something like:

