public static ProcessAndAggregateDataResult ProcessAndAggregateData(byte[] ciphertext, byte[] key, byte[] IV) 
{
    // Decrypt the ciphertext
    Aes aes = Aes.Create();
    ICryptoTransform decryptor = aes.CreateDecryptor(key, IV);
    using (MemoryStream msDecrypt = new MemoryStream()) {
        using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Write)) {
            csDecrypt.Write(ciphertext, 0, ciphertext.Length);
        }
        byte[] plainText = msDecrypt.ToArray();
    }

    // Process the data
    List<int> intList = new List<int>();
    using (StreamReader reader = new StreamReader(new MemoryStream(plainText))) {
        string line;
        while ((line = reader.ReadLine()) != null) {
            if (!Int32.TryParse(line, out int result)) {
                // handle error: invalid integer input
            } else {
                intList.Add(result);
            }
        }
    }

    long sum = 0;
    double average = 0;
    int maxValue = Int32.MinValue;
    if (intList.Count > 0) {
        sum = intList.Sum();
        average = intList.Average();
        maxValue = intList.Max();
    } else {
        // handle error: empty data stream
    }

    return new ProcessAndAggregateDataResult { PlainText = plainText, Sum = sum, Average = average, MaxValue = maxValue };
}
