#define MAX_USERS 100

typedef struct {
    int USER_ID;
    char *SESSION_KEY; // Assuming that SESSION_KEY is a string for simplicity
    int STATUS;
} USER_CONTEXT;

USER_CONTEXT users[MAX_USERS]; 
int used = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* allocate_user() {
    pthread_mutex_lock(&lock); // Lock to ensure thread-safety
    if (used < MAX_USERS) {
        users[used].USER_ID = used + 1; // Unique user id from 1 to 65535
        users[used].SESSION_KEY = generate_session_key(); // Cryptographic library function for session key generation
        if(users[used].SESSION_KEY == NULL) {
            printf("Session Key Generation Failed");
            pthread_mutex_unlock(&lock);
            return NULL;
        }
        users[used].STATUS = 0; // Initial state of the session, can be modified as required 
        ++used;
        pthread_mutex_unlock(&lock);
        return &users[used-1];
    } else {
        printf("Maximum Users Limit Reached");
        pthread_mutex_unlock(&lock);
        return NULL;
    }
}

void deallocate_user(USER_CONTEXT *user) {
    int index = user - users; // find the index of given user context in our list
    if (index >= 0 && index < used) {
        --used;
        free(users[index].SESSION_KEY); // Freeing memory allocated for session key
        if (index != used) { // If not last element then move last element to this position
            users[index] = users[used]; 
        }
    } else {
        printf("Invalid User");
    }
}
```
