public class Main {
    private static final Logger logger = LogManager.getLogger(Main.class);

    // Assuming MoSTState is a serializable class, otherwise use correct class name.
    public Object loadStateObjectFromFile(String fileName) throws ClassNotFoundException, IOException {
        FileInputStream fis = new FileInputStream(fileName); 

        try (Reader reader = new BufferedReader(new InputStreamReader(fis))) {
            LockableFileReader lockableReader = new LockableFileReader(reader.read(), true);

            Object objFromFile;

