            } else {
                // Handle error scenario, this can be done in many ways depending on the application context.
                if (logger.isDebugEnabled()) {
                    logger.debug("Loaded object is not an instance of MoSTState");
                } 

                return null;
            } 
        } catch(FileNotFoundException fnf) {
            if (logger.isErrorEnabled()) {
                logger.error("File not found: " + fileName);
            }

            throw new RuntimeException(fnf);
        } catch (IOException ioe) {
            if (logger.isErrorEnabled()) {
                logger.error("An exception occurred while reading the object from a file", ioe);
            }

            throw new RuntimeException(ioe);
        } finally {
            fis.close();
        } 
    }  
}
