```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct record {
    int value;  // this could be a pointer to more complex data structures
} Record;

typedef void (*callback_fn)(Record* rec);

void log_error(const char* message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

// Assumes an external module with a logging function 'log'
extern void log(char *message); 

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static int initialized = 0;

void* initializeRecords(int min, int max, unsigned long initializationMask, callback_fn fn) {
    if (initialized != 1) {
        pthread_mutex_lock(&mutex);

        if (!initialized) {
            int size = max - min + 1;
            Record *records = malloc(sizeof(Record)*size);

            if (records == NULL) {
                log_error("Failed to allocate memory for records");
                pthread_mutex_unlock(&mutex);
                return NULL;
            }

            // Initialize only those records which are specified by the mask
            for(int i=0; i<size; i++) {
                if((initializationMask & (1UL<<i)) != 0) {
                    Record r = { min + i }; 
                    memcpy(&records[i], &r, sizeof(Record));
                }
            }

            initialized = 1;
        }

        pthread_mutex_unlock(&mutex);
    }

    // If a callback is provided then call it
    if (fn != NULL) {
        fn(records);
    }

    return records;
}

void freeRecords() {
    pthread_mutex_lock(&mutex);

    if (initialized == 1) {
        free(records);
        initialized = 0;
    }

    pthread_mutex_unlock(&mutex);
}
```
