// Define a structure for the thread function's arguments
typedef struct {
    char *url;
    int critical;
} request_args;

void *request_handler(void *arg) {
    request_args *args = (request_args *) arg;

    CURL *curl;
    CURLcode res;

    curl = curl_easy_init();
    if (curl) {
        // Set URL and perform the fetch
        curl_easy_setopt(curl, CURLOPT_URL, args->url);

        /* adjust request parameters based on network latency */
        struct timeval tv;
        gettimeofday(&tv, NULL);
        unsigned long start = tv.tv_sec * 1000 + tv.tv_usec / 1000;
        res = curl_easy_perform(curl);

        /* measure the latency */
        gettimeofday(&tv, NULL);
        unsigned long end = tv.tv_sec * 1000 + tv.tv_usec / 1000;

        /* Report latency and success/failure to external service */
        /* (This would depend on the API of your monitoring service) */
        report_to_monitoring(args->url, end - start, res);

        curl_easy_cleanup(curl);
    }

    pthread_exit(NULL);
}

void dispatch_requests(char *urls[], int criticalities[], size_t n) {
    // Initialize threads and their arguments
    pthread_t threads[n];
    request_args args[n];

    for (size_t i = 0; i < n; ++i) {
        args[i].url = urls[i];
        args[i].critical = criticalities[i];

        // Create threads to handle requests, dynamically adjusting parameters based on network latency and criticality
        if (pthread_create(&threads[i], NULL, request_handler, &args[i]) != 0) {
            fprintf(stderr, "Error creating thread\n");
            return;
        }
    }

    // Join all threads
    for (size_t i = 0; i < n; ++i) {
        pthread_join(threads[i], NULL);
    }
}
