typedef struct {
    size_t capacity;
    size_t size;
    LogEntry* entries;
    // Add pointers to additional data sources if required
} LogCollection;

LogCollection* createLogCollection(size_t initialCapacity) {
    LogCollection* collection = malloc(sizeof(LogCollection));

    if (collection == NULL) {
        fprintf(stderr, "Memory allocation failed for LogCollection\n");
        return NULL;
    }

    collection->entries = malloc(initialCapacity * sizeof(LogEntry));

    if (collection->entries == NULL) {
        fprintf(stderr, "Memory allocation failed for LogEntries\n");
        free(collection);
        return NULL;
    }

    collection->capacity = initialCapacity;
    collection->size = 0;
    srand(time(NULL));  // Seed the random number generator

    return collection;
}

void addEntryToCollection(LogCollection* collection, long timestamp, int eventType, float priorityLevel) {
    if (collection == NULL) {
        fprintf(stderr, "Null pointer passed to addEntryToCollection\n");
        return;
    }

    // Resize the array if necessary
    if (collection->size >= collection->capacity) {
        size_t newCapacity = collection->capacity * 2;

        LogEntry* newEntries = realloc(collection->entries, newCapacity * sizeof(LogEntry));

        if (newEntries == NULL) {
            fprintf(stderr, "Memory reallocation failed for LogEntries\n");
            return;
        }

        collection->capacity = newCapacity;
        collection->entries = newEntries;
    }

    // Add the log entry
    collection->entries[collection->size].timestamp = timestamp;
    collection->entries[collection->size].eventType = eventType;
    collection->entries[collection->size].priorityLevel = priorityLevel;

    // Add random CRCFLAG value here
    collection->entries[collection->size].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    ++(collection->size);
}
