    for (size_t i = 0; i < arraySize; ++i) {
        if (ueArray[i]->ueId == ueId) {
            // Update existing UE.
            free(ueArray[i]);
            ueArray[i] = context;

            pthread_mutex_unlock(&addUpdateMutex);
            return 0;
        }
    }

    if (arraySize == arrayCapacity) {
        // Resize the array when it's full.
        arrayCapacity *= 2;
        UEContext** newArray = realloc(ueArray, arrayCapacity * sizeof(UEContext*));
        if (newArray == NULL) {
            pthread_mutex_unlock(&addUpdateMutex);
            return -1;
        }

        ueArray = newArray;
    }

    // Add a new UE.
    ueArray[arraySize++] = context;

    pthread_mutex_unlock(&addUpdateMutex);
    return 0;
}

