HashTable* create_table(size_t size) {
    HashTable *table = malloc(sizeof(HashTable));
    table->records = calloc(size, sizeof(Record*));
    pthread_mutex_init(&table->mutex, NULL);
    return table;
}

void add_record(HashTable *table, Record *record) {
    size_t index = hash(record->id) % table->size;

    pthread_mutex_lock(&table->mutex);
    table->records[index] = record;
    pthread_mutex_unlock(&table->mutex);
}

Record* get_record(HashTable *table, char *id) {
    size_t index = hash(id) % table->size;

    pthread_mutex_lock(&table->mutex);
    Record *record = table->records[index];
    pthread_mutex_unlock(&table->mutex);

    return record;
}

void delete_record(HashTable *table, char *id) {
