['The code below is an example for what you requested, it uses OpenSSL library for encryption/decryption operations and has basic error handling. However, this solution doesn't fully address all your points like thread safety, future cryptographic libraries support etc. These are complex issues and can't be handled by just one function in isolation.

```C
#include <openssl/evp.h>
#include <openssl/aes.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>

#define BUFFER_SIZE 1024*8 // 8KB buffer size

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} CipherObject;

void init_cipher(CipherObject* cipher, const unsigned char* key, const unsigned char* iv) {
    memset(cipher->key, 0, EVP_MAX_KEY_LENGTH);
    memset(cipher->iv, 0, EVP_MAX_IV_LENGTH);
    memcpy(cipher->key, key, strlen((const char*)key));
    memcpy(cipher->iv, iv, strlen((const char*)iv));
    cipher->ctx = EVP_CIPHER_CTX_new();
}

int perform_crypto(CipherObject* cipher, FILE *infile, FILE *outfile, int mode) {
    unsigned char inbuf[BUFFER_SIZE], outbuf[BUFFER_SIZE + EVP_MAX_BLOCK_LENGTH];
    size_t readBytes;
    int outlen, len = 0;

    if(!EVP_CipherInit_ex(cipher->ctx, EVP_aes_256_cbc(), NULL, cipher->key, cipher->iv, mode)) {
        return -1;  // Failed to initialize the crypto operation
    }

    for(;;) {
        readBytes = fread(inbuf, 1, BUFFER_SIZE, infile);
        if(!EVP_CipherUpdate(cipher->ctx, outbuf, &outlen, inbuf, readBytes)) {
            return -2; // Failed to perform crypto operation
        }
        fwrite(outbuf, 1, outlen, outfile);

        if (readBytes < BUFFER_SIZE) { /* end of file */
            if(!EVP_CipherFinal_ex(cipher->ctx, outbuf, &outlen)) {
                return -3; // Failed to finalize the crypto operation
            }
            fwrite(outbuf, 1, outlen, outfile);
            break;
        }
    }

    EVP_CIPHER_CTX_free(cipher->ctx);
    return len;
}

int processFile(const unsigned char* key, const unsigned char* iv, const char *inFileName, const char *outFileName, int mode) {
    FILE *infile = fopen(inFileName, "rb");
    if(!infile) {
        return -4; // Cannot open input file.
    }

    FILE *outfile = fopen(outFileName, "wb");
    if(!outfile) {
        fclose(infile);
        return -5; // Cannot open output file.
    }

    CipherObject cipher;
    init_cipher(&cipher, key, iv);
    int ret = perform_crypto(&cipher, infile, outfile, mode);

    fclose(infile);
    fclose(outfile);

    return ret; // Returns 0 if successful.
}
```
To use it:
```C
unsigned char key[] = "0123456789abcdef";
unsigned char iv[] = "0123456789abcdef";
processFile(key, iv, "infile", "outfile", 1); // encryption mode
```
This code only encrypts data with AES-256 in CBC mode. It can be adapted to support other cryptographic algorithms by modifying the `EVP_CIPHER` and `EVP_aes_*` function calls used in `perform_crypto`. 

Please note that this code does not handle thread safety, error management is very basic, and it's recommended to add more robust error handling (like return codes with specific error messages) for production usage. Also, remember to free the cipher context with EVP_CIPHER_CTX_free after using it.
']

