char* expandStringWithDelimiter(const char* input, int sizeLimit, char delimiter, bool async) {
    if (input == NULL || sizeLimit < 0) return NULL; // handle invalid inputs gracefully
    int len = strlen(input);

    // if the string length is greater than the limit and the string length is not even, return null
    if ((async && len > sizeLimit && len % 2 != 0) || (!async && len > sizeLimit)) {
        return NULL;
    }

    char* result = malloc(len + 2); // plus one for the delimiter and one for the null terminator

    if (result == NULL) return NULL; // handle memory allocation failures

    strcpy(result, input);

    if (!async || len <= sizeLimit) {
        result[len] = delimiter;
        result[len + 1] = '\0';
    } else {
        result[len] = '\0'; // null terminator only in case of async and even length string
    }

    return result;
}
