            return attack;
        }
    }

private:
    CRC_INDICATION_REL8_TAG selectNextAttack() {
        std::random_device rd;  //Will be used to obtain a seed for the random number engine
        std::mt19937 gen(rd()); //Standard mersenne_twister_engine seeded with rd()
        std::uniform_int_distribution<> distrib(0, 1);

        return {distrib(gen) == 1}; // randomly generate CRCFLAG
    }

    void printHistory() const {
        for (const auto& attack : history) {
            std::cout << "CRC_INDICATION_REL8_TAG{ crcFlag = " 
                      << (attack.crcFlag ? "true" : "false") << " } ";
        }
        std::cout << '\n';
    }

    mutable std::shared_mutex mtx; // shared_timed_mutex would be better for high contention, but is C++20 only
    std::deque<CRC_INDICATION_REL8_TAG> history;
    std::unordered_map<RNTI, 
                       std::chrono::time_point<std::chrono::system_clock>> lastAttacks;
};
