typedef struct {
    int TDD_ULDL_Config;
    int PDCCH_Bandwidth_Part;
    float Cell_Specific_Ref_Signal_Power;
    unsigned short Checksum;
} LTE_EUTRA_SIB1_T;

typedef struct {
    LTE_EUTRA_SIB1_T *array;
    size_t used;
    size_t size;
} Array;

void initArray(Array *a, size_t initialSize) {
    a->array = (LTE_EUTRA_SIB1_T *)malloc(initialSize * sizeof(LTE_EUTRA_SIB1_T));
    a->used = 0;
    a->size = initialSize;
}

void insertArray(Array *a, LTE_EUTRA_SIB1_T element) {
    if (a->used == a->size) {
        a->size *= 2;
        a->array = (LTE_EUTRA_SIB1_T *)realloc(a->array, a->size * sizeof(LTE_EUTRA_SIB1_T));
    }
    a->array[a->used++] = element;
}

void freeArray(Array *a) {
    free(a->array);
    a->array = NULL;
    a->used = a->size = 0;
}
```

To calculate checksum, you can use any algorithm suitable for your needs. Here's an example using simple summation:

```c
unsigned short CalculateChecksum(LTE_EUTRA_SIB1_T *sib) {
    unsigned short *ptr = (unsigned short *)sib;
    size_t len = sizeof(LTE_EUTRA_SIB1_T);
    unsigned long sum = 0;

    while(len > 1) {
        sum += *ptr++;
        len -= 2;
    }

    if (len > 0) {
        sum += *(unsigned char *)ptr;
    }

    while (sum>>16) 
        sum = (sum & 0xffff) + (sum >> 16);

    return ~sum;
}
```

Note: This is a simplistic implementation and does not include many features which would be required in an actual LTE network management system, such as error checking, data validation, concurrent access control, etc. Further optimization might also be necessary based on the specific use-cases and requirements of the application.
