typedef struct {
    NFAPI_CRC_INDICATION_PDU_T **list;
    int capacity;
    int size;
    pthread_mutex_t lock;
} DynamicList;

DynamicList *createList(int capacity) {
    DynamicList *lst = (DynamicList*) malloc(sizeof(DynamicList));
    if (!lst) return NULL;

    lst->list = (NFAPI_CRC_INDICATION_PDU_T**) calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if(!lst->list){
        free(lst);
        return NULL;
    }

    lst->capacity = capacity;
    lst->size = 0;
    pthread_mutex_init(&lst->lock, NULL);

    return lst;
}

int addToList(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T *element) {
    if (!list || !element) return -1;

    pthread_mutex_lock(&list->lock);
    if (list->size == list->capacity) {
        // Resize the list when full. This is a simple resize strategy and can be optimized depending on your specific needs.
        list->capacity *= 2;
        NFAPI_CRC_INDICATION_PDU_T **newList = realloc(list->list, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

        if (!newList) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Out of memory
        }

        list->list = newList;
    }

    list->list[list->size] = element;
    list->size++;
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}
```
This code provides the basic structure for a thread safe dynamic array in C. The addToList function will resize the array if it is full, which ensures that we do not run out of memory when the list grows too large. It also uses pthread_mutex to ensure thread-safety, preventing multiple threads from adding elements at the same time. 

