['Here is an implementation in C of your requirements using POSIX threads for concurrency management:

```c
#include <pthread.h>
#include <errno.h>
#include <stdio.h>
#include <string.h>

typedef struct {
    int interfaceId;
    char band[32];
    double carrierFrequency;
    float powerControlParams;
    float sinrThresholds;
} NetworkInterfaceConfig;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
NetworkInterfaceConfig* networkInterfaces[100000];
int numInterfaces = 0;
FILE *configFile;
const char *filename = "networkInterfaces.dat";

void initialize() {
    configFile = fopen(filename, "r+");
    if (configFile == NULL) {
        configFile = fopen(filename, "w+");
    } else {
        NetworkInterfaceConfig conf;
        while (fread(&conf, sizeof(NetworkInterfaceConfig), 1, configFile)) {
            networkInterfaces[numInterfaces] = malloc(sizeof(NetworkInterfaceConfig));
            memcpy(networkInterfaces[numInterfaces], &conf, sizeof(NetworkInterfaceConfig));
            numInterfaces++;
        }
    }
}

int add_interface(int interfaceId, const char* band, double carrierFrequency, float powerControlParams, float sinrThresholds) {
    if (carrierFrequency < 0 || sinrThresholds <= 0) {
        return -1; // Invalid input values
    }

    pthread_mutex_lock(&lock);
    for (int i = 0; i < numInterfaces; i++) {
        if (networkInterfaces[i]->carrierFrequency == carrierFrequency ||
            networkInterfaces[i]->interfaceId == interfaceId) {
            pthread_mutex_unlock(&lock);
            return -2; // Duplicate frequency or ID detected
        }
    }

    NetworkInterfaceConfig* conf = malloc(sizeof(NetworkInterfaceConfig));
    conf->interfaceId = interfaceId;
    strcpy(conf->band, band);
    conf->carrierFrequency = carrierFrequency;
    conf->powerControlParams = powerControlParams;
    conf->sinrThresholds = sinrThresholds;

    networkInterfaces[numInterfaces] = conf;
    numInterfaces++;

    fwrite(conf, sizeof(NetworkInterfaceConfig), 1, configFile);
    fflush(configFile);

    pthread_mutex_unlock(&lock);

    return 0; // Successfully added interface
}
```
This code implements the requested features in C with minimal error checking for readability. In a production environment, more robust checks would be necessary, such as error-checking file I/O operations and ensuring mutexes are always released even if an error occurs. Please note that this is just a simplified version of what you asked for. A real-world application will need to handle larger datasets, provide a way to update configurations, and have more robust handling of errors and edge cases.
