RecordsContainer* create_container() {
    RecordsContainer* container = malloc(sizeof(RecordsContainer));

    if (container == NULL) {
        fprintf(stderr, "Failed to allocate memory for the container\n");
        exit(EXIT_FAILURE);
    }

    container->capacity = INITIAL_CAPACITY;
    container->size = 0;

    container->records = malloc(container->capacity * sizeof(Record));

    if (container->records == NULL) {
        fprintf(stderr, "Failed to allocate memory for the records\n");
        exit(EXIT_FAILURE);
    }

    return container;
}

void add_record(RecordsContainer* container, int key, char* value) {
    if (container->size >= container->capacity) {
        // Reallocate memory for the records when exceeding capacity
        Record* temp = realloc(container->records, 2 * container->capacity * sizeof(Record));

        if (temp == NULL) {
            fprintf(stderr, "Failed to allocate additional memory for the records\n");
            exit(EXIT_FAILURE);
        }

        container->records = temp;
        container->capacity *= 2;
    }

    Record record = {.key = key};
    strncpy(record.value, value, STRING_LEN - 1);
    record.value[STRING_LEN - 1] = '\0'; // Ensure null termination
    container->records[container->size++] = record;
}

