NFAPI_CRC_INDICATION_PDU_T *generateNFAPIIndications(int N, int *allowedRNTIs, int allowedSize) {
    pthread_mutex_lock(&mutex);

    srand((unsigned int) time(0));

    NFAPI_CRC_INDICATION_PDU_T *pduList = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < N; i++) {
        int rnti;

        if (cachingEnabled && cachedSize > 0) {
            rnti = cachedRNTIs[rand() % cachedSize];
        } else {
            rnti = allowedRNTIs[rand() % allowedSize];

            // Add to cache
            if (cachingEnabled) {
                int *newCache = realloc(cachedRNTIs, ++cachedSize * sizeof(int));

                if (!newCache) exit(-1);  // Reallocation failed.

                cachedRNTIs = newCache;
                cachedRNTIs[cachedSize - 1] = rnti;
            }
        }

        pduList[i].RNTI = rnti;
    }

    pthread_mutex_unlock(&mutex);

    return pduList;
}
