['Here is an example of a solution in C language using pthreads for thread handling and locking mechanisms. However, note that this is just a basic outline and doesn't cover all possible edge cases or optimizations.

```c
#include <pthread.h>
#include <stdlib.h>
#include <time.h>

// Custom structure for DataPacket
typedef struct {
    time_t timestamp;
    int id;
    bool status;  // true if active, false otherwise
} DataPacket;

// Global variables and mutexes
DataPacket **packets;
int packetCount = 0;
time_t expirationDuration = 7 * 24 * 60 * 60;  // 7 days
pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;

// Add new packets to the dynamic array
void addPacket(DataPacket *packet) {
    pthread_mutex_lock(&listMutex);
    packet->timestamp = time(NULL);  // Get current timestamp
    packet->status = true;  // Initialize status as active

    packets = realloc(packets, sizeof(DataPacket*) * (packetCount + 1));
    if(packets == NULL) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    packets[packetCount] = packet;  // Add new packet to array
    packetCount++;

    pthread_mutex_unlock(&listMutex);
}

// Remove expired packets from the dynamic array
void removeExpiredPackets() {
    pthread_mutex_lock(&listMutex);
    time_t currentTime = time(NULL);  // Get current timestamp

    for(int i = 0; i < packetCount; i++) {
        if(currentTime - packets[i]->timestamp > expirationDuration) {
            free(packets[i]);  // Free memory allocated to expired packet

            // Shift remaining elements down in array
            for(int j = i; j < packetCount-1; j++) {
                packets[j] = packets[j+1];
            }

            packetCount--;  // Decrement count of packets
            packets = realloc(packets, sizeof(DataPacket*) * packetCount);  // Reallocate memory to fit new size
        }
    }

    pthread_mutex_unlock(&listMutex);
}

// Retrieve the count of active packets
int getActivePacketCount() {
    int count = 0;

    pthread_mutex_lock(&listMutex);
    for(int i = 0; i < packetCount; i++) {
        if(packets[i]->status == true) {
            count++;
        }
    }
    pthread_mutex_unlock(&listMutex);

    return count;
}
```

This is a basic example and doesn't cover some advanced topics such as error handling for failed external data source connections, optimizing memory usage, or implementing read-heavy and write-heavy operation optimization. Please also note that this code has limitations on the amount of data it can handle due to system memory constraints. For a real-world application, you would need to consider using more efficient data structures and managing memory carefully.
']

