        if (pm->capacity == 0) {
            pm->packets = malloc(10 * sizeof(*pm->packets));
            pm->capacity = 10;
        } else {
            size_t newCapacity = pm->capacity * 2;
            DataPacket* newArray = realloc(pm->packets, newCapacity * sizeof(*newArray));
            if (newArray == NULL) exit(EXIT_FAILURE); // If allocation fails
            pm->packets = newArray;
            pm->capacity = newCapacity;
        }
    }
    pm->packets[pm->size++] = p;
}

void packetmanagerRemoveExpiredPackets(PacketManager* pm, clock_t threshold) {
    for (size_t i = 0; i < pm->size;) {
        if (difftime(time(NULL), pm->packets[i].timestamp) > threshold) {
            pm->packets[i] = pm->packets[--pm->size]; // Overwrite the expired packet with the last one, then decrease size
        } else {
            ++i;
        }
    }
}

int packetmanagerGetActiveCount(PacketManager* pm) {
    int count = 0;
    for (size_t i = 0; i < pm->size; ++i) {
        if (pm->packets[i].statusFlag) {
            ++count;
        }
    }
    return count;
}
``` 
