const asyncLogging = false;  // change to true for asynchronous logging
let logFunc = (msg) => console.log(msg);  // replace with your logging function
if(asyncLogging){
    const { createWriteStream } = require('fs');
    const file = createWriteStream("./out.txt");
    logFunc = (msg) => file.write(JSON.stringify({timestamp: Date.now(), message: msg}));
}

function copyBufferData(chunks, byteCount){
    let copiedBytes = 0;
    const totalByteSize = chunks.reduce((total, chunk) => total + chunk.length, 0);

    logFunc("Starting buffer copying...");

    if (byteCount > totalByteSize) {
        logFunc(`Requested byte count (${byteCount}) exceeds available data size (${totalByteSize}). Copying all bytes...`);
        byteCount = totalByteSize;
    }

    let bufferOffset = 0;
    let chunkOffsets = Array(chunks.length).fill(0);
    const newBuffer = Buffer.allocUnsafe(byteCount);

    for (let i=0; copiedBytes<byteCount && i<chunkOffsets.length;) {
        const chunk = chunks[i];
        const remainingInChunk = chunk.length - chunkOffsets[i];
        let copySize = Math.min(remainingInChunk, byteCount-copiedBytes);

        chunk.copy(newBuffer, bufferOffset, chunkOffsets[i], chunkOffsets[i] + copySize);
        copiedBytes += copySize;
        chunkOffsets[i] += copySize;
        bufferOffset += copySize;

        if (chunkOffsets[i] >= chunks[i].length) {  // move to next chunk
            i++;
        }
    }

    logFunc(`Finished copying data. Requested bytes: ${byteCount}. Actual bytes copied: ${copiedBytes}`);
    return newBuffer;
}
```

You can test this function with the following code snippet:

