["Here's an example C code implementing the above requirements using POSIX threads, mutexes for thread safety and `rand_r` function for random number generation:

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_LIST_SIZE 1000
typedef struct {
    pthread_mutex_t lock;
    int count;
    NFAPI_CRC_INDICATION_PDU_T list[MAX_LIST_SIZE];
} shared_data_t;

shared_data_t data = { PTHREAD_MUTEX_INITIALIZER, 0 };

uint32_t allocateRNTI(void) {
    uint32_t rnti = 0;
    while (1) {
        // acquire a seed value
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        unsigned int seed = ts.tv_nsec;

        pthread_mutex_lock(&data.lock);
        for (int i = 0; i < data.count; ++i) {
            rnti = rand_r(&seed);
            if (data.list[i].RNTI != rnti) break;
        }
        pthread_mutex_unlock(&data.lock);

        // If no RNTI is found, retry
    }

    return rnti;
}

int createPDUList(void) {
    uint16_t tag = 0xFF;
    while (data.count < MAX_LIST_SIZE) {
        NFAPI_CRC_INDICATION_PDU_T pdu = {tag, allocateRNTI(), rand() % 256};

        pthread_mutex_lock(&data.lock);
        data.list[data.count++] = pdu;
        pthread_mutex_unlock(&data.lock);
    }

    if (data.count == MAX_LIST_SIZE) return 0; // success
    else return -1; // error occurred
}
```
Note: The function `allocateRNTI()` uses `rand_r()` to generate a new random number which is guaranteed to be thread-safe in POSIX systems. It also uses a seed that changes every microsecond, improving the randomness of the generated numbers. However, this doesn't guarantee that you can't get two consecutive RNTI values due to high concurrency or high speed network latency. You should consider using an actual external data source for RNTI allocation if possible.
