int read_file(char *filename, int **array, int *N) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Cannot open file: %s\n", filename);
        return -1;
    }

    // Determine the number of integers in the file
    int val;
    while (fscanf(fp, "%d", &val) == 1) (*N)++;

    if (*N == 0) {
        printf("File is empty or contains non-integer values.\n");
        fclose(fp);
        return -1;
    }

    rewind(fp); // Rewind the file to start from beginning for reading integers

    *array = malloc(*N * sizeof(int));
    if (*array == NULL) {
        printf("Failed to allocate memory.\n");
        fclose(fp);
        return -1;
    }

    // Read the integers from file into array
    for (int i = 0; i < *N; i++) {
        if (fscanf(fp, "%d", &(*array)[i]) != 1) {
            printf("File contains non-integer values.\n");
            free(*array);
            fclose(fp);
            return -1;
        }
    }

    fclose(fp); // Close the file
    return 0;
}

void print_largest_num(int *array, int N) {
    if (N == 0) {
        printf("Array is empty.\n");
        return;
    }

    int largest = array[0];
    for (int i = 1; i < N; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    printf("The largest number in the array is: %d\n", largest);
}

double calculate_average(int *array, int N, int threshold) {
    if (N == 0) {
        printf("Array is empty.\n");
        return 0;
    }

    int count = 0;
    double sum = 0.0;
    for (int i = 0; i < N; i++) {
        if (array[i] > threshold) {
            sum += array[i];
            count++;
        }
    }

    if (count == 0) {
        printf("No integers in the array exceed the specified threshold.\n");
        return 0;
    }

    double average = sum / count;
    printf("The average of integers that exceed the threshold is: %f\n", average);

    return average;
}

void validate_duplicates(int *array, int N) {
    for (int i = 0; i < N-1; i++) {
        for (int j = i+1; j < N; j++) {
            if (array[i] == array[j]) {
                printf("Duplicate integer: %d\n", array[i]);
                return;
            }
        }
    }

    printf("No duplicates found in the array.\n");
}

void populate_structures(NFAPI_CRC_INDICATION_PDU_T **structArray, int *array, int N) {
    srand(time(NULL)); // seed random number generator

    *structArray = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (*structArray == NULL) {
        printf("Failed to allocate memory for structures.\n");
        return;
    }

    // Populate the structures
    for (int i = 0; i < N; i++) {
        (*structArray)[i].RX_UE_INFORMATION_TAG = array[i];
        (*structArray)[i].RNTI = rand();
        (*structArray)[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <filename>\n", argv[0]);
        return -1;
    }

    int N = 0;
    int *array = NULL;

    if(read_file(argv[1], &array, &N) != 0 || N == 0) {
        printf("Failed to read file or array is empty.\n");
        return -1;
    }

    print_largest_num(array, N);
    calculate_average(array, N, 5);
    validate_duplicates(array, N);

    NFAPI_CRC_INDICATION_PDU_T *structArray = NULL;
    populate_structures(&structArray, array, N);

    // Deallocate memory
    free(array);
    free(structArray);

    return 0;
}
