['```c
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <stdbool.h>

typedef struct Record {
    long offset;
    int key;
    int value;
    bool is_occupied;
} Record;

typedef struct Collection {
    size_t capacity;
    float growth_factor;
    size_t count;
    Record *records;
} Collection;

Collection *initialize_collection(size_t initial_capacity, float growth_factor) {
    assert(growth_factor > 1);

    Collection *col = malloc(sizeof(Collection));
    col->capacity = initial_capacity;
    col->growth_factor = growth_factor;
    col->count = 0;
    col->records = calloc(initial_capacity, sizeof(Record));

    return col;
}

void add_record(Collection *col, long offset, int key, int value) {
    for (size_t i = 0; i < col->capacity; ++i) {
        Record *rec = &col->records[i];
        if (!rec->is_occupied || rec->key == key) {
            rec->offset = offset;
            rec->key = key;
            rec->value = value;
            rec->is_occupied = true;
            ++col->count;
            return;
        }
    }

    col->capacity *= col->growth_factor;
    Record *new_records = realloc(col->records, sizeof(Record) * col->capacity);
    assert(new_records != NULL);
    col->records = new_records;

    add_record(col, offset, key, value);
}

int get_value(Collection *col, int key) {
    for (size_t i = 0; i < col->capacity; ++i) {
        if (col->records[i].is_occupied && col->records[i].key == key) {
            return col->records[i].value;
        }
    }

    assert(!"Key not found");
}
```
