```c
#include <stdlib.h>
#include <pthread.h>
#define MAX_BUFFER_SIZE 1024 // Define your own maximum buffer size

// Assume we are using a simple char* log message for simplicity
typedef char *logMessage; 

typedef struct {
    pthread_mutex_t lock;
    int currentIndex;
    logMessage buffer[MAX_BUFFER_SIZE];
} LogBuffer;

void initLogBuffer(LogBuffer *buffer) {
    pthread_mutex_init(&buffer->lock, NULL);
    buffer->currentIndex = 0;
}

int addToLogBuffer(LogBuffer *buffer, logMessage message) {
    pthread_mutex_lock(&buffer->lock);

    if (buffer->currentIndex < MAX_BUFFER_SIZE) {
        buffer->buffer[buffer->currentIndex++] = message;
        pthread_mutex_unlock(&buffer->lock);

        return 0; // Success
    } else {
        pthread_mutex_unlock(&buffer->lock);

        return -1; // Buffer is full
    }
}

logMessage *flushLogBuffer(LogBuffer *buffer) {
    pthread_mutex_lock(&buffer->lock);

    logMessage *oldBuffer = malloc(sizeof(logMessage) * buffer->currentIndex);
    for (int i = 0; i < buffer->currentIndex; ++i) {
        oldBuffer[i] = buffer->buffer[i];
    }

    buffer->currentIndex = 0; // Reset the buffer

    pthread_mutex_unlock(&buffer->lock);

    return oldBuffer;
}
```
This is a simple example of a thread-safe log buffer. The `addToLogBuffer` function can be used by multiple threads to add messages to a shared buffer. If the buffer becomes full, it will return an error indicating that the message wasn't added and needs to be handled appropriately (for instance, discarding or waiting until there is room).

The `flushLogBuffer` function returns a copy of the current contents of the buffer and clears it, allowing for efficient reuse of memory.

