['```C
#include <stdio.h>
#include <dirent.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <pthread.h>

pthread_mutex_t fileLock = PTHREAD_MUTEX_INITIALIZER;
FILE *outputStream;
char *dirPath;
int streamingMode = 0;

void usage(const char *progname) {
    fprintf(stderr, "Usage: %s [-h|--help] [-s] [-o output_file] [directory path]\n", progname);
}

void processDirectory() {
    DIR *dir = opendir(dirPath);
    if (dir == NULL) {
        perror("Error opening directory");
        return;
    }
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        char filePath[1024];
        snprintf(filePath, sizeof(filePath), "%s/%s", dirPath, entry->d_name);
        processFile(filePath);
    }
    closedir(dir);
}

void processFile(char *fileName) {
    pthread_mutex_lock(&fileLock);

    FILE *file = fopen(fileName, "r");
    if (file == NULL) {
        perror("Error opening file");
        return;
    }

    int fd = fileno(file);
    struct flock lock;
    memset(&lock, 0, sizeof(struct flock));
    lock.l_type = F_WRLCK;
    if (fcntl(fd, F_SETLKW, &lock) == -1) {
        perror("Error acquiring file lock");
        return;
    }

    char buffer[4096];
    size_t bytesRead;
    while ((bytesRead = fread(buffer, 1, sizeof(buffer), file)) > 0) {
        if (streamingMode) {
            fwrite(buffer, 1, bytesRead, outputStream);
        } else {
            fprintf(outputStream, "%.*s", (int)bytesRead, buffer);
        }
    }

    lock.l_type = F_UNLCK;
    if (fcntl(fd, F_SETLKW, &lock) == -1) {
        perror("Error releasing file lock");
    }

    pthread_mutex_unlock(&fileLock);
}

void *processFileThreaded(void *arg) {
    char *fileName = (char *)arg;
    processFile(fileName);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2 || strcmp(argv[1], "--help") == 0 || strcmp(argv[1], "-h") == 0) {
        usage(argv[0]);
        return 0;
    }

    outputStream = stdout;
    for (int i = 1; i < argc - 1; ++i) {
        if (strcmp(argv[i], "-s") == 0) {
            streamingMode = 1;
        } else if (strcmp(argv[i], "-o") == 0 && outputStream == stdout) {
            outputStream = fopen(argv[++i], "w");
            if (outputStream == NULL) {
                perror("Error opening output file");
                return 1;
            }
        } else if (dirPath == NULL) {
            dirPath = argv[i];
        }
    }

    if (!dirPath) {
        usage(argv[0]);
        return 0;
    }

    processDirectory();
    fclose(outputStream);

    return 0;
}
```
']

