```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int key;
    long offset;
    int value;
} Record;

Record* records = NULL;
int recordCount = 0;
int capacity = 16;
pthread_mutex_t lock;

void addRecord(int key, long offset, int value) {
    pthread_mutex_lock(&lock);
    if (records == NULL) {
        records = malloc(sizeof(Record) * capacity);
    } else if (recordCount >= capacity) {
        capacity *= 2;
        records = realloc(records, sizeof(Record) * capacity);
    }

    Record record = {key, offset, value};
    memcpy(&records[recordCount++], &record, sizeof(Record));
    pthread_mutex_unlock(&lock);
}

void retrieveRecord(int key, long* offset, int* value) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < recordCount; i++) {
        if (records[i].key == key) {
            *offset = records[i].offset;
            *value = records[i].value;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void updateRecord(int key, long offset, int value) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < recordCount; i++) {
        if (records[i].key == key) {
            records[i].offset = offset;
            records[i].value = value;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}
``` 

This code provides a simple solution for the record management part of your problem. It uses an array to store records and automatically resizes it when necessary. However, this doesn't include all aspects mentioned in the task such as exporting to a persistent storage format, collision resolution strategy, or advanced query capabilities. Please note that these tasks are highly dependent on your exact requirements and constraints, so you might need to make significant modifications based on these details. 

