["Here is an example of how you could implement this in C. It's important to note that this code doesn't include any actual network programming or database communication for simplicity, but it does use a dynamically allocated hash table to store items and their unique identifiers as keys.

This also assumes the existence of some basic database functions like `db_insert`, `db_update`, `db_get_by_id`, etc.

```c
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* identifier;
    int status;
    char* description;
} item;

item* item_new(char* identifier, int status, char* description) {
    item* new_item = malloc(sizeof(item));

    new_item->identifier = strdup(identifier);
    new_item->status = status;
    new_item->description = strdup(description);

    return new_item;
}

void item_delete(item* i) {
    free(i->identifier);
    free(i->description);
    free(i);
}

typedef struct _hashnode {
    char* key;
    item* data;
    struct _hashnode *next;
} hashnode;

#define TABLE_SIZE 1024
hashnode* table[TABLE_SIZE];

unsigned long hash(char *str) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % TABLE_SIZE;
}

void add_item(item* i) {
    unsigned long index = hash(i->identifier);

    hashnode* new_hashnode = malloc(sizeof(hashnode));
    new_hashnode->key = strdup(i->identifier);
    new_hashnode->data = i;
    new_hashnode->next = table[index];

    table[index] = new_hashnode;
}

item* get_item(char* identifier) {
    unsigned long index = hash(identifier);
    for (hashnode *node = table[index]; node != NULL; node = node->next)
        if (strcmp(node->key, identifier) == 0)
            return node->data;

    return NULL;
}

void update_item(char* identifier, item* new_i) {
    item* old_i = get_item(identifier);
    if (old_i != NULL) {
        db_update(identifier, new_i);

        free(old_i->description);
        old_i->status = new_i->status;
        old_i->description = strdup(new_i->description);
    } else {
        db_insert(identifier, new_i);
        add_item(new_i);
    }
}
```

This code is simplified and does not include error checking or handling network errors. In a real application you would want to use database transactions so that if an operation fails, it can be rolled back and the data remains consistent. You should also consider using a B-tree instead of a hash table for large collections as a B-tree allows for quicker access times and better scaling under heavy load conditions.
"]

