        free(session->buffer);
    }

    free(session);
}

NFCConfig* initializeNetworkInterface(int numSessions, PacketCallback cb) {
    NFCConfig *config = (NFCConfig*) malloc(sizeof(NFCConfig));

    if (!config) {
        printf("Failed to allocate memory for NFCConfig.\n");
        return NULL;
    }

    config->numSessions = numSessions;
    config->sessions = (NFCSession**) calloc(numSessions, sizeof(NFCSession*));

    if (!config->sessions) {
        printf("Failed to allocate memory for NFCConfig sessions.\n");
        free(config);
        return NULL;
    }

    for (size_t i = 0; i < numSessions; ++i) {
        config->sessions[i] = initializeNFCSession(i, cb);

        if (!config->sessions[i]) {
            printf("Failed to initialize NFCSession %zu.\n", i);

            for (size_t j = 0; j < i; ++j) {
                destroyNFCSession(config->sessions[j]);
            }

            free(config->sessions);
            free(config);
            return NULL;
        }
    }

    return config;
}

void destroyNetworkInterface(NFCConfig *config) {
    if (config && config->sessions) {
        for (size_t i = 0; i < config->numSessions; ++i) {
            destroyNFCSession(config->sessions[i]);
        }

        free(config->sessions);
    }

    free(config);
}
```
In this code, `initializeNetworkInterface` is responsible for allocating memory for the NFCConfig structure and the NFCSession instances. Each session is allocated with a unique ID and callback function, and each buffer for packet data is allocated with a pre-determined size (1024 bytes). In case of failure to allocate, an error message is printed and all previously allocated memory is freed before returning NULL.

The `destroyNetworkInterface` function frees the memory allocated by initializeNetworkInterface. It goes through each session in reverse order to free memory without risking a dangling pointer.
']

['Here's an implementation in C using OpenSSL library for AES-CBC decryption:
```c
#include <stdio.h>
