typedef struct Queue {
    size_t head;
    size_t tail;
    int* data;
    size_t size;
    pthread_mutex_t lock;
} Queue;

void enqueue(Queue* q, int value) {
    assert(q->tail < q->size); // ensure there's room in the queue

    pthread_mutex_lock(&q->lock);
    q->data[q->tail] = value;
    q->tail++;
    pthread_mutex_unlock(&q->lock);
}

int dequeue(Queue* q) {
    assert(q->head < q->tail); // ensure there's data in the queue

    int result = 0;
    pthread_mutex_lock(&q->lock);
    result = q->data[q->head];
    q->head++;
    pthread_mutex_unlock(&q->lock);
    return result;
}

void* allocateMemory(size_t size) {
    void* memory = malloc(size);

    if (memory == NULL) {
