void process_file_with_crc(char *filename, int digit_count, char *filetype) {
    FILE* logFile = fopen("error.log", "a"); // open a file to log errors

    if (!logFile) {
        perror("Error opening log file");
        return;
    }

    struct stat st;
    int seed = 0; // assume the last modified time as a seed

    if(stat(filename, &st) == 0) { 
        seed = (int) st.st_mtime; // cast to int and use it for seeding
    } else {
        fprintf(logFile, "Error getting file stats: %s\n", strerror(errno));
        return;
    }

    srand(seed);

    char newFilename[MAX_FILENAME_LEN];
    strcpy(newFilename, filename);
    sprintf(&newFilename[strlen(filename)],".%*d", digit_count, rand() % (int)pow(10,digit_count)); // append random digits to the original filename

    char extension[MAX_EXTENSION];
    sprintf(extension, "%s.%s", filetype, newFilename);

    int tries = 0;
    while (access(newFilename, F_OK) == 0 && tries < MAX_TRIES) { // if filename exists
        srand((unsigned int) time(NULL)); // regenerate random seed and continue search
        ++tries;
    }

    if (tries == MAX_TRIES) {
        fprintf(logFile, "Could not find a unique filename after %d tries\n", MAX_TRIES);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu;

