    pdu.RNTI = rand();
    sprintf(pdu.CRC_INDICATION_REL8_TAG.CRCFLAG, "%d", rand() % 2); // a boolean flag

    fprintf(logFile,"Successfully processed file: %s\n", newFilename);
    fclose(logFile);
}
