// For simplicity, a doubly linked list is used here.
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

Node *head = NULL;
Node *tail = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;  // Mutex for thread safety.
sem_t semaphore;  // Semaphore for capacity limitation.
int maxCapacity = 10000;  // Maximum list size.

void addNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    newNode->data = data;

    if (semaphore < 0 && sem_trywait(&semaphore) != 0) { // If list is full and semaphore wait failed.
        return;
    }

    pthread_mutex_lock(&lock);
    newNode->next = head;
    if (head != NULL) {
        head->prev = newNode;
    }
    head = newNode;
    if (tail == NULL) {  // If list was empty.
        tail = newNode;
    }
    pthread_mutex_unlock(&lock);
}

void removeNode(int rnti) {
    Node* temp = head;

    while(temp != NULL && temp->data.RNTI != rnti) {
        temp = temp->next;
    }
    if (temp == NULL) {  // RNTI not found in list.
        return;
    }

    pthread_mutex_lock(&lock);
    if(temp->prev != NULL) {
        temp->prev->next = temp->next;
    } else {
        head = temp->next;
    }
    if(temp->next != NULL) {
        temp->next->prev = temp->prev;
    } else {
        tail = temp->prev;
    }
    free(temp);

    sem_post(&semaphore);  // Notify list has a new space.
    pthread_mutex_unlock(&lock);
}

void updateNode(int rnti, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* temp = head;

    while(temp != NULL && temp->data.RNTI != rnti) {
        temp = temp->next;
    }
    if (temp == NULL) {  // RNTI not found in list.
        return;
    }

    pthread_mutex_lock(&lock);
    temp->data = data;
    pthread_mutex_unlock(&lock);
}
```
