    int value;
    char status; // Assuming 'status' is a single byte
} RecordStruct;

typedef struct {
    size_t currentSize;
    size_t maxCapacity;
    void* memoryPool;
    pthread_mutex_t mutex; 
} MemoryPool;

MemoryPool pool = {{0}, 1024 * 1024, NULL, PTHREAD_MUTEX_INITIALIZER}; // Initialize our memory pool with a max capacity of 1MB.

int initializeStructures(OffsetStruct* offset, KeyStruct* key, RecordStruct** records, int numRecords, long offsetValue, int keyValue) {
    pthread_mutex_lock(&pool.mutex); // Lock the mutex to ensure atomicity when reading/writing to the memory pool.

    if (pool.currentSize + sizeof(RecordStruct) * numRecords > pool.maxCapacity) {
        pthread_mutex_unlock(&pool.mutex);  // Unlock the mutex before returning in case of error to prevent deadlocks.
        return -1; // Return an error code if there isn't enough space left in the memory pool.
    }

    offset->offset = offsetValue;
    key->key = keyValue;
    *records = (RecordStruct*)&pool.memoryPool[pool.currentSize];

    for (int i = 0; i < numRecords; i++) {
        (*records)[i].value = rand() % 1000 + 1; // Assuming the record's value should be within [1, 1000]
        (*records)[i].status = 0;
    }

    pool.currentSize += sizeof(RecordStruct) * numRecords;

    pthread_mutex_unlock(&pool.mutex); // Unlock the mutex after we've finished writing to the memory pool.

    return 0; // Return success code if everything went as expected.
}
```
This solution provides a dynamic allocation mechanism with thread-safe operations to handle potential race conditions when multiple threads access the memory pool simultaneously. It checks for available space in the memory pool before trying to allocate more records, and it releases the lock on the mutex even in case of error, to prevent deadlocks. 
