#include <string.h>

typedef struct Node {
    long timestamp;
    char* data;
    struct Node *next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int add_node(long timestamp, const char* data) {
    pthread_mutex_lock(&lock);

    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        pthread_mutex_unlock(&lock);
        return -1; // allocation failed
    }

    newNode->timestamp = timestamp;
    newNode->data = strdup(data);
    if (newNode->data == NULL) {
        free(newNode);
        pthread_mutex_unlock(&lock);
        return -1; // allocation failed
    }

    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
    return 0; // success
}

int remove_node(const char* data) {
    pthread_mutex_lock(&lock);

    Node** pp = &head;
    while(*pp != NULL) {
        if (strcmp((*pp)->data, data) == 0) {
            Node *tmp = *pp;
            *pp = tmp->next;
            free(tmp->data);
            free(tmp);
            break;
        }
        pp = &(*pp)->next;
    }

    pthread_mutex_unlock(&lock);
}
