Task 2: Utility class in C# to handle random value generation within a specified range.
```csharp
using System;

public class RandomValueGenerator {
    private int _minValue;
    private int _maxValue;

    public RandomValueGenerator(int minValue, int maxValue) {
        if (minValue > maxValue) {
            throw new ArgumentException("Minimum value cannot be greater than maximum value.");
        }

        this._minValue = minValue;
        this._maxValue = maxValue;
    }

    public int GetRandomInt() {
        Random rand = new Random();
        return rand.Next(_minValue, _maxValue + 1);  // Add 1 to include the maximum value
    }

    public float GetRandomFloat() {
        Random rand = new Random();
        double fraction = rand.NextDouble();

        double result = _minValue + (fraction * (_maxValue - _minValue));
        return (float)result;
