['Below is a simplified version of how you might structure such a function. This implementation uses a doubly linked list for its core data structure. The functions `add_record`, `remove_record` and `iterate_records` handle the addition, removal and iteration over records respectively. 

```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <pthread.h>

// Define the record structure
typedef struct record {
    int key;
    char *str;
    UE_TX_POWER_REPORT txPowerReport;
    RSSI* rssiValues;
    size_t rssiValueCount;

    struct record *prev;
    struct record *next;
} Record;

// Define the list structure
typedef struct {
    pthread_mutex_t mutex;
    Record *head;
    Record *tail;
} List;

// Function to create a new record
Record* create_record(int key, char *str, UE_TX_POWER_REPORT txPowerReport, RSSI *rssiValues, size_t rssiValueCount) {
    Record *new_node = (Record*) malloc(sizeof(Record));

    if (new_node == NULL) return NULL; // Handle allocation failures

    new_node->key = key;
    new_node->str = strdup(str);
    new_node->txPowerReport = txPowerReport;
    new_node->rssiValues = rssiValues;
    new_node->rssiValueCount = rssiValueCount;

    return new_node;
}

// Function to add a record
void add_record(List *list, Record *new_rec) {
    if (pthread_mutex_lock(&list->mutex)) {
        // Handle error
    }

    if (list->tail == NULL) {
        list->head = new_rec;
        list->tail = new_rec;
    } else {
        list->tail->next = new_rec;
        new_rec->prev = list->tail;
        list->tail = new_rec;
    }

    if (pthread_mutex_unlock(&list->mutex)) {
        // Handle error
    }
}

// Function to remove a record
void remove_record(List *list, Record *record) {
    if (pthread_mutex_lock(&list->mutex)) {
        // Handle error
    }

    if (record->prev != NULL) {
        record->prev->next = record->next;
    } else {
        list->head = record->next;
    }

    if (record->next != NULL) {
        record->next->prev = record->prev;
    } else {
        list->tail = record->prev;
    }

    free(record);

    if (pthread_mutex_unlock(&list->mutex)) {
        // Handle error
    }
}

// Function to iterate over records
void iterate_records(List *list, void (*callback)(Record*)) {
    Record *current = list->head;

    while (current != NULL) {
        callback(current);
        current = current->next;
    }
}
```

This is a basic implementation and doesn't include the memory management for RSSI values or string, which would depend on your specific requirements. 
