['Implementing this in C would involve interacting with system calls for DNS resolution and managing threads. Here is a simplified version of how it could be done using POSIX pthreads library:

```C
#include <pthread.h>
#include <netdb.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <time.h>
#include <stdio.h>

#define MAX_ENTRIES 1024
#define MAX_CACHE_SIZE 512000

typedef struct {
    char hostname[256];
    struct in_addr ip;
    time_t resolvedTime;
} cacheEntry;

cacheEntry cache[MAX_ENTRIES];
int currentCacheSize = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
FILE *logFile;
int loggingLevel = 2; // 1: error, 2: warning/error, 3: info/warning/error

void logEvent(int level, char* message) {
    if (level <= loggingLevel) {
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[80];
        strftime(timestamp, 80, "%F %T", timeinfo);

        fprintf(logFile, "[%s] %s: %s\n", timestamp, level == 1 ? "ERROR" : (level == 2 ? "WARNING" : "INFO"), message);
    }
}

struct in_addr resolveDNS(char* hostname) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < MAX_ENTRIES; ++i) {
        if (!strcmp(hostname, cache[i].hostname)) {
            time_t currentTime = time(NULL);
            double elapsedSeconds = difftime(currentTime, cache[i].resolvedTime);
            pthread_mutex_unlock(&lock);

            if (elapsedSeconds < 60) { // TTL of 1 minute
                logEvent(3, "Cache hit");
                return cache[i].ip;
            } else {
                break;
            }
        }
    }

    pthread_mutex_unlock(&lock);

    struct hostent *host = gethostbyname(hostname);
    if (host == NULL) {
        logEvent(1, "Failed to resolve DNS");
        return;
    }

    struct in_addr **addressList = (struct in_addr **) host->h_addr_list;
    pthread_mutex_lock(&lock);
    for (; currentCacheSize < MAX_ENTRIES && addressList[currentCacheSize] != NULL; ++currentCacheSize) {
        strncpy(cache[currentCacheSize].hostname, hostname, sizeof(cache[0].hostname));
        cache[currentCacheSize].ip = *addressList[currentCacheSize];
        cache[currentCacheSize].resolvedTime = time(NULL);
    }

    if (currentCacheSize == MAX_ENTRIES) { // Evict LRU entry
        int lruIndex = 0;
        for (int i = 1; i < currentCacheSize; ++i) {
            if (difftime(time(NULL), cache[i].resolvedTime) > difftime(time(NULL), cache[lruIndex].resolvedTime)) {
                lruIndex = i;
            }
        }

        currentCacheSize -= 1;
        memmove(&cache[lruIndex], &cache[lruIndex + 1], (currentCacheSize - lruIndex) * sizeof(cacheEntry));
    }

    pthread_mutex_unlock(&lock);

    logEvent(3, "Successfully resolved DNS");
    return *addressList[0];
}
``` 

This is a highly simplified version of what you're asking for. It doesn't cover all the edge cases and error handling that would be needed in a production environment. Also, this code doesn't enforce any resource usage limits or provide low-latency guarantees as those are quite complex to implement properly. A production quality DNS resolver in C would need to have much more robust error handling and logging mechanisms, and also be integrated into an existing service architecture.
']

