LOG_RECORD* logs;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
size_t currentIndex = 0;
int initialized = 0;

void initializeLoggingSystem(size_t size) {
    if (initialized == 1) return;

    // Ensure thread-safe initialization 
    pthread_mutex_lock(&lock);
    if (!initialized){
        logs = malloc(size * sizeof(LOG_RECORD));

        if (logs == NULL) {
            fprintf(stderr, "Error allocating memory for log records. Exiting.\n"); 
            exit(EXIT_FAILURE);
        }

        initialized = 1;
    }
    pthread_mutex_unlock(&lock);  
}

void appendLogRecord(int logLevel, char* message, void* metadata) {
    // Protect against memory exhaustion by checking if we have room for a new log record
    pthread_mutex_lock(&lock);

    if (currentIndex < MAX_LOG_RECORDS){
        LOG_RECORD* record = &logs[currentIndex++];

        // Populate the log record fields
        record->logLevel = logLevel;
        time(&record->timestamp);
        record->message = message; 
        record->metadata = metadata;

        // Asynchronously send to external logging service
        sendToExternalLoggingService(record);
    } else {
        fprintf(stderr, "Error: Memory exhausted. Dropping log record.\n");
    }

    pthread_mutex_unlock(&lock);
}
```

