['Here's an outline for such a complex command-line utility in C using glib. Note that this code doesn't actually perform any file or network operations, because it's quite complex to fully implement them. But you can use the provided functions as a basis and extend them according to your specific requirements:

```C
#include <glib.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

void print_usage() {
  g_printerr("Usage:\n");
  g_printerr("  -cs <keyword>  Check for a specific keyword in each line of the input file.\n");
  g_printerr("  -o <output_file>  Specify an output file where results are saved instead of printing to the console.\n");
  g_printerr("  -u <url>  Specify a remote URL from which the input file can be downloaded if local access is unavailable.\n");
  g_printerr("  --help  Display comprehensive usage instructions.\n");
}

gboolean check_keyword(char *line, char *keyword) {
  return strstr(line, keyword);
}

void process_file(char *filename, char *keyword, char *output_filename) {
  gchar *contents;
  gsize length;
  if (!g_file_get_contents(filename, &contents, &length, NULL)) {
    g_printerr("Error reading file: %s\n", filename);
    exit(1);
  }

  GString *output = g_string_new("");

  char *line;
  int keyword_count = 0;
  int total_length = 0;
  for (line = strtok(contents, "\n"); line != NULL; line = strtok(NULL, "\n")) {
    if (check_keyword(line, keyword)) {
      keyword_count++;
      total_length += strlen(line);

      g_string_append_printf(output, "Keyword found in line: %s\n", line);
    }
  }

  double average_length = (keyword_count > 0) ? ((double)total_length / keyword_count) : 0.0;

  g_string_append_printf(output, "Average length of lines containing the keyword: %f\n", average_length);

  if (!g_strcmp0(output_filename, "")) {
    // Print to console
    g_print("%s\n", output->str);
  } else {
    GError *error = NULL;
    g_file_set_contents(output_filename, output->str, strlen(output->str), &error);
    if (error != NULL) {
      g_printerr("Error writing to file: %s\n", error->message);
      exit(1);
    }
  }

  g_string_free(output, TRUE);
  free(contents);
}

int main(int argc, char *argv[]) {
  GOptionContext *context;
  GError *error = NULL;

  context = g_option_context_new("- command line options");
  GOptionEntry entries[] = {
    {"cs", 'c', 0, G_OPTION_ARG_STRING, &keyword, "Check for a specific keyword in each line of the input file", NULL},
    {"o", 'o', 0, G_OPTION_ARG_FILENAME, &output_filename, "Specify an output file where results are saved instead of printing to the console", NULL},
    {"u", 'u', 0, G_OPTION_ARG_STRING, &url, "Specify a remote URL from which the input file can be downloaded if local access is unavailable", NULL},
    {NULL}
  };

  g_option_context_add_main_entries(context, entries, NULL);
  if (!g_option_context_parse(context, &argc, &argv, &error)) {
    g_printerr("Error parsing options: %s\n", error->message);
    exit(1);
  }

  process_file(filename, keyword, output_filename);

  return 0;
}
```

This code is just a basic starting point. A real-world program would need to be much more complex, including error handling for all possible edge cases and failure modes, performance optimizations, etc. It's also worth noting that C isn't typically used for this type of task in production environments; modern languages like Python or Go are often a better choice due to their higher level abstractions and built-in libraries for networking, filesystem operations, and more.
