['The implementation will require creating a custom `ScriptLoader` class that can handle all these requirements. Here's an example of how you could approach the task with some pseudocode:

```javascript
class ScriptLoader {
  constructor(maxLimit, logger) {
    this.loadedScriptCount = 0;
    this.maxLimit = maxLimit || 5;
    this.logger = logger || console;
    this.scriptCache = {};
  }

  validateScript(src, integrity, crossorigin) {
    // Validate src, integrity and crossorigin attributes of the script object here
    // Return true if valid, false otherwise
  }

  async loadScriptAsync(src, integrity, crossorigin, isDeferred = false) {
    const self = this;

    return new Promise((resolve, reject) => {
      if (self.loadedScriptCount >= self.maxLimit) {
        return reject("Maximum limit of scripts reached");
      }

      if (!self.validateScript(src)) {
        return reject("Invalid script object");
      }

      // check cache before creating a new request
      const cachedScript = self.scriptCache[src];
      if (cachedScript) {
        return resolve(cachedScript);
      }

      let scriptTag = document.createElement('script');
      scriptTag.onload = function() {
        self.logger.log("Loaded: " + src);
        self.loadedScriptCount++;
        // cache the loaded script for future use
        self.scriptCache[src] = scriptTag;
        resolve(scriptTag);
      };

      scriptTag.onerror = function() {
        delete self.scriptCache[src];
        reject("Error loading: " + src);
      };

      if (integrity) scriptTag.setAttribute('integrity', integrity);
      if (crossorigin) scriptTag.setAttribute('crossorigin', crossorigin);
      scriptTag.defer = isDeferred;
      scriptTag.async = !isDeferred; // load scripts immediately if deferred loading isn't supported or fails

      document.body.appendChild(scriptTag);
    });
  }
}
```
This code creates a `ScriptLoader` class with methods to validate and asynchronously load scripts into the webpage, ensuring that only valid scripts are loaded and memory usage is optimized by caching script tags. The class also logs events related to script loading using a custom logger.
