angular.module('app', [])
  .controller('MainController', function($scope, $http) {
    const dialogFields = ['field1', 'field2', 'field3'];
    const fieldNamesToRefresh = ['field1', 'field3'];
    $scope.refreshDialogFields = function() {
      let timestamp = new Date().getTime();
      return Promise.all(dialogFields.map(fieldName => {
        if (fieldNamesToRefresh.includes(fieldName)) {
          return sendMessageAndUpdateField($http, fieldName, timestamp)
            .catch(() => retrySendMessageAndUpdate(3));
        }
      })).then(() => {
        // Log successful update
        localStorage.setItem('lastUpdate', JSON.stringify({ timestamp: timestamp, outcome: 'success' }));
      }).catch((error) => {
        // Log failed update
        localStorage.setItem('lastUpdate', JSON.stringify({ timestamp: timestamp, outcome: 'failure', error: error }));
      });
    };

    function sendMessageAndUpdateField($http, fieldName, timestamp) {
      return $http.post('/api/updateField', { fieldName, timestamp })
        .then((response) => {
          // update the dialog field as per response
          $scope[fieldName] = response.data;
        });
    }

    function retrySendMessageAndUpdate(retriesLeft, backoff = 0) {
      return new Promise((resolve, reject) => {
        setTimeout(() => {
          if (retriesLeft > 0) {
            resolve(sendMessageAndUpdateField().catch(() => retrySendMessageAndUpdate(--retriesLeft, Math.pow(2, 3 - retriesLeft))));
          } else {
            reject();
          }
        }, backoff * 1000);
      });
    }
  });
```

