        printf("Invalid input: %d\n", n);
        return 0;
    }
    return 1;
}

record* create_arrays(long** offsets, int** keys, record** records, int size) {
    *offsets = calloc(size, sizeof(long));
    if (*offsets == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    *keys = calloc(size, sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        printf("Memory allocation failed\n");
        return NULL;
    }

    *records = malloc(size * sizeof(record));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Initialize arrays
    for (int i = 0; i < size; ++i) {
        (*records)[i].value = i;
        (*records)[i].offset = &(*offsets)[i];
        (*keys)[i] = i;
        (*records)[i].key = *keys[i];
    }

    return *records;
}

int main() {
    int size = 10;  // user input here
    long* offsets;
    int* keys;
    record* records;

    if (!validate_input(size)) {
