import java.util.concurrent.*;
import java.util.logging.*;

public class AsyncClient {
    private final ConnectionFactory factory = new ConnectionFactory();
    private List<String> serverAddresses;
    private Map<String, Integer> serverFailures = new HashMap<>();
    private Random randomGenerator = new Random();

    public AsyncClient(List<String> serverAddresses) {
        this.serverAddresses = serverAddresses;
        factory.setHost("localhost");
    }

    // Connect to a server
    Connection connectToServer() throws IOException, TimeoutException {
        return factory.newConnection();
    }

    // Choose the server based on load balancing policy
    String chooseServer(String roundRobin) {
        int index = randomGenerator.nextInt(serverAddresses.size());
        String serverAddress = serverAddresses.get(index);

        if (roundRobin == "true") {
            return serverAddress;
        } else {
            // Implement your own logic for load balancing e.g., least connection, round robin etc
        }
    }

    // Send message to a server and handle transient failures with exponential backoff
    void sendMessage(String server, String queueName, byte[] message) throws IOException {
        Connection connection = factory.newConnection();
        Channel channel = connection.createChannel();
        AMQP.BasicProperties properties = new AMQP.BasicProperties().builder().expiration("60000").build();

        try {
            serverFailures.put(server, 0);
            channel.basicPublish("", queueName, properties, message);
        } catch (IOException e) {
            int failures = serverFailures.getOrDefault(server, 0);
            serverFailures.put(server, ++failures);
            handleFailure(server, failures, queueName, message);
        } finally {
            channel.close();
            connection.close();
        }
    }

    // Handle transient failures with exponential backoff and retry policy
    private void handleFailure(String server, int failureCount, String queueName, byte[] message) throws IOException {
        if (failureCount > 3) {
            // If more than 3 attempts fail then we might want to stop trying this server.
            serverFailures.remove(server);
            return;
        }

        try {
            int sleepTime = (int) Math.pow(2, failureCount - 1) * 1000 + new Random().nextInt(500); // exponential backoff with jitter
            Thread.sleep(sleepTime);
            sendMessage(server, queueName, message);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}
``` 
