["Here is an example of how you can implement this in python:

```python
import csv
import json
import xml.etree.ElementTree as ET
from queue import Queue
from threading import Thread, Lock
from requests import Session

class NFAPIProcessor:
    def __init__(self, config_file, data_format):
        self.config = self._load_and_validate(config_file, data_format)
        self.api = APIInterface()
        self.queue = Queue()
        self.lock = Lock()
        self.successful = 0
        self.failed = 0

    def _load_and_validate(self, config_file, data_format):
        if data_format == 'CSV':
            with open(config_file, 'r') as f:
                reader = csv.DictReader(f)
                return list(reader)
        elif data_format == 'JSON':
            with open(config_file, 'r') as f:
                config = json.load(f)
                return config['network_entities']
        elif data_format == 'XML':
            tree = ET.parse(config_file)
            root = tree.getroot()
            return [{child.tag: child.text for child in entity} for entity in root]

    def _process_entity(self, entity):
        if self.api.is_valid(entity):
            with self.lock:
                self.successful += 1
        else:
            with self.lock:
                self.failed += 1

    def process(self, num_threads=4):
        for entity in self.config:
            self.queue.put(entity)

        threads = []
        for i in range(num_threads):
            t = Thread(target=self._worker)
            t.start()
            threads.append(t)

        # wait for all threads to complete
        self.queue.join()

        # stop workers
        for i in range(num_threads):
            self.queue.put(None)
        for t in threads:
            t.join()

    def _worker(self):
        while True:
            entity = self.queue.get()
            if entity is None:
                break
            self._process_entity(entity)
            self.queue.task_done()

class APIInterface:
    def __init__(self, max_retries=3):
        self.session = Session()
        self.max_retries = max_retries

    def is_valid(self, entity, retry=0):
        try:
            response = self.session.post('http://api-endpoint', json=entity)
            if response.status_code == 200:
                return True
            else:
                return False
        except Exception as e:
            print(f'Error during API request: {e}')

        if retry < self.max_retries:
            return self.is_valid(entity, retry + 1)
        else:
            raise Exception('Max retries reached')
```
This code creates a NFAPIProcessor class that reads and validates the configuration file, processes entities in parallel using threads for better efficiency, and integrates with an APIInterface to validate real-time data. It also includes error handling, thread safety, and retry mechanism for API requests. However, this is a high-level implementation and doesn't handle all specific cases or edge scenarios.
"]

['Here's a possible implementation of such a Java method, using `java.util.concurrent` package and `ObjectInputStream` with try-with-resources block for auto-closing:

```java
import java.io.*;
import java.nio.file.*;
import java.util.concurrent.*;
import java.security.MessageDigest;
import javax.xml.bind.DatatypeConverter;

public class StateLoader {
    private static final ExecutorService executor = Executors.newCachedThreadPool();
    private MessageDigest md;

    public CompletableFuture<MoSTState> load(Path path) throws IOException, NoSuchAlgorithmException {
        return CompletableFuture.supplyAsync(() -> {
            MoSTState state = null;
            try (ObjectInputStream inStream = new ObjectInputStream(Files.newInputStream(path))) {
                String expectedHash = Files.readAllLines(Paths.get(path.toString() + ".md5")).get(0);

                md = MessageDigest.getInstance("MD5");
                try (DigestInputStream dis = new DigestInputStream(Files.newInputStream(path), md)) {
                    dis.on(true); // enable MD5 check on read operations
                    Object obj = inStream.readObject();

                    if (obj instanceof MoSTState) {
                        state = (MoSTState) obj;

                        String actualHash = DatatypeConverter.printHexBinary(md.digest());

                        if (!expectedHash.equalsIgnoreCase(actualHash)) {
                            System.err.println("Error: file is corrupted.");
                            state = null;
                        } else if (!state.validate()) { // custom deserialization validation
                            System.err.println("Error: invalid MoSTState object.");
                            state = null;
                        }
                    } else {
                        System.err.println("Error: file does not contain a valid MoSTState object.");
                    }
                } catch (ClassNotFoundException | IOException e) {
                    e.printStackTrace();
                }
            } catch (IOException | ClassNotFoundException | InvalidPathException | OutOfMemoryError e) {
                System.err.println("Error: unable to load state object from file.");
                e.printStackTrace();
            }

            return state;
        }, executor);
    }
}
```
Please replace `MoSTState` and its methods as necessary for your specific use case. The MD5 hash file is assumed to be the same path of the object file with ".md5" appended at the end, and should contain a single line which is an expected hash value. The method can throw exceptions like IOException, ClassNotFoundException, InvalidPathException or OutOfMemoryError that you might want to handle in your code. It's important to note that this is a simple example for educational purposes only, you would need to consider further factors such as error handling on disk IO operations and ensuring the MD5 hash file and object file are always updated together.
