#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

typedef struct Record {
    long offset;
    int key;
} Record;

int read_long(FILE* file, long* value) {
    return fscanf(file, "%ld", value) == 1;
}

int read_int(FILE* file, int* value) {
    return fscanf(file, "%d", value) == 1;
}

Record* allocate_records(const char* filename, size_t* recordCount) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        perror("Failed to open file");
        return NULL;
    }

    *recordCount = 0;
    Record records[1024]; // initialize with some reasonable default size

    while (!feof(file)) {
        long offset;
        int key;
        if (read_long(file, &offset) && read_int(file, &key)) {
            if (*recordCount >= sizeof(records)/sizeof(Record)) {
                fprintf(stderr, "Too many records\n");
                break;
            }
            Record record = { .offset = offset, .key = key };
            records[(*recordCount)++] = record;
        } else {
            if (ferror(file)) {
                perror("Failed to read file");
            } else {
                fprintf(stderr, "Invalid line\n");
            }
            break;
        }
    }

    Record* result = malloc(*recordCount * sizeof(Record));
    if (result == NULL) {
        perror("Failed to allocate memory for records");
    } else {
        memcpy(result, records, *recordCount * sizeof(Record));
    }

    fclose(file);
    return result;
}
```
