#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    double value;
    char string[20];
} Record;

typedef struct {
    int key;
    Record* record;
} Metadata;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int currentKey = 1;  // starting key value

Record* createRecord(double min, double max) {
    Record *record = (Record*) malloc(sizeof(Record));
    if (record == NULL) {
        fprintf(stderr, "Memory allocation error\n");
        exit(1);  // Exit the program on memory allocation failure
    }

    record->value = ((double)rand() / RAND_MAX) * (max - min) + min;
    sprintf(record->string, "%f", record->value);

    return record;
}

Metadata* createMetadata() {
    Metadata *metadata = (Metadata*) malloc(sizeof(Metadata));
    if (metadata == NULL) {
        fprintf(stderr, "Memory allocation error\n");
        exit(1);  // Exit the program on memory allocation failure
    }

    pthread_mutex_lock(&lock);
    metadata->key = currentKey++;
    pthread_mutex_unlock(&lock);

    return metadata;
}

void freeMemory(Record *record, Metadata *metadata) {
    if (record != NULL) {
        free(record);
    }

    if (metadata != NULL) {
        free(metadata);
    }
}
```
This implementation allocates memory for the structs using `malloc` and frees them upon function exit or error using `free`. The record's double value is set to a random floating-point number within a specified range, while each metadata object's key is initialized to a unique integer starting from 1.

This implementation uses a mutex lock to ensure thread safety when assigning keys, so multiple threads can access and modify the currentKey without causing data races. This solution is simple for explanation purposes, but may not be optimal in real-world scenarios due to limitations like system resources, efficiency considerations, or other performance concerns.
