        $this->db = $dbConnection;
        $this->configFilePath = $filePath;
        $this->restApiEndpoint = $apiEndpoint;

        // Inject necessary headers for REST API authentication 
        $this->headers = [
            'Content-Type: application/json',
            'Authorization: Bearer your_access_token'
        ];
    }

    public function updateClinicStatus($clinicId, $newStatus) {
        $fileContents = $this->readConfigFile();

        if ($fileContents) {
            $parsedJson = json_decode($fileContents, true);
            // Update status in JSON configuration file
            $parsedJson['status'] = $newStatus;

            $checksum = md5(json_encode($parsedJson));

            $this->writeConfigFile(json_encode($parsedJson), $checksum);

            // Update database with new status, IP and date
            $query = "UPDATE clinics SET status=?, last_modified_ip=?, last_modified_date=NOW() WHERE id=?";
            $stmt = $this->db->prepare($query);
            $stmt->execute([$newStatus, $_SERVER['REMOTE_ADDR'], $clinicId]);
        } else {
            throw new Exception('Failed to read or parse the JSON configuration file.');
        }
    }

    private function readConfigFile() {
        $fileContents = '';

        $handle = fopen($this->configFilePath, "r");
        while (!feof($handle)) {
            $buffer = fread($handle, 4096); // Read in chunks for buffered I/O
            $fileContents .= $buffer;
        }

        fclose($handle);
        return $fileContents;
    }

    private function writeConfigFile($newContent, $checksum) {
        $ch = curl_init();

        curl_setopt($ch, CURLOPT_URL, $this->restApiEndpoint);
