        curl_setopt($ch, CURLOPT_POSTFIELDS, ['file' => $newContent, 'checksum' => $checksum]);
        curl_setopt($ch, CURLOPT_HTTPHEADER, $this->headers);

        $response = curl_exec($ch);

        // Verify checksum and retry mechanism if checksum does not match 
        $remoteChecksum = $this->getRemoteFileChecksum();
        if ($checksum !== $remoteChecksum) {
            throw new Exception('Data integrity check failed after modification. Please try again.');
        }

        curl_close($ch);
    }

