typedef enum { DEFLATE, ZLIB, LZMA, ZSTD, NO_COMPRESSION } compression_type;

// Compressed data structure
typedef struct compressed_data_structure{
    compression_type type;
    size_t original_size;
    size_t compressed_size;
    double processing_time;
} compressed_data_structure;

compressed_data_structure* compress(void* data, size_t size, compression_type preferred_type){

    // Error handling for external data sources can be added here...

    compressed_data_structure *cds = malloc(sizeof(compressed_data_structure));
    if (cds == NULL) {
        printf("Memory allocation failed!\n");
        return NULL; 
    }

    cds->original_size = size;
    double processing_time = 0.0;
    size_t compressed_size = 0;

    // Implement no compression option for testing purposes...
    if(preferred_type == NO_COMPRESSION){
        compressed_size = size;
        cds->compressed_size = size;
        processing_time += 0.1;  // For testing, we assume a small constant time.

    }else{
        switch(preferred_type) {
            case DEFLATE:
                compressed_size = deflate_compress((uint8_t*)data, size);
                processing_time += 0.2;  // For testing, we assume a small constant time.
                break;

            case ZLIB:
                compressed_size = zlib_compress((uint8_t*)data, size);
                processing_time += 0.3;  // For testing, we assume a small constant time.
                break;

            case LZMA:
                compressed_size = lzma_compress((uint8_t*)data, size);
                processing_time += 0.4;  // For testing, we assume a small constant time.
                break;

            case ZSTD:
                compressed_size = zstd_compress((uint8_t*)data, size);
                processing_time += 0.5;  // For testing, we assume a small constant time.
                break;

            default:
                printf("Unsupported compression type\n");
        }
    }

    cds->type = preferred_type;
    cds->processing_time = processing_time;
    cds->compressed_size = compressed_size;

    return cds;
}
