void processIntegersAndGenerateCRC(int* arr, std::size_t size) {
    // Initialize random number generator and distribution
    std::random_device rd;  
    std::mt19937 gen(rd()); 
    std::uniform_int_distribution<> dis(0, 1);

    auto start = std::chrono::high_resolution_clock::now();

    for (std::size_t i = 0; i < size; ++i) {
        // Fill the array with random integers within a specified range
        arr[i] = dis(gen);
    }

    auto end = std::chrono::high_resolution_clock::now();
    std::cout << "Filling array took " << std::chrono::duration<double, std::milli> (end-start).count() << " ms\n";

    // Find and print the largest integer in the array
    int max = *std::max_element(arr, arr + size);
    std::cout << "Largest element is " << max << '\n';

    // Generate a list of NFAPI_CRC_INDICATION_PDU_T structures
    auto crcs = new NFAPI_CRC_INDICATION_PDU_T[size];

    start = std::chrono::high_resolution_clock::now();

    for (std::size_t i = 0; i < size; ++i) {
        // Populate the structures with random values for CRCFLAG 
