#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#define MAX_INTERFACES 1024 /* define the maximum number of interfaces */

/* Define structure for network interface configuration */
typedef struct {
    unsigned long mac_stats;
    int timeout;
} NetworkInterfaceConfig;

/* Define structure for a node in linked list */
typedef struct Node{
    NetworkInterfaceConfig config;
    struct Node *next;
} Node;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; /* declare a mutex for thread safety */

Node* initializeNetworkInterfaces(int num_interfaces){
    if (num_interfaces <= 0 || num_interfaces > MAX_INTERFACES) {
        printf("Error: Invalid number of interfaces.\n");
        return NULL; /* Return error */
    }

    pthread_mutex_lock(&mutex); /* Lock the mutex before critical section */

    Node *head = NULL, *tail = NULL; 

    for(int i = 0; i < num_interfaces; ++i){
        Node *newNode = (Node*)malloc(sizeof(Node));

        if(newNode == NULL) {
            printf("Error: Failed to allocate memory.\n");
            pthread_mutex_unlock(&mutex); /* Unlock the mutex before return */
            return NULL;  /* Return error */
        }

        newNode->config.mac_stats = 0;
        newNode->config.timeout = 1000; /* Default timeout */
        newNode->next = NULL;

        if(head == NULL) {
            head = newNode;
            tail = newNode;
        } else {
            tail->next = newNode;
            tail = newNode;
        }
    }

    pthread_mutex_unlock(&mutex); /* Unlock the mutex after critical section */
    printf("Successfully allocated memory for %d interfaces.\n", num_interfaces);

    return head; 
}
```
Please note that in a real-world environment, error handling would be more extensive and logging would likely include information about where and why the error occurred. Moreover, actual MAC layer statistics would require additional code to fetch this data, which is beyond the scope of this simple example. Also, the allocation method used (linked list) is suitable for scenarios where interfaces can grow or shrink at runtime, as it allows dynamic memory management efficiently.
