void initDynamicList(DynamicList* dl, size_t initialSize) {
    dl->data = (NFAPI_UL_CCCH_MSG_T*)malloc(initialSize * sizeof(NFAPI_UL_CCCH_MSG_T));
    dl->used = 0;
    dl->size = initialSize;
}

void insertDynamicList(DynamicList* dl, NFAPI_UL_CCCH_MSG_T element) {
    if (dl->used == dl->size) {
        dl->size *= 2;
        dl->data = (NFAPI_UL_CCCH_MSG_T*)realloc(dl->data, dl->size * sizeof(NFAPI_UL_CCCH_MSG_T));
    }
    dl->data[dl->used++] = element;
}

