    node->frame = frame;

    pthread_mutex_lock(&lock);
    node->next = head;
    head = node;
    atomic_fetch_add(&num_nodes, 1);
    pthread_mutex_unlock(&lock);
}

void remove_frame(Node* prev, Node* node) {
