typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Node *head = NULL;

int insert(NFAPI_CRC_INDICATION_PDU_T val) {

    if (val.RNTI < 0 || val.RNTI > 16383) return -1; // invalid RNTI

    pthread_mutex_lock(&lock);  // locking before critical section for concurrency control

    Node *curr = head;
    while (curr != NULL) {
        if (curr->data.RNTI == val.RNTI) { // duplicate RNTI, return error code
            pthread_mutex_unlock(&lock); 
            return -2;
        }
        curr = curr->next;
    }

    Node *tempNode = (Node *)malloc(sizeof(Node));
    if (!tempNode) { // insufficient memory for new node, return error code
        pthread_mutex_unlock(&lock); 
        return -3;
    }

    tempNode->data = val;
    tempNode->next = head;
    head = tempNode;

    pthread_mutex_unlock(&lock); // unlocking after critical section to allow other threads access

    return 0; // operation successful, return success code
}
```
This code creates a singly linked list where each node contains an `NFAPI_CRC_INDICATION_PDU_T`. The function `insert()` takes in an `NFAPI_CRC_INDICATION_PDU_T` and adds it to the start of the list if it does not have a duplicate RNTI. It also protects against race conditions by locking the list before modifying and unlocking afterwards.

