    sem_init(&semaphore, 0, 10); // Initialize semaphore to allow up to 10 concurrent threads

    for (int i = 0; i < size; ++i) {
        sem_wait(&semaphore); // Wait for a free slot in the semaphore

        pthread_create(&threads[i % 10], NULL, measure, &list[i]); // Start a new thread to process measurement
    }

    /* Wait for all threads to finish processing */
    for (int i = 0; i < 10 && i < size; ++i) {
        pthread_join(threads[i], NULL); 
    }
}
