["To implement this requirement we can use PHP's inbuilt functions `uniqid`, `password_hash`, `openssl_random_pseudo_bytes` for generating unique session tokens and secure password hashing respectively. Here is an example of how you might create such a function.

```php
<?php
class SessionManager {
    private $tokenAlgorithm;
    private $passwordHashAlgorithm;

    public function __construct($tokenAlgorithm, $passwordHashAlgorithm) {
        $this->tokenAlgorithm = $tokenAlgorithm;
        $this->passwordHashAlgorithm = $passwordHashAlgorithm;
    }

    // Generate unique session token
    private function generateSessionToken() {
        return bin2hex(openssl_random_pseudo_bytes(16));
    }

    // Securely hash password
    public function hashPassword($password) {
        return password_hash($password, $this->passwordHashAlgorithm);
    }

    // Create a new session for the user
    public function createSession($userId, $username, $password) {
        $sessionToken = $this->generateSessionToken();

        try {
            $hashedPassword = $this->hashPassword($password);

            // Assuming you have a Database class with methods like beginTransaction, commit and rollback. 
            // Also assuming the session table has fields 'session_token', 'user_id', 'username' and 'password'
            $db = new Database();
            $db->beginTransaction();

            $sessionData = [
                'session_token' => $sessionToken,
                'user_id' => $userId,
                'username' => $username,
                'password' => $hashedPassword
            ];

            if ($db->insert('sessions', $sessionData)) {
                $db->commit();
                return ['status' => 'success', 'message' => 'Session created successfully', 'token' => $sessionToken];
            } else {
                $db->rollback();
                return ['status' => 'error', 'message' => 'Failed to create session'];
            }
        } catch (Exception $e) {
            $db->rollback();
            error_log('Caught exception: '.  $e->getMessage()); // logging failure
            return ['status' => 'error', 'message' => 'An error occurred while creating the session'];
        }
    }
}
?>
```
This is a simple implementation. In reality, you would likely want to include more robust error handling and possibly even use a caching system for storing tokens in order to quickly check if a generated token already exists. 

