['Here is an example of how you might design such a function using C11's _Atomic type qualifier, POSIX threads (pthread) library for synchronization and Linux-specific API to map memory into shared memory region:

```c
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <sys/mman.h>
#define MAX_STRUCTS 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    // add more fields as needed...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct SharedMemoryRegion {
    atomic_int count;
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *structs[MAX_STRUCTS];
} SharedMemoryRegion;

SharedMemoryRegion* sharedRegion = NULL;

void initSharedMemory() {
    int fd = shm_open("/sharedMem", O_CREAT | O_RDWR, 0666);
    if (fd < 0) { perror("shm_open failed"); exit(1); }
    ftruncate(fd, sizeof(*sharedRegion));

    sharedRegion = mmap(NULL, sizeof(*sharedRegion), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (sharedRegion == MAP_FAILED) { perror("mmap failed"); exit(1); }

    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_setpshared(&attr, PTHREAD_PROCESS_SHARED);
    pthread_mutex_init(&sharedRegion->lock, &attr);
}

void* createStruct(int tag, int rnti) {
    if (atomic_load(&sharedRegion->count) >= MAX_STRUCTS) {
        return NULL; // indicate allocation failure
    }

    pthread_mutex_lock(&sharedRegion->lock);
    if (atomic_load(&sharedRegion->count) < MAX_STRUCTS) {
        NFAPI_CRC_INDICATION_PDU_T* newStruct = malloc(sizeof(*newStruct));
        // initialize the struct...

        sharedRegion->structs[atomic_fetch_add(&sharedRegion->count, 1)] = newStruct;
        pthread_mutex_unlock(&sharedRegion->lock);
        return newStruct;
    } else {
        pthread_mutex_unlock(&sharedRegion->lock);
        return NULL; // indicate allocation failure
    }
}

void deleteStruct(NFAPI_CRC_INDICATION_PDU_T* structToDelete) {
    pthread_mutex_lock(&sharedRegion->lock);

    for (int i = 0; i < atomic_load(&sharedRegion->count); ++i) {
        if (sharedRegion->structs[i] == structToDelete) {
            free(sharedRegion->structs[i]);

            // Shift remaining elements.
            for (; i < atomic_load(&sharedRegion->count) - 1; ++i) {
                sharedRegion->structs[i] = sharedRegion->structs[i + 1];
            }
            atomic_fetch_sub(&sharedRegion->count, 1);

            break;
        }
    }

    pthread_mutex_unlock(&sharedRegion->lock);
}
