        pthread_mutex_lock(&lock);
        childCount++;
        pthread_create(&threads[i], NULL, execute, &commands[i]);
        pthread_detach(threads[i]); // Detaching the thread ensures that resources are cleaned up properly when they terminate.
        pthread_mutex_unlock(&lock);
    }

    for (int i = 0; i < numCommands; i++) {
        if (pthread_join(threads[i], NULL)) {  // Waiting for all threads to finish their execution before returning.
