int count = 0;  // Tracks the number of elements in the list.
const int MAX_COUNT = M;  // Maximum limit for structures.

void* allocate(size_t size) {
    void* memory = NULL;

    pthread_mutex_lock(&lock);
    if (count < MAX_COUNT) {
        memory = malloc(size);
        ++count;
    }
    pthread_mutex_unlock(&lock);

    return memory;
}

void deallocate(void* memory) {
    pthread_mutex_lock(&lock);
    free(memory);
    --count;
    pthread_mutex_unlock(&lock);
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu() {
