        Node* new_node = allocate(sizeof(Node));
        assert(new_node != NULL);

        new_node->pdu = new_pdu;
        new_node->next = head;
        head = new_node;
        pthread_mutex_unlock(&lock);
    }

    return new_pdu;
}

void delete_pdu(NFAPI_CRC_INDICATION_PDU_T* target) {
    pthread_mutex_lock(&lock);
    Node** pp = &head;  // `pp` points to the `next` field of the node before `target`.

    while (*pp && (*pp)->pdu != target) {
        pp = &(*pp)->next;
    }

    if (*pp) {  // Found `target` in the list.
        Node* to_delete = *pp;
        *pp = to_delete->next;  // Skip over `to_delete` in the list.

        deallocate(to_delete);
    }

    pthread_mutex_unlock(&lock);
}
