['Here's an example of how you might implement the described structure in C. Please note that this is a simplified version and real-world applications may require more sophisticated error handling, data validation and management strategies:

```c
#include <stdlib.h>

typedef struct Node {
    int data;
    struct Node* next;
    struct Node* prev;
} Node;

Node* head = NULL;
Node* tail = NULL;
int size = 0;

void insert(int value) {
    Node* new_node = malloc(sizeof(Node));
    if (new_node == NULL) {
        // Handle memory allocation failure
        return;
    }

    new_node->data = value;
    new_node->next = NULL;
    new_node->prev = tail;

    if (tail != NULL) {
        tail->next = new_node;
    } else {
        head = new_node;
    }

    tail = new_node;
    size++;
}

void delete(int value) {
    Node* current = head;
    while (current != NULL) {
        if (current->data == value) {
            if (current->prev != NULL) {
                current->prev->next = current->next;
            } else {
                head = current->next;
            }

            if (current->next != NULL) {
                current->next->prev = current->prev;
            } else {
                tail = current->prev;
            }

            free(current);
            size--;
            return;
        }

        current = current->next;
    }
}

void traverse() {
    Node* current = head;
    while (current != NULL) {
        // Perform your operation here. For example:
        printf("%d ", current->data);
        current = current->next;
    }

    printf("\n");
}

void processDataFeed(int data[], int size) {
    const int batchSize = 1024; // Adjust this value as needed to balance between memory usage and latency.

    for (int i = 0; i < size; i += batchSize) {
        int end = i + batchSize <= size ? i + batchSize : size;

        for (int j = i; j < end; j++) {
            insert(data[j]); // Replace this with your own data processing logic.
        }

        traverse(); // Call your traversal function here if needed.
    }
}

void cleanup() {
    Node* current = head;

    while (current != NULL) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }

    size = 0;
}
```
This code defines a doubly linked list and implements insert, delete and traverse operations. It also handles data processing in batches to optimize memory usage and minimize latency. The cleanup function frees all nodes when the list is no longer needed. 

