['Here is a C# solution for the first part of your question:
```csharp
using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Threading;

public class MD5HashGenerator {
    private readonly Dictionary<string, string> _cache = new Dictionary<string, string>();
    private readonly ReaderWriterLockSlim _lock = new ReaderWriterLockSlim();

    public Dictionary<string, string> generateMD5Hashes(List<string> inputStrings) {
        var resultDict = new Dictionary<string, string>();

        foreach (var str in inputStrings) {
            _lock.EnterUpgradeableReadLock();

            try {
                if (_cache.TryGetValue(str, out var cachedHash)) {
                    resultDict[str] = cachedHash;
                } else {
                    _lock.EnterWriteLock();

                    try {
                        // Compute hash and store in cache
                        using (var md5 = MD5.Create()) {
                            byte[] inputBytes = System.Text.Encoding.ASCII.GetBytes(str);
                            byte[] hashBytes = md5.ComputeHash(inputBytes);

                            var hashStr = BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
                            _cache[str] = hashStr;
                            resultDict[str] = hashStr;
                        }
                    } finally {
                        _lock.ExitWriteLock();
                    }
                }
            } finally {
                _lock.ExitUpgradeableReadLock();
            }
        }

        return resultDict;
    }
}
```
This solution uses a `ReaderWriterLockSlim` to ensure thread safety and handles concurrent requests efficiently by utilizing an upgradeable read lock pattern where possible, minimizing the time spent in write mode. A dictionary is used for caching hashes to reduce repeated computation of identical strings. 

