const { cloudStorage } = require('third-party-cloud-storage');
const externalMetadataService = require('external-metadata-service');
const logger = require('centralized-logging-service');
const axios = require('axios').default;
const async = require('async');

// Define constants for file size limit and supported MIME types
const FILE_SIZE_LIMIT = 10 * 1024 * 1024; // 10MB
const SUPPORTED_MIMETYPES = ['image/*', 'application/pdf', 'application/octet-stream'];

// Define exponential backoff strategy for network failures
function retryStrategy(retryCount) {
    return (Math.pow(2, retryCount) - 1) * 1000; // Exponential backoff with jitter
}

async function uploadFile(url, options = {}) {
    return new Promise((resolve, reject) => {
        axios({ method: 'head', url })
            .then(response => {
                const { headers } = response;
                if (!SUPPORTED_MIMETYPES.includes(headers['content-type']) || headers['content-length'] > FILE_SIZE_LIMIT) {
                    reject('Unsupported file type or size');
                } else {
                    axios({ method: 'get', url, responseType: 'stream' })
                        .then(response => {
                            const uploadOptions = Object.assign({ concurrentParts: 5 }, options);

                            cloudStorage.uploadFile(url, response.data, uploadOptions)
                                .on('progress', progress => logger.info('Upload progress: ', progress))
                                .then(() => {
                                    const externalMetadata = externalMetadataService.fetchAttributes(url);
                                    resolve({ 
                                        fileURL: cloudStorage.getFileURL(url),
                                        metadata: externalMetadata
                                    });
                                })
                                .catch(err => reject(`Upload failed with error: ${err}`));
                        })
                        .catch(err => reject(`Download failed with error: ${err}`));
                }
            })
            .catch(err => reject(`Head request failed with error: ${err}`));
    });
}
