#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/time.h>
#include <unistd.h>
#include <assert.h>

typedef struct Node {
    struct Node* prev;
    struct Node* next;
    unsigned long timestamp;
    int unique_id;
} Node;

Node* head = NULL;
Node* tail = NULL;
pthread_mutex_t mutex;

Node* new_node(int id) {
    Node* node = (Node*) malloc(sizeof(Node));
    assert(node != NULL);

    struct timeval tv;
    gettimeofday(&tv,NULL);
    unsigned long millisecondsSinceEpoch = (unsigned long)(tv.tv_sec) * 1000 + (unsigned long)(tv.tv_usec) / 1000;

    node->timestamp = millisecondsSinceEpoch;
    node->unique_id = id;
    return node;
}

void insert(int id) {
    Node* node = new_node(id);
    pthread_mutex_lock(&mutex);

    if (head == NULL) {
        head = tail = node;
        node->prev = node->next = NULL;
    } else {
        tail->next = node;
        node->prev = tail;
        node->next = NULL;
        tail = node;
    }

    pthread_mutex_unlock(&mutex);
}

void delete(int id) {
    pthread_mutex_lock(&mutex);
    Node* currNode = head;

    while (currNode != NULL && currNode->unique_id != id) 
        currNode = currNode->next;

    if(currNode == NULL){
        pthread_mutex_unlock(&mutex);
        return;
    }

    if (currNode->prev != NULL) 
        currNode->prev->next = currNode->next;

    if(currNode->next != NULL)
        currNode->next->prev = currNode->prev;

    if (head == currNode) 
        head = currNode->next;

    if (tail == currNode) 
        tail = currNode->prev;

    free(currNode);
    pthread_mutex_unlock(&mutex);
}

void traverse() {
    Node* node = head;

    while (node != NULL){
        printf("id: %d, timestamp:%lu\n", node->unique_id, node->timestamp);
        node = node->next;
    }
}

void cleanup(){
    Node* currNode = head;

    while(currNode != NULL){
        Node* nextNode = currNode->next;
        free(currNode);
        currNode = nextNode;
    }
}

void process_data_stream() {
    int data = 0; // assume we are fetching some data from an external API

    while (1) {
        insert(data++);
        if(data % 100 == 0) 
            delete(data - 99); // removing every 100th node

        usleep(100); // simulate latency and data rate fluctuations from external API
    }
}
```
This code provides a basic implementation of a doubly linked list. The `insert` function inserts a new node at the end of the list, the `delete` function removes a node with a specific unique identifier (assumes uniqueness), and the `traverse` function prints out all nodes in the list for debugging purposes. A cleanup function is provided to free up memory when we're done using our data structure.

Concurrency issues are handled by locking the entire linked list whenever a node is inserted, deleted, or traversed via mutexes (`pthread_mutex_lock()/unlock()`). The `process_data_stream` function simulates an external high-frequency data stream by inserting new nodes with unique identifiers and then removing every 100th node. This is just a basic example, the actual handling of concurrent access and data stream from external API would depend on the exact requirements and constraints of your specific use case.

Please note that proper thread management, such as join threads to avoid memory leaks or potential race conditions, is not included in this code snippet. It's a simple example for illustrating how to manage concurrency with mutexes when working with dynamic data structures like linked lists. 

This code has been written on the assumption that the unique identifier `id` and timestamp are integers respectively unsigned long ints, you may need to adjust this according to your specific use case.
