int allocate_crc_indications(NFAPI_CRC_INDICATION_PDU_T **result, int N, int maxChunkSize) {
    srand(time(NULL)); // seed the random number generator
    *result = NULL; 
    if (N <= 0 || maxChunkSize <= 0) {
        return -1; // Invalid parameters
    }

    for (int i = 0; i < N; i += maxChunkSize) {
        int chunkSize = (i + maxChunkSize > N) ? N - i : maxChunkSize; 

        pthread_mutex_lock(&mutex); // Lock before accessing shared resources
        if ((g_memoryUsage + sizeof(NFAPI_CRC_INDICATION_PDU_T) * chunkSize) >= INT_MAX) {
            pthread_mutex_unlock(&mutex); 
            return -2; // Memory allocation failure
        }

        NFAPI_CRC_INDICATION_PDU_T *chunk = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * chunkSize);
        if (chunk == NULL) {
            pthread_mutex_unlock(&mutex); 
            return -2; // Memory allocation failure
        }

        for (int j = 0; j < chunkSize; ++j) {
            chunk[j].RX_UE_INFORMATION_TAG = i+j;
            chunk[j].RNTI = rand(); // Randomly set RNTI
            chunk[j].CRCFALG = rand(); // Randomly set CRCFLAG
        }

        *result = realloc(*result, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (g_memoryUsage + chunkSize)); 
        if (*result == NULL) {
            pthread_mutex_unlock(&mutex); 
            return -2; // Memory allocation failure
        }

        memcpy(*result + g_memoryUsage, chunk, sizeof(NFAPI_CRC_INDICATION_PDU_T) * chunkSize); 
        g_memoryUsage += chunkSize;
        pthread_mutex_unlock(&mutex); // Unlock after modification of shared resources

        free(chunk); 
    }

    return 0; // Success
}
