void processFilesInDirectory(const char *dirname) {
    DIR *dir = opendir(dirname);
    if (dir == NULL) {
        perror("Failed to open directory");
        return;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip the current and parent directories.
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        char *filename = malloc(strlen(dirname) + strlen(entry->d_name) + 2);
        sprintf(filename, "%s/%s", dirname, entry->d_name);

        // Create a thread for each file.
        pthread_t thread;
        if (pthread_create(&thread, NULL, processFile, filename) != 0) {
            perror("Failed to create thread");
            free(filename);
            continue;
        }

        // Detach the thread so we don't need to join it later.
        pthread_detach(thread);
    }

    closedir(dir);
}
