['Here's a simple implementation for your requirements using C with Linked List data structure to manage NetworkFlowRecords. This is a simplified version, real-life implementation would be much more complex:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PACKETS 50000 // Maximum number of packets to be handled by the system
#define BUFFER_SIZE 256 // Buffer size for each packet metadata

typedef struct PacketMetadata {
    int length;
    char sourceIP[BUFFER_SIZE];
    char destIP[BUFFER_SIZE];
    int protocol;
} PacketMetadata;

typedef struct NetworkFlowRecord {
    char flowID[BUFFER_SIZE];
    time_t timestamp;
    PacketMetadata *packetsList;
    int packetsCount;
    struct NetworkFlowRecord *next;
} NetworkFlowRecord;

NetworkFlowRecord* networkFlowRecords = NULL; // Global linked list of records
int totalPackets = 0; // Keep track of total number of packets received

void processPacket(char *flowID, PacketMetadata packet) {
    if (totalPackets >= MAX_PACKETS) {
        printf("Error: Maximum limit for packets reached!\n");
        return;
    }

    NetworkFlowRecord *record = networkFlowRecords;
    while (record != NULL && strcmp(record->flowID, flowID)) 
        record = record->next;

    if (record == NULL) { // If the record doesn't exist yet, create one
        record = malloc(sizeof(NetworkFlowRecord));
        strncpy(record->flowID, flowID, BUFFER_SIZE);
        record->packetsList = malloc(MAX_PACKETS * sizeof(PacketMetadata));
        record->packetsCount = 0;
        record->next = networkFlowRecords; // Add to the beginning of the list
        networkFlowRecords = record;
    }

    if (record->packetsCount >= MAX_PACKETS) {
        printf("Error: Maximum limit for packets in a flow reached!\n");
        return;
    }

    // Add packet to the list and update count
    record->packetsList[record->packetsCount++] = packet; 
    totalPackets++;
}
```

This is just the function to process a single packet. For loading this with multiple sources and managing memory exhaustion, handling external data source updates for network topology changes, optimizing for time and space complexity, handling edge cases such as high-frequency packet bursts, would require a more complex design and additional code. The key optimization strategies here are to avoid unnecessary memory allocation (using an array instead of linked list) and avoiding excessive copying (storing the flowID only once). This is a simplified version and there're many areas where it could be improved for production use.
