// Global variables
record* records = NULL;
metadata* metadatas = NULL;
int record_count = 0;
int metadata_count = 0;
pthread_mutex_t lock;

void initialize(double range, int initialSize) {
    // Initialize mutex for thread safety
    pthread_mutex_init(&lock, NULL);

    // Allocate memory for arrays
    records = malloc(sizeof(record) * initialSize);
    metadatas = malloc(sizeof(metadata) * initialSize);
}

void addRecord(double value, char* string, char type) {
    pthread_mutex_lock(&lock);

    // Reallocate memory if necessary
    if (record_count % 10 == 0 && record_count != 0) {
        records = realloc(records, sizeof(record) * record_count * 2);
    }

    // Assign values to new record
    records[record_count].value = value;
    int stringLength = rand() % 256 + 1;
    records[record_count].string = malloc(sizeof(char) * (stringLength+1));

    for(int i = 0; i < stringLength; ++i){
        records[record_count].string[i] = 'a' + rand()%26;
    }
    records[record_count].string[stringLength] = '\0';
    records[record_count].type = type;

    // Increment count
    record_count++;

    pthread_mutex_unlock(&lock);
}

void addMetadata(int key, char tag) {
    pthread_mutex_lock(&lock);

    // Reallocate memory if necessary
    if (metadata_count % 10 == 0 && metadata_count != 0) {
        metadatas = realloc(metadatas, sizeof(metadata) * metadata_count * 2);
    }

    // Assign values to new metadata
    metadatas[metadata_count].key = key;
    metadatas[metadata_count].rcrd = &records[record_count-1];
    metadatas[metadata_count].tag = tag;

    // Increment count
    metadata_count++;

    pthread_mutex_unlock(&lock);
}

// Free allocated memory and destroy mutex on cleanup
void cleanup() {
    for(int i = 0; i < record_count; ++i) {
        free(records[i].string);
    }

    free(records);
    free(metadatas);
    pthread_mutex_destroy(&lock);
}
```
This code will create a thread-safe function for adding records and metadata to arrays. The memory allocation strategy of the record's string may need some adjustments based on what kind of random strings you want generated. For more complex memory allocation, consider using a custom memory allocator that can manage variable size blocks in different lists to minimize fragmentation.
