typedef struct {
    sem_t *sem; 
    int maxConcurrent;
    pthread_mutex_t lock;  
} SemaphoreManager;

SemaphoreManager* createSemaphoreManager(int initialValue){
    /* Create and initialize a new semaphore manager */
}

void acquireSemaphore(SemaphoreManager *semMgr) {
    int result = sem_wait(semMgr->sem);
    if (result != 0){
        logError("Failed to acquire semaphore");  /* Use external dependency for logging */
    } else {
        pthread_mutex_lock(&(semMgr->lock));  
        /* Update maxConcurrent value here */
        pthread_mutex_unlock(&(semMgr->lock));
    }
}

void releaseSemaphore(SemaphoreManager *semMgr) {
    int result = sem_post(semMgr->sem);
    if (result != 0){
        logError("Failed to release semaphore"); /* Use external dependency for logging */
    } else {
        pthread_mutex_lock(&(semMgr->lock));  
        /* Update maxConcurrent value here */
        pthread_mutex_unlock(&(semMgr->lock));
    } 
}
```
