#include <string.h>
#include <assert.h>
#include <time.h>

typedef struct Record {
    int key;
    int value;
    char* description;
} Record;

int manage_memory(const char** descriptions, const size_t *offsets, int numRecords, int maxSize) {
    srand((unsigned int)time(NULL)); // Seed the random number generator

    // Allocate memory for records array and check for allocation failure
    Record* records = (Record*)malloc(numRecords * sizeof(Record));
    assert(records != NULL); 

    int totalSize = 0;

    for (int i = 0; i < numRecords && totalSize <= maxSize; ++i) {
        // Allocate memory for description and check for allocation failure
        records[i].description = malloc(strlen(descriptions[offsets[i]]) + 1);
        assert(records[i].description != NULL); 

        strcpy(records[i].description, descriptions[offsets[i]]); // Copy string to allocated memory

        // Initialize 'value' field of each Record to a random integer within a specified range
        records[i].value = rand() % (100 + 1 - 1) + 1; 

        totalSize += strlen(records[i].description);
    }

    // Free allocated memory after use
    for (int i = 0; i < numRecords; ++i) {
        free(records[i].description);
    }
    free(records);

    return totalSize;
