public class SystemCommandUtility {
    private static final int MAX_RETRY = 3;

    public Object deserialize(byte[] data, String className) throws RuntimeException {
        try (ByteArrayInputStream bais = new ByteArrayInputStream(data); 
             ObjectInputStream in = new ObjectInputStream(bais)) {
            return Class.forName(className).cast(in.readObject());
        } catch (ClassNotFoundException | IOException | InvalidClassException e) {
            throw new RuntimeException("Deserialization failed: " + e);
        } catch (ClassCastException e) {
            System.err.println("Failed to cast object to specified class. Falling back...");
            return null; // fallback mechanism
        } catch (OptionalDataException e) {
            System.err.println("Error with deserialized data: " + e);
            return null; // fallback mechanism
        }
    }

    public void executeCommand(String command, String[] params) {
        if (!isValidCommand(command)) {
            throw new RuntimeException("Invalid command. Exiting.");
        }

        List<String> cmdWithArgs = new ArrayList<>();
        cmdWithArgs.add(command);
        for (String param : params) {
            if (param != null && isValidParam(param)) {
                cmdWithArgs.add(param);
            } else {
                System.err.println("Invalid parameter: " + param + ". Skipping.");
            }
        }

        for (int i = 0; i < MAX_RETRY; i++) {
            try {
                Process p = Runtime.getRuntime().exec(cmdWithArgs.toArray(new String[0]));
                if (p.waitFor() == 0) return; // Command executed successfully
            } catch (IOException | InterruptedException e) {
                System.err.println("Error executing command: " + e);
                if (i < MAX_RETRY - 1) {
                    System.out.println("Retrying...");
                    continue;
                } else {
                    throw new RuntimeException("Failed to execute command after maximum retries.");
                }
            }
        }
    }

    private boolean isValidCommand(String cmd) {
        // Add your whitelist logic here. For example:
        return Arrays.asList("ls", "grep").contains(cmd);
    }

