pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

record** allocate(size_t count) {
    pthread_mutex_lock(&lock);

    // Dynamically allocate memory for the record collection
    record **collection = (record **)malloc(count * sizeof(record*));
    if (collection == NULL) {
        fprintf(stderr, "Failed to allocate memory\n");
        pthread_mutex_unlock(&lock);
        return NULL;  // On failure
    }

    // Initialize each record in the collection
    for (size_t i = 0; i < count; ++i) {
        collection[i] = (record *)malloc(sizeof(record));

        if (collection[i] == NULL) {
            fprintf(stderr, "Failed to allocate memory\n");

            // Free previously allocated records
            for (size_t j = 0; j < i; ++j) {
                free(collection[j]);
            }
            free(collection);  // Free the collection itself

            pthread_mutex_unlock(&lock);
            return NULL;  // On failure
        }

        collection[i]->key = 0;
        collection[i]->value = 0.0;
        collection[i]->string = "";
    }

    pthread_mutex_unlock(&lock);
    return collection;  // Return the allocated and initialized record collection
}
