["Here is a basic example of how you could implement this in C. This code does not include any form of logging, error checking or dynamic reallocation, as these are quite complex to do properly, and would greatly increase the complexity of the code. I suggest using libraries such as glibc's `malloc` and `realloc` for memory allocation, and OpenSSL's `RAND_bytes` for generating random data.

```C
#include <stdlib.h>
#include <time.h>
#include <openssl/rand.h>

typedef struct {
    // fields of NFAPI_CRC_INDICATION_PDU_T
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_crc_indications(int N, int MAX_ALLOCATION_SIZE) {
    if (N <= 0) return NULL; // handle edge case where N is zero or negative

    srand((unsigned int)time(NULL)); // initialize random number generator

    NFAPI_CRC_INDICATION_PDU_T* entries = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);

    if (entries == NULL) return NULL; // handle allocation failure

    int i, remainingSize = MAX_ALLOCATION_SIZE - sizeof(NFAPI_CRC_INDICATION_PDU_T)*N; 

    for (i = 0; i < N && remainingSize >= sizeof(NFAPI_CRC_INDICATION_PDU_T); ++i) {
        // populate entries[i] with valid data

        if (!checkIntegrity(&entries[i])) {
            // handle integrity check failure
            free(entries);
            return allocate_and_populate_crc_indications(--N, MAX_ALLOCATION_SIZE); 
            /* retry with a reduced size after deallocating the current array 
               this is not efficient for large sizes of N */
        }

        remainingSize -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    // handle case where we couldn't allocate enough entries due to MAX_ALLOCATION_SIZE limit
    if (i < N) { 
        entries = realloc(entries, sizeof(NFAPI_CRC_INDICATION_PDU_T) * i);
    }

    return entries; // returns a pointer to the allocated and populated array
}
```
You should use this code as a starting point and adapt it according to your specific requirements. It's also important to note that C does not have built-in error handling mechanisms like exceptions in other languages, so it is common practice in C programming to return an error value (typically `NULL`) when something goes wrong with allocation or integrity checks to allow the caller to handle these errors.
