['Implementing this task in C would require understanding of file I/O operations, networking, threading concepts, error handling and OpenSSL library for encryption and decryption. Here is a simple implementation without extensive error checking and resource management strategies. 

```c
#include <stdio.h>
#include <string.h>
#include <errno.h>
#include <openssl/evp.h>

typedef struct {
    int encrypted;      // Whether the content is encrypted or not
    char *content;      // The content of the file (either encrypted or decrypted)
    size_t length;       // The length of the content
} CipherObject;

CipherObject* processFile(char* filePath, char* cmdOption){
    FILE *file = fopen(filePath, "rb");

    if (file == NULL){
        printf("Failed to open the file: %s\n", strerror(errno));
        return NULL;
    }

    // Reading from file in chunks to avoid large memory usage for large files
    const size_t bufferSize = 1024 * 1024;   // Buffer size set to 1MB
    char buffer[bufferSize];

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    CipherObject *cipherObj = malloc(sizeof(CipherObject));
    cipherObj->content = malloc(1);  // Start with an empty string
    cipherObj->length = 0;

    if (strcmp(cmdOption, "encrypt") == 0){
        EVP_EncryptInit(ctx, EVP_aes_256_cbc(), /* key here */, /* iv here */);
        cipherObj->encrypted = 1;   // Setting the encryption state to true
    } else if (strcmp(cmdOption, "decrypt") == 0){
        EVP_DecryptInit(ctx, EVP_aes_256_cbc(), /* key here */, /* iv here */);
        cipherObj->encrypted = 0;   // Setting the encryption state to false
    } else {
        printf("Invalid command option. Please use 'encrypt' or 'decrypt'\n");
        EVP_CIPHER_CTX_free(ctx);
        free(cipherObj->content);
        free(cipherObj);
        fclose(file);
        return NULL;
    }

    size_t nread;
    while ((nread = fread(buffer, 1, bufferSize, file)) > 0) {
        // For encryption and decryption operations
        EVP_CipherUpdate(ctx, cipherObj->content + cipherObj->length, &nread, buffer, nread);
    }

    /* Finalize operation */
    if (!EVP_CipherFinal(ctx, cipherObj->content + cipherObj->length, &nread)) {
        printf("Error finalizing encryption/decryption\n");
        EVP_CIPHER_CTX_free(ctx);
        free(cipherObj->content);
        free(cipherObj);
        fclose(file);
        return NULL;
    }

    cipherObj->length += nread;
    EVP_CIPHER_CTX_free(ctx);
    fclose(file);
    return cipherObj;
}
```
Please note that this is a simplified version and does not include all the details you mentioned. Also, please replace `/* key here */` and `/* iv here */` with actual keys and initialisation vectors for encryption/decryption respectively. This code also needs to be integrated with appropriate error checking mechanisms and memory management strategies before it could be used in a production environment.
