NFAPI_CRC_INDICATION_PDU_T** populateNfadIndicationList() {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    static NFAPI_CRC_INDICATION_PDU_T** list = NULL;
    static int size = 0;

    pthread_mutex_lock(&mutex);

    // Check if the list needs to be resized
    int newSize = getConfigurationValue("listSize", 10);
    if (newSize != size) {
        NFAPI_CRC_INDICATION_PDU_T** newList = realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * newSize);
        if (!newList) {
            logError("Failed to allocate memory for list.");
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        list = newList;
        size = newSize;
    }

    // Populate the list
    int sum = 0;
    for (int i = 0; i < size; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            logError("Failed to allocate memory for PDU.");
