// Memory pool implementation details
#define POOL_SIZE 100000
#define MAX_POOLS 256 // Limit the number of pools to prevent excessive memory usage
static NFAPI_CRC_INDICATION_PDU_T* memPool[MAX_POOLS];
static int poolIndex = 0;
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // Lock for thread safety

// Memory allocation function, ensuring no two consecutive elements have the same RNTI value
NFAPI_CRC_INDICATION_PDU_T* allocateMemory(RX_UE_INFORMATION_TAG rxInfoTag, RNTI rnti) {
    pthread_mutex_lock(&lock); // Lock to ensure thread safety

    // Create a new memory pool if the current one is full
    if (poolIndex >= POOL_SIZE * MAX_POOLS) {
        printf("Error: Memory pool limit reached. Unable to allocate memory.\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Allocate memory from the current pool if it's not full
    NFAPI_CRC_INDICATION_PDU_T* node = &memPool[poolIndex % MAX_POOLS][poolIndex / MAX_POOLS];
    pthread_mutex_unlock(&lock); // Unlock after memory allocation

    // Initialize the structure with provided values
    memset(node, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    node->rxInfoTag = rxInfoTag;
    node->rnti = rnti;

    // Ensure no two consecutive elements have the same RNTI value
    if (poolIndex > 0) {
        assert(node[-1].rnti != rnti);
    }

    poolIndex++;
    return node;
}

// Function for validating the integrity of the list after its creation, ensuring all elements meet the specified criteria
int validateListIntegrity() {
    pthread_mutex_lock(&lock); // Lock to ensure thread safety

    int errorCount = 0;
    for (int i = 1; i < poolIndex; ++i) {
        if (memPool[i % MAX_POOLS][i / MAX_POOLS].rnti == memPool[(i - 1) % MAX_POOLS][(i - 1) / MAX_POOLS].rnti) {
            printf("Error: Duplicate RNTI found at index %d.\n", i);
            errorCount++;
        }
    }

    pthread_mutex_unlock(&lock); // Unlock after validation

