Node* createNode(NFAPI_CRC_INDICATION_PDU_T value) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    if(newNode == NULL){
        exit(-1);  // Error!! return from main 
    }
    newNode->data = value;
    newNode->prev = NULL;
    newNode->next = NULL;
    return newNode;
}

// Define the structure for list
typedef struct {
    Node *head;
    Node *tail;
    pthread_rwlock_t lock;
} List;

List* createList() {
    List* list = (List*) malloc(sizeof(List));
    if(list == NULL){
        exit(-1);  // Error!! return from main 
    }
    list->head = list->tail = NULL;
    pthread_rwlock_init(&list->lock, NULL);
    return list;
}

void insertNode(List* list, NFAPI_CRC_INDICATION_PDU_T value) {
    pthread_rwlock_wrlock(&list->lock);  // Acquire write lock

    Node* node = createNode(value);
    if (list->head == NULL && list->tail == NULL){ 
        list->head = list->tail = node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T lastData = list->tail->data;
        if (lastData.RNTI != value.RNTI) {  // Check for consecutive RNTIs
            node->prev = list->tail;
            list->tail->next = node;
            list->tail = node;
        } else{
            free(node);
            return;
        }
    }

    pthread_rwlock_unlock(&list->lock);  // Release write lock
}
```
In the code above, we create a custom memory pool that dynamically resizes based on current memory pressure. A reader-writer lock is used to handle concurrent access from multiple threads, which ensures data consistency while minimizing thread synchronization overheads. The list supports inserting nodes with unique `RNTI` values only and prevents cycles by checking consecutive elements for identical `RNTI` values.
