void addIndication(NFAPI_CRC_INDICATION_PDU_T *newInd){
    assert(newInd != NULL); // Add your own error handling if you want

    Node* newNode = malloc(sizeof(Node)); 
    newNode->ind = newInd;
    newNode->next = NULL;

    pthread_mutex_lock(&lock);

    // Add to the end of list
    if (head == NULL){
        head = newNode;
    }else{
        Node* curr = head;
        while(curr->next != NULL) {
            if (curr->ind->RNTI == newInd->RNTI && curr->ind->RX_UE_INFORMATION_TAG < newInd->RX_UE_INFORMATION_TAG){
                break;  // Add new node before this one
            }
            curr = curr->next;
        }

        if (curr == head && (head->ind->RNTI != newInd->RNTI || head->ind->RX_UE_INFORMATION_TAG > newInd->RX_UE_INFORMATION_TAG)){
            // Add to the front of list
            newNode->next = head;
            head = newNode;
        }else{  // Insert into the middle or at end
            newNode->next = curr->next;
            curr->next = newNode;
        }
    }

    pthread_mutex_unlock(&lock);
}

void removeIndication(uint16_t RNTI, uint16_t RX_UE_INFORMATION_TAG){
    pthread_mutex_lock(&lock);

    Node* curr = head;
    Node* prev = NULL;

    while (curr != NULL && (curr->ind->RNTI != RNTI || curr->ind->RX_UE_INFORMATION_TAG != RX_UE_INFORMATION_TAG)){
        prev = curr;
        curr = curr->next;
    }

    if (curr == NULL) { // Not found
        pthread_mutex_unlock(&lock);
        return; 
    }

    if(prev != NULL){ 
        prev->next = curr->next;
    }else{
        head = curr->next;
