int loadResourceAndInitializeRecords(const char *filepath, int min, int max, int *totalItems) {
    FILE *resourceFile = fopen(filepath, "r"); // Open the resource file
    if (resourceFile == NULL) {
        perror("Failed to open the resource file. ");
        return -1;
    }

    char buffer[256];
    int count = 0;
    while (fgets(buffer, sizeof(buffer), resourceFile)) { // Read line by line and count lines 
        ++count;
    }
    if (rewind(resourceFile) != 0) { // Reset file pointer to start
        perror("Failed to rewind the file. ");
        fclose(resourceFile);
        return -1;
    }

    record *records = malloc(count * sizeof(record)); // Allocate memory for records
    if (records == NULL) {
        perror("Failed to allocate memory for the records. ");
        fclose(resourceFile);
        return -1;
    }

    int i = 0;
    while (fgets(buffer, sizeof(buffer), resourceFile)) {  // Read each line and generate random numbers
        if (i >= count) break;

        pthread_mutex_lock(&mutex);
        records[i++].value = generateRandomNumber(min, max); // Generate a random number
        pthread_mutex_unlock(&mutex);
    }

    *totalItems = count;
    fclose(resourceFile);
    free(records);  // Deallocate the memory after use
    return i;
}
