typedef struct {
    time_t timestamp;
    unsigned long msgId;
    char* payload;
} Message;

Message** messages = NULL;
size_t messageCount = 0;
pthread_mutex_t lock;  // for thread safety
int fragmentationThreshold;
int memoryPressureThreshold;

void cleanup() {
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < messageCount; ++i) {
        free(messages[i]->payload);
        free(messages[i]);
    }
    free(messages);
    pthread_mutex_unlock(&lock);
}

void insertMessage(char* payload, size_t length) {
    Message* message = malloc(sizeof(Message));
    if (!message) exit(-1);  // handle error 

    time(&message->timestamp);
    message->msgId = rand();  // unique ID
    message->payload = malloc(length + 1);
    strncpy(message->payload, payload, length);
    (message->payload)[length] = 0;

    pthread_mutex_lock(&lock);
    messages = realloc(messages, ++messageCount * sizeof(*messages));  // expand array
    if (!messages) exit(-1);  // handle error 
    messages[messageCount - 1] = message;
    pthread_mutex_unlock(&lock);

    if (messageCount % fragmentationThreshold == 0) {
        compactMemory();  // periodic compaction
    }
}

void deleteMessage(unsigned long msgId) {
    int indexToDelete = -1;

    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < messageCount; ++i) {
        if (messages[i]->msgId == msgId) {
            free(messages[i]->payload);
            free(messages[i]);
            indexToDelete = i;
            break;
        }
    }

    // Shift all elements forward, overwrite the deleted one
    if (indexToDelete != -1) {
        for (size_t i = indexToDelete; i < messageCount - 1; ++i) {
            messages[i] = messages[i + 1];
        }
        --messageCount;
    }

    // Compact memory if needed
    if (messageCount % fragmentationThreshold == 0) {
        compactMemory();
    }

    pthread_mutex_unlock(&lock);
}
