    long *offsets = malloc(offsets_size * sizeof(long));
    int *keys = calloc(keys_size, sizeof(int));
    record_t *records = malloc(records_size * sizeof(record_t));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return -ENOMEM;
    }

    // Initialize offsets with sequential integers.
    for (long i = 0; i < offsets_size; ++i) {
        offsets[i] = i;
    }

    srand(time(NULL));

    int unique_keys = 0;
    while (unique_keys < keys_size) {
        int key = rand() % max_key;
        if (!keys[key]) {
            keys[key] = 1;
            ++unique_keys;
        }
    }

    // Initialize records with unique random integers.
    for (int i = 0; i < records_size; ++i) {
        int value;
        do {
            value = rand();
        } while (!records[value % records_size].value);

        records[value % records_size].value = value;
    }

    data->offsets = offsets;
    data->keys = keys;
    data->records = records;
    atomic_store(&initialized, true);

    return 0;
}

void release(data_t *data) {
    assert(atomic_load(&initialized));

    pthread_mutex_lock(&mutex);

    free(data->offsets);
    free(data->keys);
    free(data->records);

    atomic_store(&initialized, false);

    pthread_mutex_unlock(&mutex);
}
```
This implementation uses a `pthread` mutex to ensure thread safety in the release function. The `initialize()` function is not re-entrant and can be made so by using a recursive mutex or locking inside the critical section of code that checks for initialization. This would improve performance but make the code more complex.
']

