using System.Xml.XPath;
using System.Linq;

public class Measurement
{
    public string SRS { get; set; }
    public TimeDomainResourceAllocation TimeDomainResourceAllocation { get; set; }
}

public class TimeDomainResourceAllocation
{
    public double SignalToNoiseRatio { get; set; }
}

public static List<Measurement> InitializeAndConfigure(string xml, string name)
{
    try
    {
        XPathDocument doc = new XPathDocument(xml);
        XPathNavigator nav = doc.CreateNavigator();

        XPathNodeIterator iterator = nav.SelectChildren("root", "");
        var measurements = new List<Measurement>();

        while (iterator.MoveNext())
        {
            var xpath = string.Format("descendant::{0}", name);

            if (nav.Matches(xpath))
            {
                XPathNodeIterator matches = nav.Select(xpath);

                while (matches.MoveNext())
                {
                    var matchNavigator = matches.Current;

                    measurements.Add(new Measurement()
                    {
                        SRS = matchNavigator.GetAttribute("SRS", ""),
                        TimeDomainResourceAllocation = new TimeDomainResourceAllocation()
                        {
                            SignalToNoiseRatio = double.Parse(matchNavigator.GetAttribute("SignalToNoiseRatio", ""))
                        }
                    });
                }
            }
        }

        return measurements;
    }
    catch (Exception ex)
    {
        Console.WriteLine("An error occurred: " + ex);
        throw;
    }
}
