        (*count)++;
    }

    if (ferror(file)) {
        perror("fgets");
    }

    return records;
}

int* read_numbers(FILE *file, size_t count, int rangeStart, int rangeEnd) {
    int *numbers = malloc(count * sizeof(*numbers));
    if (numbers == NULL) {
        perror("malloc");
        return numbers;
    }

    char buffer[256];
    size_t i = 0;

    while (fgets(buffer, sizeof(buffer), file)) {
        int num = atoi(buffer);
        if (num < rangeStart || num > rangeEnd) {
            fprintf(stderr, "Invalid number: %d\n", num);
            continue;
        }

        numbers[i++] = num;
    }

    if (ferror(file)) {
        perror("fgets");
    }

    return numbers;
}

void assign_numbers(Record *records, size_t recordCount, int *numbers, size_t numberCount) {
    srand(time(NULL));

    for (size_t i = 0; i < recordCount; ++i) {
        int index = rand() % numberCount;
        records[i].key = numbers[index];
    }
