    size_t value = 0;
    for (size_t i = 0; key[i] != '\0'; ++i)
        value = (value << 5) + value + key[i];
    return value % hashTableSize;
}

// Function to generate unique ID
char *generateUniqueId(double timestamp, int counter, unsigned int seed) {
    char buffer[32];
    sprintf(buffer, "%.15g-%d-%u", timestamp, counter, seed);
    return strdup(buffer);
}

// Function to insert event into hash table
void insertEventIntoHashTable(const char *key, Event *event) {
    pthread_mutex_lock(&mutex);  // Thread-safe operation

    HashNode *node = malloc(sizeof(*node));
    if (!node) goto err;
    node->key = strdup(key);
    if (!node->key) goto free_node;
    node->value = event;
    node->next = hashTable[hash(key)];
    hashTable[hash(key)] = node;

    pthread_mutex_unlock(&mutex);  // Unlock mutex after operation
    return;
free_node:
    free(node);
err:
    perror("Error inserting event into hash table");
}

