Here's an example:

```C
#include <pthread.h>
#include <stdio.h>
#define MAX_LOGS 1024 // Adjust this value as per your requirement

typedef struct {
    int head;
    int tail;
    char* logs[MAX_LOGS];
    pthread_mutex_t mutex;
    void (*callback)(const char*); // External callback mechanism.
} Logger;

void log(Logger *logger, const char* msg) {
    pthread_mutex_lock(&logger->mutex);

    logger->logs[logger->head] = strdup(msg);  // Use memory allocation on heap for each message.
    logger->head = (logger->head + 1) % MAX_LOGS;

    if (logger->callback != NULL) {
        (*logger->callback)(msg); // Notify external callback mechanism.
    }

    if (logger->head == logger->tail) {
        free(logger->logs[logger->tail]);  // Overwriting oldest log message.
        logger->tail = (logger->tail + 1) % MAX_LOGS;
    }

    pthread_mutex_unlock(&logger->mutex);
}

void initLogger(Logger *logger, void (*callback)(const char*)) {
    logger->head = 0;
    logger->tail = 0;
    logger->callback = callback;
    pthread_mutex_init(&logger->mutex, NULL);  // Initializing mutex.
}
```
