const path = require('path');
const glob = require("glob");
const { promisify } = require('util');
const readFileAsync = promisify(fs.readFile);

function handleErrorMiddleware(logger) {
  return async (req, res, next) => {
    try {
      await next();
    } catch (error) {
      logger.log('error', error.message);
      res.status(500).json({ error: 'Something went wrong' });
    }
  };
}

function createReadFiles(logger, limit) {
  return async function readFiles(directoryPath, extension) {
    let fileNames;

    try {
      const globPattern = `${path.join(directoryPath, `*.${extension}`)}`;
      fileNames = await new Promise((resolve, reject) => {
        glob(globPattern, (err, files) => {
          if (err) {
            reject(err);
          } else {
            resolve(files.slice(0, limit));
          }
        });
      });
    } catch (error) {
      logger.log('error', `Error reading directory: ${directoryPath}`);
      return [];
    }

    const fileContents = await Promise.all(fileNames.map(async (fileName) => {
      try {
        const data = await readFileAsync(fileName, 'utf8');
        logger.log('info', `Read: ${fileName}`);
        return data;
      } catch (error) {
        logger.log('error', `Error reading file: ${fileName}`);
        return null;
      }
    }));

    return fileContents;
  };
}

const readFiles = handleErrorMiddleware(logger)(createReadFiles(logger, limit));
```

This solution assumes a logging system has been set up with `winston` or another logger library. You can use the function by calling `readFiles('/path/to/directory', 'extension')`. 

It also uses rate limiting via the `limit` variable to control the maximum number of files that will be read in a single batch, helping to prevent memory overflow while balancing between throughput and resource usage. Please note that this is a basic example and may need adjustments for use in production environments.
']

