    PacketHeader packetHeader;
    PayloadType payloadType;
} DataPacket;

typedef struct NetworkEvent {
    EventTag eventTag;
    DataPacket dataPacket;
} NetworkEvent;

// Define your linked list node structure
typedef struct Node {
    NetworkEvent* networkEvent;
    struct Node* next;
} Node;

// Initialize the head of the linked list
Node* head = NULL;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void addNetworkEvent(EventTag eventTag, DataPacket dataPacket) {
    // Locking for thread safety
    pthread_mutex_lock(&mutex);

    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->networkEvent = (NetworkEvent*)malloc(sizeof(NetworkEvent));
    newNode->next = head;

    // Populating the NetworkEvent structure
    newNode->networkEvent->eventTag = eventTag;
    newNode->networkEvent->dataPacket = dataPacket;

    // Updating the head of the list
    head = newNode;

    // Unlocking after critical section is finished
    pthread_mutex_unlock(&mutex);
}
