#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    unsigned RNTI;
    unsigned CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct array {
    pthread_mutex_t lock;
    size_t capacity;
    size_t count;
    NFAPI_CRC_INDICATION_PDU_T *data;
} array;

array* createArray(size_t initialCapacity) {
    array* arr = (array*) malloc(sizeof(array));
    if(!arr) return NULL;  // out of memory

    pthread_mutex_init(&arr->lock, NULL);
    arr->count = 0;
    arr->capacity = initialCapacity;
    arr->data = (NFAPI_CRC_INDICATION_PDU_T*) malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if(!arr->data) {
        free(arr);
        return NULL;  // out of memory
    }

    srand(time(NULL));  // initialize random seed
    for(size_t i = 0; i < arr->capacity; ++i) {
        arr->data[i].RX_UE_INFORMATION_TAG = rand();
        arr->data[i].RNTI = rand();
        arr->data[i].CRC_INDICATION_REL8_TAG = rand();
        arr->data[i].CRCFLAG = rand() % 2;
    }

    return arr;
}

int resize(array* arr, size_t newCapacity) {
    pthread_mutex_lock(&arr->lock);

    NFAPI_CRC_INDICATION_PDU_T *newData = (NFAPI_CRC_INDICATION_PDU_T*) realloc(arr->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if(!newData) {
        pthread_mutex_unlock(&arr->lock);
        return -1;  // out of memory
    }

    arr->data = newData;
    arr->capacity = newCapacity;

    pthread_mutex_unlock(&arr->lock);

    return 0;  // success
}
```

