#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <glib.h> /* GHashTable */

typedef struct {
    char ip[16];  // Assuming IPV4 addresses are used, which have up to 15 characters
    int port;
} PacketKey;

GHashTable* packets_table = NULL;
pthread_mutex_t mutex;

static unsigned int g_hash(gconstpointer v) {
    PacketKey *key = (PacketKey *)v;
    return abs((int)g_str_hash(key->ip)*31 + key->port);
}

static gboolean g_equal(gconstpointer a, gconstpointer b) {
    PacketKey *keyA = (PacketKey *)a;
    PacketKey *keyB = (PacketKey *)b;
    return !strcmp(keyA->ip, keyB->ip) && (keyA->port == keyB->port);
}

void init_packets() {
    packets_table = g_hash_table_new_full(g_hash, g_equal, NULL, g_free);
    pthread_mutex_init(&mutex, NULL);
}

int insert_packet(PacketKey key) {
    pthread_mutex_lock(&mutex);
    if (!g_hash_table_contains(packets_table, &key)) {
        gpointer packet = malloc(sizeof(struct Packet));  // Assuming struct Packet is the actual packet data type.
        if (packet == NULL) {
            pthread_mutex_unlock(&mutex);
            return -1;
        }

        memcpy(packet, &key, sizeof(PacketKey));  // Assuming Packet has a similar structure to Key.
        g_hash_table_insert(packets_table, g_memdup(&key, sizeof(PacketKey)), packet);
    }
    pthread_mutex_unlock(&mutex);

    return 0;
}

void remove_packet(PacketKey key) {
    pthread_mutex_lock(&mutex);
    gpointer packet = g_hash_table_lookup(packets_table, &key);
    if (packet != NULL) {
        free(packet);  // Assuming memory is allocated using malloc.
        g_hash_table_remove(packets_table, &key);
    }
    pthread_mutex_unlock(&mutex);
}

void iterate_over_packets() {
    pthread_mutex_lock(&mutex);

    GHashTableIter iter;
    gpointer key, value;
    g_hash_table_iter_init (&iter, packets_table);
    while (g_hash_table_iter_next (&iter, &key, &value)) {
        // Process packet.
    }

    pthread_mutex_unlock(&mutex);
}
``` 
This example uses the Glib library for hash maps which provides a thread-safe hash table implementation. The `PacketKey` struct is used to uniquely identify each packet, and the hash map stores packets with their corresponding keys. For the handling of memory allocation failures, we return -1 when malloc fails in `insert_packet()` function, while for thread safety, we use a mutex to prevent multiple threads from accessing the packet table simultaneously.

