#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int value;
} Record;

typedef struct {
    char label[10];
} Metadata;

// memory pool for reusing allocated memory
struct MemPoolNode{
   void* block;
   struct MemPoolNode* next;
};

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static struct MemPoolNode *memPool = NULL;  // Memory pool for reusing allocated memory

void *allocateMemory(size_t size){
    void* block;
    pthread_mutex_lock(&mutex);
    if (memPool != NULL) {
        // Reuse an existing block of memory from the pool.
        struct MemPoolNode* head = memPool;
        block = head->block;
        memPool = head->next;
        free(head);
    } else {
        block = malloc(size); 
    }
    pthread_mutex_unlock(&mutex);
    return block;
}

void deallocateMemory(void *block){
    pthread_mutex_lock(&mutex);
    struct MemPoolNode* node = (struct MemPoolNode*)malloc(sizeof(struct MemPoolNode));
    node->block = block;
    node->next = memPool;
    memPool = node;
    pthread_mutex_unlock(&mutex);
}

void *dynamicAllocationWithMemoryReuseAndThreadSafety(size_t size, int includeMetadata){
    long* offsetValues = allocateMemory(sizeof(long) * size);
    if (offsetValues == NULL) return NULL;

