        packets[i] = init_packet("192.168.0.1", "192.168.0.2", 100, 6); // Example packet metadata
    }
    while (1) {
        add_flow(id, time(NULL), packets, 5);
        sleep(1);
    }
}

// Main function to start multiple threads for traffic processing from different sources
int main() {
    pthread_t threads[MAX_FLOWS];
    int i;
    for (i = 0; i < MAX_FLOWS; i++) {
        if(pthread_create(&threads[i], NULL, process_traffic, (void*)(unsigned long)i)){
            printf("Error creating thread\n");
            return 1;
        }
