['Here's a basic example of how you could accomplish this task in C# using ADO.NET. Please note that this example does not take all your requirements into account (like logging, monitoring, etc.), it just shows how to use `SqlDataReader` with cursor-based approach. Also it might not be optimal for all situations as a generic solution because of the lack of concurrency control and other optimizations:

```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Data;
using System.Data.SqlClient;

public class ConfigObject
{
    public int ConcurrencyLevel { get; set; } = 1;
    public int BatchSize { get; set; } = 1000;
}

public delegate void DataProcessingDelegate(IDataRecord record);

class StreamingDataProcessor
{
    private ConfigObject config;
    private SqlConnection connection;
    private string sqlCommandText;
    private DataProcessingDelegate processDelegate;

    public StreamingDataProcessor(SqlConnection connection, string sqlCommandText, 
                                  DataProcessingDelegate processDelegate, ConfigObject config = null)
    {
        this.connection = connection ?? throw new ArgumentNullException(nameof(connection));
        this.sqlCommandText = sqlCommandText ?? throw new ArgumentNullException(nameof(sqlCommandText));
        this.processDelegate = processDelegate ?? throw new ArgumentNullException(nameof(processDelegate));

        if (config != null)
            this.config = config;
        else 
            this.config = new ConfigObject();
    }

    public void Process()
    {
        using (SqlCommand command = new SqlCommand(sqlCommandText, connection))
        {
            connection.Open();

            using (var reader = command.ExecuteReader())
            {
                while (reader.Read())
                {
                    processDelegate?.Invoke(reader);
                }
            }

            connection.Close();
        }
    }
}
```

To use this class, you would do something like:

