    if (AES_set_encrypt_key(key, keyLen * 8, &aes_key) < 0) {
        printf("Failed to set AES encryption key.\n");
        pthread_mutex_unlock(&aes_cipher_ctx_lock);
        return -1;
    }

    // Allocate memory for ciphertext.
    *ciphertext = malloc(plaintextLen + (AES_BLOCK_SIZE - plaintextLen % AES_BLOCK_SIZE));
    if (*ciphertext == NULL) {
        printf("Failed to allocate memory for ciphertext.\n");
        pthread_mutex_unlock(&aes_cipher_ctx_lock);
        return -1;
    }

    // Encrypt the plaintext.
    AES_cbc_encrypt(plaintext, *ciphertext, plaintextLen, &aes_key, iv, AES_ENCRYPT);

    // Unlock the mutex after using the cipher context.
    pthread_mutex_unlock(&aes_cipher_ctx_lock);

    *ciphertextLen = plaintextLen + (AES_BLOCK_SIZE - plaintextLen % AES_BLOCK_SIZE);

