char *configureCell(LTE_ENB_API_STRUCT cell, bool addOnly) {
    if (addOnly && checkOverlap(cell)) {
        return "Error: Overlapping frequency bands or PCI values";
    }

    // Add the node to list and increment size
    ListNode* newNode = (ListNode*) malloc(sizeof(ListNode));
    newNode->data = cell;
    newNode->next = head;
    head = newNode;
    size++;

    return "Cell successfully configured";
}

char *removeCell(LTE_ENB_API_STRUCT cell) {
    ListNode* temp = head, *prev = NULL;

    while (temp != NULL && (temp->data.frequencyBands != cell.frequencyBands || 
                            temp->data.pci != cell.pci)) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return "Error: Cell not found";

    // Unlink the node from list and free memory, decrement size
    if(prev != NULL)
        prev->next = temp->next;

    // Change head
    if(head == temp) 
        head = temp->next;

    free(temp);
    size--;

    return "Cell successfully removed";
}

void deallocateList() {
    ListNode* current = head;
    ListNode* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    head = NULL;
    size = 0;
}
```
