struct point {
    int x;
    int y;
};

double* distance_array;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* loadData(void* arg) {
    pthread_mutex_lock(&mutex);

    struct point* p = (struct point*)arg;
    int size = sizeof(p)/sizeof(struct point);

    for(int i = 0; i < size - 1; ++i) {
        double dx = p[i+1].x - p[i].x;
        double dy = p[i+1].y - p[i].y;

        distance_array[i] = sqrt(dx*dx + dy*dy);
    }

    pthread_mutex_unlock(&mutex);
    return NULL;
}

double* handleMemory() {
    // Dynamically allocate memory for double precision floating point number array and char byte value array.
    double* arr1 = (double*)malloc(sizeof(double) * 100);
    char* arr2 = (char*)malloc(sizeof(char) * 100);

    // Dynamically allocate memory for the 'struct point' array.
    struct point* p_arr = (struct point*)malloc(sizeof(struct point) * 100);

    if(arr1 == NULL || arr2 == NULL || p_arr == NULL) {
        printf("Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    // Initialize the arrays.
    for (int i = 0; i < 100; ++i) {
        arr1[i] = i + 0.5;
        arr2[i] = 'A' + i%26;
        p_arr[i].x = i;
        p_arr[i].y = i * 2;
    }

    // Dynamically allocate memory for the distance array.
    distance_array = (double*)malloc(sizeof(double) * 99);

    if(distance_array == NULL){
