    if (fp == NULL) {
        printf("Failed to open file.\n");
        exit(EXIT_FAILURE);
    }

    // Handle potential data corruption or incomplete data gracefully.
    for (int i = 0; i < 100; ++i) {
        if (fscanf(fp, "%lf %c %d %d", &arr1[i], &arr2[i], &p_arr[i].x, &p_arr[i].y) != 4){
            printf("Data corruption or incomplete data detected. Aborting.\n");
            exit(EXIT_FAILURE);
        }
    }

    fclose(fp);

    // Create a thread to handle memory management for the point array.
    pthread_t tid;
    if (pthread_create(&tid, NULL, loadData, p_arr)) {
        printf("Failed to create thread.\n");
        exit(EXIT_FAILURE);
    }

    // Wait for the thread to finish.
    if (pthread_join(tid, NULL)){
        printf("Thread join failed.\n");
        exit(EXIT_FAILURE);
    }

    // Free the memory allocated to individual arrays.
    free(arr1);
    free(arr2);
    free(p_arr);

    return distance_array;
}
```
