typedef struct DynamicList {
    pthread_mutex_t mutex;
    size_t count;
    NFAPI_CRC_INDICATION_PDU_T **items;
} DynamicList;

void dynamic_list_init(DynamicList *list) {
    pthread_mutex_init(&list->mutex, NULL);
    list->count = 0;
    list->items = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * MAX_LIST_SIZE);
}

void dynamic_list_destroy(DynamicList *list) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; ++i) {
        free(list->items[i]);
    }
    free(list->items);
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

int dynamic_list_add(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T* item) {
    int result = 0;
    pthread_mutex_lock(&list->mutex);
    if (list->count < MAX_LIST_SIZE) {
        list->items[list->count++] = item;
        result = 1; // Success
    } else {
        result = 0; // Failure due to full capacity
    }
    pthread_mutex_unlock(&list->mutex);
    return result;
}
```
