```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include "jansson.h" // A C library for parsing JSON

typedef struct bundle {
    json_t *json;
    int count;
} Bundle;

typedef struct cacheEntry {
    char* path;
    Bundle* bundle;
    pthread_mutex_t lock;
    struct cacheEntry* next;
} CacheEntry;

CacheEntry* cache = NULL;
pthread_mutex_t cacheLock = PTHREAD_MUTEX_INITIALIZER;

Bundle* loadFromFile(char* path) {
    // Check the cache first
    pthread_mutex_lock(&cacheLock);
    CacheEntry* entry = cache;
    while (entry != NULL && strcmp(entry->path, path) != 0) {
        entry = entry->next;
    }

    if (entry == NULL) {
        // Not in the cache - load from file and add to cache
        pthread_mutex_unlock(&cacheLock);

        json_error_t error;
        Bundle* bundle = malloc(sizeof(Bundle));
        if (!bundle) {
            return NULL;  // Error allocating memory
        }

        bundle->json = json_load_file(path, 0, &error);
        if(!bundle->json) {
            free(bundle);
            return NULL;  // Error reading the file or parsing as JSON
        }

        bundle->count = 0;
        json_t *key, *value;
        void* iter = json_object_iter(bundle->json);
        while (key = json_object_iter_next(&key, &value)) {
            bundle->count++;  // Replace with actual counting logic if necessary
        }

        pthread_mutex_lock(&cacheLock);
        CacheEntry* newEntry = malloc(sizeof(CacheEntry));
        if (newEntry) {
            strcpy(newEntry->path, path);  // Error checking needed here
            newEntry->bundle = bundle;
            pthread_mutex_init(&newEntry->lock, NULL);
            newEntry->next = cache;
        }
        pthread_mutex_unlock(&cacheLock);

        return bundle;
    } else {
        // In the cache - lock and return
        Bundle* result = entry->bundle;
        pthread_mutex_lock(&entry->lock);
        pthread_mutex_unlock(&cacheLock);
        return result;
    }
}
```
Please note that error checking is very basic in this example. You would need to expand it depending on your needs (e.g., make sure malloc doesn't fail, check the return values from strcpy and json_load_file, etc.). Also, be aware that there are many ways to handle thread safety here, and you may want to adjust this code based on your specific requirements.
