["The following C code snippets can serve as a starting point for solving this problem. This is not a full solution but a high-level overview of how you might approach it. 

This program uses POSIX threads and OpenSSL for thread synchronization and random number generation respectively.

```c
#include <pthread.h>
#include <openssl/rand.h>

typedef struct NFAPI_CRC_INDICATION_PDU {
    int RNTI;
    float CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_NUM_PDUS 1024
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T *pduList[MAX_NUM_PDUS];
static int numPDUs = 0;

void addPDU(int RNTI, float CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&mutex);
    if (numPDUs >= MAX_NUM_PDUS) {
        // Handle error or resize list
        exit(-1);
    } else {
        unsigned char randomByte;
        RAND_bytes(&randomByte, 1);
        int CRCFLAG = (int)randomByte & 0x01;

        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu->RNTI = RNTI;
        pdu->CRC_INDICATION_REL8_TAG = CRCFLAG ? CRC_INDICATION_REL8_TAG : 0;

        pduList[numPDUs++] = pdu;
    }
    pthread_mutex_unlock(&mutex);
}

float calculateRollingAverage(int RNTI) {
    float sum = 0.0f;
    int count = 0;

    pthread_mutex_lock(&mutex);
    for (int i = 0; i < numPDUs; ++i) {
        if (pduList[i]->RNTI == RNTI && pduList[i]->CRC_INDICATION_REL8_TAG != 0) {
            sum += pduList[i]->CRC_INDICATION_REL8_TAG;
            ++count;
        }
    }
    pthread_mutex_unlock(&mutex);

    return count > 0 ? sum / count : 0.0f;
}
```
This code creates a list of PDUs and calculates the rolling average for each RNTI as requested. It uses mutexes to ensure thread safety when modifying the shared data structure (the pduList array).

