pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
void updateStatsRecord(UEStatsRecord* record, double value) {
    MeasurementReport report = { .timestamp = time(NULL), .value = value };

    pthread_mutex_lock(&mutex);
    if (record->reportsSize == record->reportsCapacity) {
        // Double the capacity when full
        record->reportsCapacity *= 2;
        record->reports = realloc(record->reports, sizeof(MeasurementReport) * record->reportsCapacity);
