typedef struct {
    double value;
    time_t timestamp;
    int valid;
} Record;

Record **records;
int *keys, *offsets;
int NUM_RECORDS = 100;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void init() {
    records = malloc(NUM_RECORDS * sizeof(Record*));
    keys = malloc(NUM_RECORDS * sizeof(int));
    offsets = malloc(NUM_RECORDS * sizeof(long));

    srand((unsigned)time(NULL));
    for (int i = 0; i < NUM_RECORDS; ++i) {
        records[i] = malloc(sizeof(Record));
        keys[i] = rand();
        offsets[i] = rand();

        struct timeval tv;
        gettimeofday(&tv, NULL);
        records[i]->timestamp = tv.tv_sec * 1000 + tv.tv_usec / 1000;
    }
}

void update(int key) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < NUM_RECORDS; ++i) {
        if (keys[i] == key) {
            struct timeval tv;
            gettimeofday(&tv, NULL);

            records[i]->value = rand() % 1000 + 1.0 / (rand() % 1000 + 1); // Random double within the range [1,2]
            records[i]->timestamp = tv.tv_sec * 1000 + tv.tv_usec / 1000;
        }
    }
    pthread_mutex_unlock(&lock);
}

void invalidate(int key) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < NUM_RECORDS; ++i) {
        if (keys[i] == key) {
            struct timeval tv;
            gettimeofday(&tv, NULL);

            records[i]->valid = 0;
            records[i]->timestamp = tv.tv_sec * 1000 + tv.tv_usec / 1000;
        }
    }
    pthread_mutex_unlock(&lock);
}
```
