static mtx_t dataMutex = MTX_INIT;

DataPacket* initDataPackets(size_t num, size_t size) {
    static atomic_ullong counter = 0;

    if (mtx_lock(&dataMutex)) {
        fprintf(stderr, "Could not lock mutex during packet initialization\n");
        return NULL;
    }

    DataPacket* packets = malloc(num * sizeof(DataPacket));
    if (!packets) {
        fprintf(stderr, "Memory allocation failed for packets array.\n");
        mtx_unlock(&dataMutex);
        return NULL;
    }

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < num; ++i) {
        char* payload = malloc(size);

        if (!payload) {
            fprintf(stderr, "Memory allocation failed for packet payload.\n");
            free(packets);
            mtx_unlock(&dataMutex);
