        for (size_t j = 0; j < size; ++j) {
            payload[j] = rand() % 256;
        }

        packets[i].id = atomic_fetch_add(&counter, 1);
        packets[i].timestamp = time(NULL);
        packets[i].payload = payload;
    }

    mtx_unlock(&dataMutex);

    return packets;
}
