['Here's how you can implement this in C. This solution involves creating a dynamic array that grows automatically as new complex numbers are added, and ensures unique indices by checking an index table before assigning. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <string.h>
#include <time.h>

typedef struct {
    double real;
    int imag;
} ComplexNumber;

typedef struct {
    ComplexNumber* number_ptr;
    size_t index;
} IndexedComplexNumber;

typedef struct {
    size_t capacity;  // total capacity
    size_t count;     // current used capacity
    IndexedComplexNumber *array;
} DynamicArray;

DynamicArray array = { .capacity = 1000, .count = 0 };
int index_table[10000] = {0};  // table to check if an index has been used before

void init_complex_number(ComplexNumber* num) {
    srand((unsigned int)time(NULL));
    double real_part =  (double)(rand() % 201 - 100);   // random value between -100 and +100
    int imag_part = rand() % 201 - 100;                 // random value between -100 and +100
    *num = (ComplexNumber){ .real = real_part, .imag = imag_part };
}

size_t generate_unique_index(void) {
    size_t index;
    while (1) {
        index = rand() % 10000; // random value between 0 and 9999
        if (!index_table[index]) {
            index_table[index] = 1;
            return index;
        }
    }
}

void add_complex_number(DynamicArray* array) {
    if (array->count == array->capacity) {  // reallocate when capacity is exceeded
        size_t new_capacity = array->capacity * 2;
        IndexedComplexNumber* temp_arr = realloc(array->array, sizeof(IndexedComplexNumber) * new_capacity);
        if (temp_arr == NULL) {
            printf("Memory allocation failed\n");
            exit(-1);
        }
        array->array = temp_arr;
        array->capacity = new_capacity;
    }

    ComplexNumber* num = malloc(sizeof(ComplexNumber));  // allocate memory for complex number
    init_complex_number(num);  // initialize complex number
    size_t index = generate_unique_index();   // generate unique index

    array->array[array->count] = (IndexedComplexNumber){ .number_ptr = num, .index = index };
    array->count++;  // increment count
}
```
This implementation creates a dynamic array of complex numbers along with their indices. When the capacity is exceeded, memory for more complex numbers are allocated. If memory allocation fails, the program terminates gracefully with an error message. Indices are generated randomly and checked against an index table to ensure uniqueness. 

Note: For multithreaded environments, proper locking should be used when accessing `array` or modifying `index_table` to avoid race conditions. 

Also consider using a hash map instead of `index_table` for better performance in lookups and insertions.
']

