void* init_resources(float float_values[], unsigned short ids[], size_t num) {
    sys.floats = malloc(num * sizeof(float));
    if (sys.floats == NULL) return NULL;
    memcpy(sys.floats, float_values, num * sizeof(float));

    sys.ids = malloc(num * sizeof(unsigned short));
