    memcpy(sys.ids, ids, num * sizeof(unsigned short));

    data_node *current = sys.head;
    for (size_t i = 0; i < num; ++i) {
        current->next = malloc(sizeof(data_node));
        if (current->next == NULL) return NULL;
        memset(current, 0, sizeof(data_node));
    }

    pthread_mutex_init(&sys.lock, NULL);
    gettimeofday(&sys.start_time, NULL);
    sys.num_inserts = sys.num_retrievals = 0;

    return &sys;
}

void free_resources() {
    pthread_mutex_destroy(&sys.lock);
    free(sys.floats);
    free(sys.ids);

    data_node *current = sys.head, *next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
}

