        // Handle allocation failure, e.g., by returning NULL
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(*pdu));
    if (pdu == NULL) {
        // Handle allocation failure
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    pool[pool_count++] = pdu;

    // Handle successful allocation, e.g., by logging the event

    pthread_mutex_unlock(&lock);
    return pdu;
}

void deallocate(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < pool_count; ++i) {
        if (pool[i] == pdu) {
            free(pdu);

            // Move the last element to this position and decrement count
            pool[i] = pool[--pool_count];

            // Handle successful deallocation, e.g., by logging the event
            pthread_mutex_unlock(&lock);
            return;
        }
    }

