extern void log_event(char* message); 
extern void cache_ip_address(char* hostname, u_char* ip_addr);
extern u_char* get_cached_ip_address(char* hostname);

#define MAX_CONCURRENT_REQUESTS 10
#define CACHE_SIZE 1024 // Adjust this as per requirement

void* dns_lookup(void* arg) {
    char *hostname = (char*)arg;
    struct hostent *hp;

    u_char ip_addr[INET6_ADDRSTRLEN];

    // Check if the IP address is in cache
    u_char* cached_ip = get_cached_ip_address(hostname);
    if (cached_ip != NULL) {
        memcpy(ip_addr, cached_ip, INET6_ADDRSTRLEN);
    } else { 
        hp = gethostbyname(hostname);
        // Handle error
        if (!hp){
            log_event("DNS resolution failed");
            return NULL; 
        }

        // Copy the resolved IP address to our buffer
        memcpy(ip_addr, hp->h_addr_list[0], hp->h_length);

        // Cache the ip for future use
        cache_ip_address(hostname, ip_addr);
    }

    log_event("DNS resolution successful");
    return ip_addr; 
}

int main() {
    char hostnames[MAX_CONCURRENT_REQUESTS][256] = {"www.google.com", "www.yahoo.com"}; // Assume these are the host names you want to resolve

    pthread_t threads[MAX_CONCURRENT_REQUESTS];

