#include <stdio.h>
#include <netdb.h>
#include <arpa/inet.h>

int resolve_hostname(char* hostname, struct in_addr *addr) {
    struct addrinfo hints;
    struct addrinfo *res = NULL;
    int ret;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // use IPv4
    hints.ai_socktype = SOCK_STREAM; // use TCP stream sockets

    if ((ret = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo failed: %s\n", gai_strerror(ret));
        return -1; // return error code
    }

    memcpy(addr, &((struct sockaddr_in *) res->ai_addr)->sin_addr, sizeof(struct in_addr));
    freeaddrinfo(res);

    return 0; // success
}
```
This code uses the `getaddrinfo` function from the C standard library to perform DNS resolution. The hostname is passed as a string and an `in_addr` struct is filled with the IP address returned by DNS. If the function fails, it prints an error message and returns -1. Otherwise, it returns 0 to indicate success.

