typedef struct {
    int value;
} Record;

// Define a global lock for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* allocateAndInitialize(long** offsets, int** keys, Record** records, int n, int min, int max) {
    pthread_mutex_lock(&lock); // Lock to ensure thread safety

    *offsets = malloc(n * sizeof(long));
    if(*offsets == NULL) {
        FILE* logFile = fopen("log.txt", "a");
        fprintf(logFile, "Memory allocation failure for offsets\n");
        fclose(logFile);
        return NULL;
    }

    *keys = malloc(n * sizeof(int));
    if(*keys == NULL) {
        FILE* logFile = fopen("log.txt", "a");
        fprintf(logFile, "Memory allocation failure for keys\n");
        fclose(logFile);

        free(*offsets); // Clean up previously allocated memory
        return NULL;
    }

    *records = malloc(n * sizeof(Record));
    if(*records == NULL) {
        FILE* logFile = fopen("log.txt", "a");
        fprintf(logFile, "Memory allocation failure for records\n");
        fclose(logFile);

        free(*offsets); // Clean up previously allocated memory
        free(*keys);    // Clean up previously allocated memory
        return NULL;
    }

    srand(time(NULL));  // Seed the random number generator
    for (int i = 0; i < n; i++) {
        (*offsets)[i] = rand();   // Initialize offsets with random values

        int range = max - min + 1;
        if(range <= RAND_MAX) { 
            int limit = RAND_MAX - RAND_MAX % range;

            int rnd;
            do {
                rnd = rand();
            } while (rnd >= limit);

            (*keys)[i] = min + rnd % range; // Initialize keys with random values in a specified range
        } else {
            (*keys)[i] = min + ((int) (((long)range * rand()) / RAND_MAX)); // Handle integer overflow
        }

        (*records)[i].value = (*keys)[i];  // Initialize record values with corresponding key values
    }

    pthread_mutex_unlock(&lock); // Unlock after memory allocation and initialization
    return NULL;
}

void cleanupMemory(long** offsets, int** keys, Record** records) {
    free(*offsets);  // Clean up allocated memory
    *offsets = NULL;

    free(*keys);     // Clean up allocated memory
    *keys = NULL;

    free(*records);  // Clean up allocated memory
    *records = NULL;
}
```
This code provides a C function that allocates and initializes two arrays for 'long' offset values, one for 'int' keys, and an array of 'record' structures. It uses a lock to ensure thread safety during memory allocation and initialization. If any memory allocation fails, it logs the error into a log file and cleans up previously allocated memory. After use, it provides a function to clean up all allocated memory when the function exits, avoiding memory leaks.
