['Below is an example code snippet for this task. This code uses POSIX APIs (`dirent.h`, `fnmatch.h`) and OpenSSL library for SHA1 hash. 

```C
#include <stdio.h>
#include <string.h>
#include <sys/types.h>
#include <dirent.h>
#include <errno.h>
#include <openssl/sha.h>
#include <time.h>
#include <unistd.h>
#include <fnmatch.h>

void rename_files(const char *dir_path, const char *file_pattern) {
    DIR *dir;
    struct dirent *entry;
    unsigned char hash[SHA_DIGEST_LENGTH];
    SHA_CTX sha1;
    FILE *file;
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20], filename[256], newfilename[280], oldpath[4096], newpath[4096];

    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);

    if ((dir = opendir(dir_path)) != NULL) {
        while ((entry = readdir(dir)) != NULL) {
            if (fnmatch(file_pattern, entry->d_name, 0) == 0) { // match pattern
                snprintf(oldpath, sizeof(oldpath), "%s/%s", dir_path, entry->d_name);
                strncpy(filename, entry->d_name, 255); // copy base name of file
                filename[sizeof(filename)-1] = '\0'; // ensure null termination

                // compute SHA1 hash of filename without extension and convert to hexadecimal string
                char *dot = strrchr(filename, '.');
                if (dot) {*dot='\0';}
                SHA1_Init(&sha1);
                SHA1_Update(&sha1, filename, strlen(filename));
                unsigned char md[SHA_DIGEST_LENGTH];
                SHA1_Final(md, &sha1);

                for (int i = 0; i < SHA_DIGEST_LENGTH; ++i) {sprintf(&filename[strlen(filename)], "%02x", md[i]);}
                if (dot) {*dot='.';}

                // construct new filename with timestamp, unique identifier and original extension
                snprintf(newfilename, sizeof(newfilename), "%s_%s.%s", entry->d_name, timestamp, entry->d_extension);

                if (strlen(oldpath) + strlen(newfilename) < 4096) { // check total length doesn't exceed 4096 bytes
                    snprintf(newpath, sizeof(newpath), "%s/%s", dir_path, newfilename);

                    if ((file = fopen(oldpath, "r")) != NULL) { // open file to check it exists before renaming
                        fclose(file);

                        if (rename(oldpath, newpath) == 0) {printf("Renamed '%s' to '%s'\n", oldpath, newpath);}
                        else {fprintf(stderr, "Failed to rename '%s' to '%s': %s\n", oldpath, newpath, strerror(errno));}
                    }
                } 
                else {fprintf(stderr, "Path too long: '%s'\n", newfilename);}
            }
        }
        closedir(dir);
    } 
    else {fprintf(stderr, "Could not open directory '%s': %s\n", dir_path, strerror(errno));}
}
```
This is a basic example and does not include error handling or optimization for performance. For production code, you would need to add more robust error checking, handling of special cases (like files that are in use by other processes), parallel execution using threads or processes, memory management, etc.
