#define MAX_LENGTH 10
#define RETRY_COUNT 3

typedef struct {
    char* userData;
    int maxLength;
} UserProfileArgs;

void* handleNetworkError(void *args) {
    sleep(rand() % 5 + 1); // Simulate network latency
    return NULL;
}

int validateDirectory(const char* path) {
    if (access(path, F_OK) != -1) {
        return 1;
    } else {
        if (mkdir(path, 0700) == -1) {
            perror("Could not create directory");
            exit(EXIT_FAILURE);
        }
        printf("Directory created\n");
    }
    return 0;
}

char* generateUsername(const char *base, int maxLength) {
    srand((unsigned) time(NULL)); // seed random number generator
    char* username = malloc(maxLength + 1);
    strncpy(username, base, maxLength / 2);
    for (int i = strlen(base); i < maxLength; ++i) {
        username[i] = '0' + rand() % 10; // Append a random digit
    }
    username[maxLength] = '\0';

    return username;
}

void* createUserProfile(void *args_ptr) {
    UserProfileArgs args = *((UserProfileArgs*) args_ptr);
    char* path = "/path/to/userdata"; // Change to actual directory path
    pthread_mutex_t lock;

    if (pthread_mutex_init(&lock, NULL) != 0) {
        perror("Failed to initialize mutex");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&lock);

    validateDirectory(path);

    char* username;
    int i = 0;

    do {
        if (i++ > RETRY_COUNT) {
            printf("Failed to generate unique username after %d attempts\n", i);
            exit(EXIT_FAILURE); // Change as per your requirement
        }

        username = generateUsername(args.userData, args.maxLength);
    } while (access((*path), F_OK) != -1 && ++i <= RETRY_COUNT);

    pthread_mutex_unlock(&lock);

    return NULL;
