typedef struct {
    int color_type;
    int bit_depth;
    char compression[50];
    int interlace;
    int background_chunks;
    int text_chunks;
} PNGInfo;

PNGInfo get_png_info(const char *filename) {
    FILE *fp = fopen(filename, "rb");

    if (!fp) {
        printf("Unable to open file %s\n", filename);
        exit(1);
    }

    png_structp png_ptr = png_create_read_struct(PNG_LIBPNG_VER_STRING, NULL, NULL, NULL);
    if (!png_ptr) {
        fclose(fp);
        printf("Unable to create read struct\n");
        exit(1);
    }

    png_infop info_ptr = png_create_info_struct(png_ptr);
    if (!info_ptr) {
        png_destroy_read_struct(&png_ptr, NULL, NULL);
        fclose(fp);
        printf("Unable to create info struct\n");
        exit(1);
    }

    if (setjmp(png_jmpbuf(png_ptr))) {
        png_destroy_read_struct(&png_ptr, &info_ptr, NULL);
        fclose(fp);
        printf("Error during init_io\n");
        exit(1);
    }

    png_init_io(png_ptr, fp);
    png_read_info(png_ptr, info_ptr);

    PNGInfo png_info;
    memset(&png_info, 0, sizeof(PNGInfo));

    png_get_IHDR(png_ptr, info_ptr, &width, &height, &bit_depth, &color_type, &interlace_method, NULL, NULL);

    if (color_type < 0 || color_type > 6) {
        printf("Unsupported color type\n");
        exit(1);
    }

    png_info.color_type = color_type;
    png_info.bit_depth  = bit_depth;

    if (interlace_method == PNG_INTERLACE_NONE) {
        png_info.interlace = 0;
    } else if (interlace_method == PNG_INTERLACE_ADAM7) {
        png_info.interlace = 1;
    }

    png_textp text;
    int num_text;
    if (png_get_text(png_ptr, info_ptr, &text, &num_text)) {
        for (int i=0; i<num_text; i++) {
            char *key = text[i].key;
            if (strcmp(key, "Background") == 0) {
                png_info.background_chunks++;
            } else if (strcmp(key, "Text") == 0) {
                png_info.text_chunks++;
            }
        }
    } 

    strncpy(png_info.compression, png_get_compression_type(png_ptr, info_ptr), sizeof(png_info.compression));
    png_destroy_read_struct(&png_ptr, &info_ptr, NULL);
    fclose(fp);

    return png_info;
}
```

