    int RNTI;
    NFAPI_CRC_INDICATION_PDU_T* pdu;
    struct HashNode* next;
} HashNode;
HashNode hashTable[HASH_TABLE_SIZE];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to generate a hash value from RNTI
int hash(int rnti) {
    return abs(rnti % HASH_TABLE_SIZE);
}

// Insert a new structure into the hash table
void insertIntoHashTable(NFAPI_CRC_INDICATION_PDU_T* pdu, int RNTI) {
    HashNode* node = malloc(sizeof(HashNode));
    node->RNTI = RNTI;
    node->pdu = pdu;

    int index = hash(RNTI);
    pthread_mutex_lock(&mutex); // lock to ensure thread safety
    node->next = hashTable[index].next;
    hashTable[index].next = node;
    pthread_mutex_unlock(&mutex); // unlock
}

// Find a structure in the hash table by RNTI
NFAPI_CRC_INDICATION_PDU_T* findInHashTable(int RNTI) {
    int index = hash(RNTI);
    pthread_mutex_lock(&mutex); // lock to ensure thread safety

    HashNode* node;
    for (node = hashTable[index].next; node != NULL; node = node->next) {
        if (node->RNTI == RNTI) {
            pthread_mutex_unlock(&mutex); // unlock
            return node->pdu;
        }
    }

