#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    // Your structure definition here. 
} NFAPI_CRC_INDICATION_PDU_T;

// Memory pool of structures:
NFAPI_CRC_INDICATION_PDU_T *memory_pool = NULL;
size_t M = 0, current_size = 0;
sem_t semaphore;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Allocate and initialize a new structure:
NFAPI_CRC_INDICATION_PDU_T *allocate_structure() {
    pthread_mutex_lock(&mutex);
    sem_wait(&semaphore);
    // Check if more space is needed in the memory pool:
    if (current_size == M) {
        NFAPI_CRC_INDICATION_PDU_T *new_pool = realloc(memory_pool, sizeof(*new_pool) * (M + 1024)); // Increase by 1024 on full.
        if (!new_pool) {
            sem_post(&semaphore);
            pthread_mutex_unlock(&mutex);
            return NULL; // Out of memory.
        }
        memory_pool = new_pool;
        M += 1024;
    }
    NFAPI_CRC_INDICATION_PDU_T *result = &memory_pool[current_size++];
    sem_post(&semaphore);
    pthread_mutex_unlock(&mutex);
    return result;
}

// Deallocate a structure:
void deallocate_structure(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&mutex);
    // Move the last element to this position and update the size:
    if (--current_size > 0 && pdu != &memory_pool[current_size])
        *pdu = memory_pool[current_size];
    sem_post(&semaphore);
    pthread_mutex_unlock(&mutex);
}
```

This code uses a single large block of memory to store all the structures. When a structure is needed, it simply allocates from this pool in constant time, and when an existing structure is freed, it moves the last one to its position (in O(1) time). This minimizes heap fragmentation. 

The `sem_wait` call ensures that only one thread can access the memory pool at a time, providing serialization for multi-threaded access without using locks or explicit synchronization primitives. 

