    char *Interface_Name;
    char *IP_Address;
    int Subnet_Mask;
    char *Gateway_Address;
} Network_Configuration;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

Network_Configuration* configure_network_interface(Network_Configuration *configurations, int size) {
    Network_Configuration *result = malloc(sizeof(Network_Configuration) * size);

    if (result == NULL) {
        printf("Failed to allocate memory\n");
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        Network_Configuration configuration = configurations[i];

        pthread_mutex_lock(&mutex);

        // Validation
        if (!validateIP(configuration.IP_Address)) {
            printf("Invalid IP address: %s\n", configuration.IP_Address);
            continue;
        }
        if (configuration.Subnet_Mask < 1 || configuration.Subnet_Mask > 32) {
            printf("Invalid subnet mask: %d\n", configuration.Subnet_Mask);
            continue;
        }
        // Simulate a delay to simulate the effect of high network traffic
        sleep(1);

        // Copy the structure
        result[i] = configurations[i];

        pthread_mutex_unlock(&mutex);
    }

    return result;
}

int validateIP(char *ip) {
    int num, dots = 0;
    char temp[20];

    strcpy(temp, ip);

    if (ip == NULL)
        return 0;

    char *ptr = strtok(temp, ".");

    if (ptr == NULL)
        return 0;

    while (ptr) {
        if (!strlen(ptr))
            return 0;

        num = atoi(ptr); // String to integer

        if (num >= 0 && num <= 255) {
            ptr = strtok(NULL, ".");

            if (ptr != NULL)
                ++dots;
        } else
            return 0;
    }

    if (dots != 3)
        return 0;

    return 1;
}
```
This code first validates the IP address and subnet mask. If validation fails, it skips this iteration and continues with the next one. It simulates a delay to simulate high network traffic conditions. After successful validation, it copies the configuration into the result array. To ensure thread safety, it uses a mutex lock before accessing shared memory.
