```c
#include <stdlib.h>
#include <pthread.h>
#define TABLE_SIZE 100
typedef struct Record {
    int key;
    int value;
    void *metadata;
    size_t metadataSize;
} Record;

Record **recordTable;
pthread_mutex_t tableLock = PTHREAD_MUTEX_INITIALIZER;

void recordInit(int capacity) {
    // Initialize the hash table with a certain capacity.
    recordTable = (Record **)calloc(capacity, sizeof(Record *));
}

void recordInsert(int key, int value, void *metadata, size_t metadataSize) {
    pthread_mutex_lock(&tableLock);

    // Hash the key to find an appropriate slot in the table.
    int index = abs(key % TABLE_SIZE);

    if (recordTable[index] != NULL) {
        // Handle collision by linear probing.
        while (recordTable[(++index) % TABLE_SIZE] != NULL);
    }

    recordTable[index] = malloc(sizeof(Record));
    recordTable[index]->key = key;
    recordTable[index]->value = value;
    recordTable[index]->metadata = metadata;
    recordTable[index]->metadataSize = metadataSize;

    pthread_mutex_unlock(&tableLock);
}

Record *recordLookup(int key) {
    // Hash the key to find the slot in the table.
    int index = abs(key % TABLE_SIZE);

    if (recordTable[index] != NULL && recordTable[index]->key == key) {
        return recordTable[index];
    } else if (recordTable[index] != NULL) {
        // Handle collision by linear probing.
        while ((++index % TABLE_SIZE) != abs(key % TABLE_SIZE)) {
            if (recordTable[index] != NULL && recordTable[index]->key == key) {
                return recordTable[index];
            }
        }
    }

    return NULL;  // Record not found.
}

void recordDelete(int key) {
    pthread_mutex_lock(&tableLock);

    Record *record = recordLookup(key);
    if (record != NULL) {
        free(record->metadata);
        free(record);
    }

    pthread_mutex_unlock(&tableLock);
}
```
This is a very basic example and does not include caching, logging mechanisms or memory management for errors. Further development would require additional features such as eviction policy in cache system, dynamic resizing of the hash table, thread safety and error handling.
