    return abs(cellId % MAX_RECORDS);
}

// Thread-safe way of allocating memory from the pool and returning its address 
NrCellMeasurementRecord *allocateMemoryForPool() {
    pthread_mutex_lock(&lock);
    if (pool_index == MAX_RECORDS) {
        // Handle error or reallocate memory
    }

    NR_CELL_MEASUREMENT_RECORD *record = &(pool[pool_index++]);
    pthread_mutex_unlock(&lock);

