    int index = getIndexFromHash(cellId);

    pthread_mutex_lock(&lock);
    hash_node_t * node;
    for (node = hashTable[index]; node != NULL; node = node->next) {
        if (node->record->CELL_ID == cellId) {
            pthread_mutex_unlock(&lock);
            return node->record;
        }
    }
    pthread_mutex_unlock(&lock);

    // Record not found, handle error
    return NULL;
}

// Function to update a record. 
