```
The mutex will ensure that only one thread can access the collection at a time. 

For adding a new event, we should allocate memory for it and set its fields:
```c
event_log* create_event(const char* message, int status_code) {
    pthread_mutex_lock(&lock);

    event_log* log = malloc(sizeof(event_log));
    if (log == NULL) {
        pthread_mutex_unlock(&lock);
        return NULL; // Handle memory allocation failure.
    }

    size_t message_length = strlen(message);
    char* new_message = malloc((message_length + 1) * sizeof(char));
    if (new_message == NULL) {
        free(log);
        pthread_mutex_unlock(&lock);
        return NULL; // Handle memory allocation failure.
    }

    log->timestamp = time(NULL);
    strcpy(new_message, message);
    log->message = new_message;
    log->status_code = status_code;

    log_node* node = malloc(sizeof(log_node));
    if (node == NULL) {
        free(log->message);
        free(log);
        pthread_mutex_unlock(&lock);
        return NULL; // Handle memory allocation failure.
    }

    node->log = log;
    node->next = head;
    head = node;

    pthread_mutex_unlock(&lock);
    return log;
}
```
For writing all logs to a file:
```c
int write_logs(FILE* file) {
    pthread_mutex_lock(&lock);

    // Lock the file before accessing it.
    flockfile(file);

    for (log_node* node = head; node != NULL; node = node->next) {
        fprintf(file, "[%ld] %s (Status code: %d)\n", 
                node->log->timestamp,
                node->log->message,
                node->log->status_code);
    }

    // Unlock the file after accessing it.
    funlockfile(file);

    pthread_mutex_unlock(&lock);
    return 0; // Return status indicates success or failure.
}
```
For cleaning up all allocated memory:
```c
void free_logs() {
    pthread_mutex_lock(&lock);

    while (head != NULL) {
        log_node* next = head->next;

        // Free the message and then the event.
        free(head->log->message);
        free(head->log);
        // Then, free the node itself.
        free(head);

        head = next;
    }

    pthread_mutex_unlock(&lock);
}
```
