['Here is an example of how you might implement such a function in C using pthreads for thread safety and a flexible array implementation to dynamically resize:

```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Assume the definitions of IP_HEADER, UDP_HEADER and PAYLOAD 
typedef struct {
    IP_HEADER ip;
    UDP_HEADER udp;
    PAYLOAD payload;
} TNL_PACKET_T;

typedef struct {
    size_t capacity;
    size_t size;
    TNL_PACKET_T *packets;
    pthread_mutex_t lock;  // used for thread safety
} PacketArray;

int packet_array_init(PacketArray *a, size_t initialSize) {
    a->packets = (TNL_PACKET_T *)malloc(initialSize * sizeof(TNL_PACKET_T));
    if (a->packets == NULL) return -1;  // allocation failed
    a->capacity = initialSize;
    a->size = 0;
    pthread_mutex_init(&a->lock, NULL);  // initialize lock
    return 0;
}

void packet_array_append(PacketArray *a, TNL_PACKET_T element) {
    pthread_mutex_lock(&a->lock);  // acquire lock before modifying the array

    if (a->size >= a->capacity) {  // if at capacity, resize the array
        a->capacity *= 2;
        a->packets = realloc(a->packets, a->capacity * sizeof(TNL_PACKET_T));
    }

    a->packets[a->size++] = element;  // append the new packet and increment size

    pthread_mutex_unlock(&a->lock);  // release lock after modification
}

void packet_array_free(PacketArray *a) {
    free(a->packets);
    a->packets = NULL;
    a->capacity = 0;
    a->size = 0;

    pthread_mutex_destroy(&a->lock);  // clean up lock
}
```
This code provides the basic functionality you requested. However, it does not include error handling for malformed headers or race conditions between threads. Also, implementing such checks would depend on the specific details of your system and could be quite complex. For example, header validation could involve checking that the IP version is valid, that the UDP length field matches the actual packet size, etc. 

