    IP_HEADER ipHeader;
    UDP_HEADER udpHeader;
    char *payload;
    size_t payloadSize;
} TNL_PACKET_T;

typedef struct {
    pthread_mutex_t mutex;
    TNL_PACKET_T **packets;
    int packetCount;
    int maxPacketCount;
    // add your dynamic reconfiguration parameters here
} PacketArray;

void initPacketArray(PacketArray *array, int initialSize) {
    array->maxPacketCount = initialSize;
    array->packets = malloc(initialSize * sizeof(TNL_PACKET_T*));
    pthread_mutex_init(&array->mutex, NULL);
}

void addPacketToArray(PacketArray *array, TNL_PACKET_T *packet) {
    pthread_mutex_lock(&array->mutex);

    if (array->packetCount == array->maxPacketCount) {
        // resize the array
        int newSize = array->maxPacketCount * 2;
        TNL_PACKET_T **newArray = realloc(array->packets, newSize * sizeof(TNL_PACKET_T*));

        if (newArray == NULL) {
            // handle error here
        } else {
            array->packets = newArray;
            array->maxPacketCount = newSize;
        }
    }

    array->packets[array->packetCount] = packet;
    array->packetCount++;

    pthread_mutex_unlock(&array->mutex);
}
``` 

This code provides a basic structure for a thread-safe dynamic array of TNL_PACKET_T structures. It uses `pthread` mutexes to ensure that only one thread can modify the array at a time, preventing data corruption and providing concurrency control. The `addPacketToArray` function automatically resizes the array when it reaches its maximum size, minimizing memory fragmentation and ensuring that additional packets can be added without disrupting ongoing operations.
