CustomData* initializeList(int size, const char* defaultMessage) {
    CustomData* list = (CustomData*)malloc(size * sizeof(CustomData));

    if (list == NULL) {
        printf("Memory allocation failed.\n");
        exit(1);
    }

    for (int i = 0; i < size; ++i) {
        list[i].message = malloc((strlen(defaultMessage) + 1) * sizeof(char));  // +1 for '\0'

        if (list[i].message == NULL) {
            printf("Memory allocation failed.\n");
            exit(1);
        }

        strcpy(list[i].message, defaultMessage);
        list[i].key = i;  // Assign key based on index for simplicity
    }

    return list;
}

void updateList(CustomData* list, int index, const char* newMessage) {
    free(list[index].message);  // Free the old message before updating
    list[index].message = malloc((strlen(newMessage) + 1) * sizeof(char));  

    if (list[index].message == NULL) {
        printf("Memory allocation failed.\n");
        exit(1); 
    }

    strcpy(list[index].message, newMessage);
}

void printList(CustomData* list, int size) {
    for (int i = 0; i < size; ++i) {
        printf("Index: %d\n", i);
        printf("Message: %s\n", list[i].message);
        printf("Key: %d\n", list[i].key);
        printf("\n");
    }
}

void freeList(CustomData* list, int size) {
    for (int i = 0; i < size; ++i) {
        free(list[i].message);  // Free each message in the list
    }

