pthread_mutex_t lock; // mutex for synchronization
struct config* listHead; // head of linked list

void initConfigList() {
    srand(time(NULL)); // seed random generator

    pthread_mutex_init(&lock, NULL); // initialize mutex

    const char* names[] = {"name1", "name2", ...};  // replace with actual names
    const int defaultValues[] = {5000, 8080, ...};  // replace with actual default values
    const protocol_type types[] = {TCP, UDP, HTTP, ...};  // replace with actual protocols

    for(int i = 0; i < 1000; ++i) {
        struct config* newNode = malloc(sizeof(struct config));

        if(!newNode) {
            printf("Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        // initialize the node
        newNode->name = strdup(names[i]);
        newNode->defaultValue = defaultValues[i];
        newNode->type = types[i];

        pthread_mutex_lock(&lock);  // acquire lock before updating config value
        protocolUsage[(int)newNode->type]++; // update usage count for this protocol
        newNode->currentValue = calculateCurrentValue(names[i], defaultValues[i], types[i]); // set current value based on name, default value and type
        pthread_mutex_unlock(&lock);  // release lock after updating config value

        // add the node to the linked list
        newNode->next = listHead;
        listHead = newNode;
    }
