    return data;
}

// Function to check if a new element can be inserted (based on RNTI uniqueness)
int checkUniqueness(Node* head, int RNTI){
    Node* temp = head;
    while(temp != NULL){
        if(temp->data.RNTI == RNTI) return 0; // If same RNTI found, return 0 for failure
        temp = temp->next;
    }
    return 1; // No duplicates found, return success
}

// Function to insert a new node at the end of linked list
void append(Node** head_ref, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&lock);  // Lock for thread safety

    Node* new_node = (Node*) malloc(sizeof(Node));
    if (!new_node || !checkUniqueness(*head_ref, data.RNTI)) {
        printf("Memory allocation failed or RNTI not unique!\n");  // Error handling
        exit(-1);
    }

    new_node->data = data;
    new_node->next = NULL;

    if (*head_ref == NULL) {
        *head_ref = new_node;
    } else {
        Node* last = *head_ref;
        while (last->next != NULL) {
            last = last->next;
        }
        last->next = new_node;
    }

    pthread_mutex_unlock(&lock);  // Unlock after insertion
}

// Function to free all the memory allocated for linked list nodes
void deleteList(Node** head_ref) {
    Node* current = *head_ref;
    Node* next;

    while (current != NULL){
        next = current->next;
        free(current);
        current = next;
    }

    *head_ref = NULL;  // Reset the head to null after deleting all nodes
}
