}

int checkDuplicateRNTI(Node *list, int RNTI) {
    Node *curr = list;
    while (curr != NULL) {
        if (curr->data.RNTI == RNTI) {
            fprintf(stderr, "Error: Duplicate RNTI detected.\n");
            return 1; /* Error */
        }
        curr = curr->next;
    }
    return 0; /* No error */
}

void addElementToList(int maxSize) {
    pthread_mutex_lock(&lock); /* Lock mutex for thread safety */

    if (size >= maxSize) {
        fprintf(stderr, "Error: Maximum size limit reached.\n");
        pthread_mutex_unlock(&lock); /* Unlock the lock before terminating function execution */
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *newElement = createNewElement();
    if (checkDuplicateRNTI(head, newElement->RNTI)) {
        free(newElement); /* Free allocated memory and terminate function execution */
        pthread_mutex_unlock(&lock); /* Unlock the lock before terminating function execution */
        return;
    }

    Node *node = malloc(sizeof(Node));
    if (node == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        pthread_mutex_unlock(&lock); /* Unlock the lock before terminating function execution */
        return;
    }

    node->data = *newElement; /* Copy data into list element */
    free(newElement); /* Free allocated memory as it's no longer needed */

    node->next = head; /* Add new node at the beginning of list */
    head = node;

    size++; /* Increment size counter */

    pthread_mutex_unlock(&lock); /* Unlock mutex after operation is done */
}
