typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
node *head = NULL;
unsigned long max_elements = 1024; // default maximum number of elements

int validate(NFAPI_CRC_INDICATION_PDU_T data) {
    node *cursor = head;
    while (cursor != NULL) {
        if (cursor->data.RNTI == data.RNTI) {
            return 0; // RNTI is not unique
        }
        cursor = cursor->next;
    }
    return 1; // RNTI is unique
}

void insert(NFAPI_CRC_INDICATION_PDU_T data) {
    if (!validate(data)) {
        printf("Error: RNTI is not unique\n");
        return;
    }

    node *newNode = malloc(sizeof(node));
    newNode->data = data;
    newNode->next = NULL;

    pthread_mutex_lock(&lock);
    if (head == NULL) {
        head = newNode;
    } else {
        node *cursor = head;
        while (cursor->next != NULL) {
            cursor = cursor->next;
        }
        cursor->next = newNode;
    }
    pthread_mutex_unlock(&lock);
}

void remove(unsigned long RNTI) {
    pthread_mutex_lock(&lock);
    node **cursor = &head;
    while (*cursor != NULL) {
        if ((*cursor)->data.RNTI == RNTI) {
            node *tempNode = *cursor;
            *cursor = tempNode->next;
            free(tempNode);
            break;
        }
        cursor = &(*cursor)->next;
    }
    pthread_mutex_unlock(&lock);
}

