```c
#include <stdio.h>
#include <stdarg.h>
#include <pthread.h>

typedef enum { DEBUG, INFO, WARN, ERROR } LogLevel;

// Define the base structure of a log sink
struct Sink {
    void (*log)(struct Sink *self, LogLevel level, const char *message);
};

// Implement console logging sink
struct ConsoleSink {
    struct Sink super;
};
void console_sink_log(struct Sink *super, LogLevel level, const char *message) {
    printf("[%d] %s\n", level, message);
}
struct ConsoleSink* console_sink_new() {
    static struct ConsoleSink sink = {{console_sink_log}};
    return &sink;
}

// Logger maintains a list of sinks to which it logs
typedef struct {
    pthread_mutex_t lock;
    struct Sink **sinks;
    int num_sinks;
} Logger;

Logger* logger_new() {
    Logger *logger = malloc(sizeof(Logger));
    logger->num_sinks = 0;
    pthread_mutex_init(&logger->lock, NULL);
    return logger;
}
void logger_add_sink(Logger *self, struct Sink *sink) {
    pthread_mutex_lock(&self->lock);
    self->num_sinks++;
    self->sinks = realloc(self->sinks, sizeof(struct Sink *) * self->num_sinks);
    self->sinks[self->num_sinks - 1] = sink;
    pthread_mutex_unlock(&self->lock);
}
void logger_log(Logger *self, LogLevel level, const char *format, ...) {
    va_list args;
    va_start(args, format);
    int len = vsnprintf(NULL, 0, format, args) + 1;
    char message[len];
    vsnprintf(message, len, format, args);
    va_end(args);

    pthread_mutex_lock(&self->lock);
    for (int i = 0; i < self->num_sinks; ++i) {
        self->sinks[i]->log(self->sinks[i], level, message);
    }
    pthread_mutex_unlock(&self->lock);
}
void logger_free(Logger *self) {
    free(self->sinks);
    free(self);
}
```

This is a basic logging framework with console logging sink and multiple threads support. A more complete solution would involve using an event loop to handle asynchronous operations, JSON parsing for configuration file, networking code for remote log sinks, error handling mechanisms, resource management optimizations etc.
