```cpp
#include <iostream>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <chrono>
#include <thread>
#include <unordered_map>
#include <memory>
#include <fstream>
#include <json/json.h> // Assuming jsoncpp for parsing JSON

using namespace std::literals; 

// Configuration class
class Config {
public:
    static const Config& instance() {
        static Config config("config.json");
        return config;
    }

    int getMaxMessageSize() const { return m_maxMessageSize;}

private:
    explicit Config(const std::string &configPath) {
        Json::Value root;
        std::ifstream file(configPath);
        file >> root;

        m_maxMessageSize = root.get("maxMessageSize", 0).asInt();
        // Parse other settings...
    }

    int m_maxMessageSize;
    // Add other settings...
};

// Message class
class Message {
public:
    explicit Message(const std::string &data) : m_data(data) {}

    const std::string& getData() const { return m_data;}

private:
    std::string m_data;
};

// Queue class
class MessageQueue {
public:
    void addMessage(const Message &message) {
        if (message.getData().size() > Config::instance().getMaxMessageSize()) {
            throw std::runtime_error("Message size exceeded");
        }

        std::lock_guard<std::mutex> lock(m_mutex);
        m_queue.push(message);
        m_condVar.notify_one();
    }

    Message getNextMessage() {
        std::unique_lock<std::mutex> lock(m_mutex);

        if (m_queue.empty()) {
            m_condVar.wait(lock, [this](){ return !m_queue.empty(); });
        }

        auto message = m_queue.front();
        m_queue.pop();
        return message;
    }

private:
    std::queue<Message> m_queue;
    mutable std::mutex m_mutex;
    std::condition_variable m_condVar;
};

// Producer class
class MessageProducer {
public:
    explicit MessageProducer(std::shared_ptr<MessageQueue> queue) : m_queue(std::move(queue)) {}

    void produce(const std::string &data) {
        try {
            Message message(data);
            m_queue->addMessage(message);
        } catch (const std::exception& e) {
            std::cerr << "Failed to add message: " << e.what() << "\n";
        }
    }

private:
    std::shared_ptr<MessageQueue> m_queue;
};

// Consumer class
class MessageConsumer {
public:
    explicit MessageConsumer(std::shared_ptr<MessageQueue> queue) : m_queue(std::move(queue)) {}

    void consume() {
        while (true) {
            auto message = m_queue->getNextMessage();

            // Handle the message...
        }
    }

private:
    std::shared_ptr<MessageQueue> m_queue;
};
```

The above code provides a simple design for a thread-safe queue, along with producer and consumer classes. The `Config` class loads its settings from a JSON file. This setup assumes that each message is small enough to fit into memory. If messages are large, additional considerations such as memory mapping or streaming the data will be required. 

The configuration settings could also provide options for enabling/disabling features like expiration and dead-letter handling based on specific requirements of the application. This basic design can easily be extended with more features in future.
