#include <stdlib.h>
#include <pthread.h>
#define MAX_SIZE 20000 // Maximum allowed size
#define TIMEOUT 5000   // Timeout threshold in milliseconds
#define MAX_THREADS 16 // Number of threads for synchronization
#define BUFFER_SIZE 4096 // Size of the buffer for I/O operations

typedef struct {
    long offset;
    int key;
    int value;
} record;

record* records[MAX_SIZE];
int size = 0, head = 0, tail = -1;
pthread_mutex_t mutex[MAX_THREADS];
pthread_cond_t cond;
FILE *logFile;
double totalLatency = 0.0;
int totalRequests = 0;

void addRecord(record* rec) {
    pthread_mutex_lock(&mutex[(head + 1) % MAX_THREADS]);

    if (size == MAX_SIZE) {
        // Buffer is full, wait for space
        pthread_cond_wait(&cond, &mutex[(head + 1) % MAX_THREADS]);
    }

    records[head] = rec;
    head = (head + 1) % MAX_SIZE;
    size++;

    if (size == 1) {
        // Wake up any sleeping consumer threads
        pthread_cond_signal(&cond);
    }

    pthread_mutex_unlock(&mutex[(head + 1) % MAX_THREADS]);
}

record* getRecord() {
    pthread_mutex_lock(&mutex[tail]);

    if (size == 0) {
        // Buffer is empty, wait for data
        pthread_cond_wait(&cond, &mutex[tail]);
    }

    record* rec = records[tail];
    tail = (tail + 1) % MAX_SIZE;
    size--;

    if (size == MAX_SIZE - 1) {
        // Wake up any sleeping producer threads
        pthread_cond_signal(&cond);
    }

    pthread_mutex_unlock(&mutex[tail]);

    return rec;
}

void* processRecord(void* arg) {
    while (1) {
        record* rec = getRecord();

