    if (it != list.end()) {
        list.insert_after(it, insertString);
    } else {
        list.push_back(insertString);
    }

    long* offsets = new long[std::distance(list.begin(), list.end())];
    int* keys = new int[std::distance(list.begin(), list.end())];
