        mkdir(outputDir, 0700);
    }

    char command[512]; // Max length of a command in unix/linux

    strcpy(command, "zip ");

    if (fast) {
        strcat(command, "-0 ");
    } else {
        switch(compressionLevel){
            case 1:
                strcat(command, "-1 ");
                break;
            case 2:
                strcat(command, "-2 ");
                break;
            case 3:
                strcat(command, "-3 ");
                break;
            case 4:
                strcat(command, "-4 ");
                break;
            case 5:
                strcat(command, "-5 ");
                break;
            case 6:
                strcat(command, "-6 ");
                break;
            case 7:
                strcat(command, "-7 ");
                break;
            case 8:
                strcat(command, "-8 ");
                break;
            case 9:
                strcat(command, "-9 ");
                break;
            default: // if compression level is not in the range of 1-9 or it's not set
                strcat(command, "-6 ");
                break;
        }
    }

    strncat(command, file, sizeof(command) - strlen(command) - 1); // Add filename to command
    strcat(command, " -r "); // Recursive compression option

    char outputPath[256];
    snprintf(outputPath, sizeof(outputPath), "%s/%s.zip", outputDir, basename(file));
    strncat(command, outputPath, sizeof(command) - strlen(command) - 1); // Add output file path to command

    if (system(command) != EXIT_SUCCESS) {
        return 1;
    }

    return 0;
}
```
This solution assumes that the "zip" utility is available on the system, and it does not handle file size or processing time optimizations. It also doesn't provide error handling for cases where outputDir path is too long, filename is too long, etc. You should adapt this code to your specific requirements, adding error checks and optimizations as needed.
