    if (!json_is_array(metricsArray)) {
        printf("JSON does not contain a valid metrics array\n");
        return -1;
    }

    size_t index;
    json_t *value;
    int metricCount = json_array_size(metricsArray);
    *metrics = (Metric*) malloc(metricCount * sizeof(Metric));
    if (*metrics == NULL) {
        return -1;
    }

    // Initialize each metric in the data structure from config file
    int loadedMetrics = 0;
