            printf("Error reading from file.\n");
            return;
        }
        records[i].key_ref = &arr[i]; // Set key ref to array element
    }
    pthread_mutex_unlock(&mutex);

    fclose(file);
}

void set_random_value(Record* record, int min, int max) {
    pthread_mutex_lock(&mutex);
    record->value = rand() % (max - min + 1) + min; // Set value to random number in range
    pthread_mutex_unlock(&mutex);
}

void deallocate_memory(Record* records) {
    pthread_mutex_lock(&mutex);
    free(records);
    pthread_mutex_unlock(&mutex);
}
```
