#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct log_record {
    int log_level;
    time_t timestamp;
    char* message;
    void* metadata;
    struct log_record *prev, *next;
} LOG_RECORD;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
LOG_RECORD* head = NULL;
int count = 0;

void* allocate(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) { 
        // Log memory exhaustion and release all allocated memory
        free_all();
        return NULL;
    }
    return ptr;
}

int append_record(LOG_RECORD* record) {
    pthread_mutex_lock(&lock);
    ++count;

    if (head == NULL) {
        head = record;
        record->prev = record->next = NULL;
    } else {
        LOG_RECORD* tail = head;
        while(tail->next != NULL) 
            tail = tail->next;

        tail->next = record;
        record->prev = tail;
        record->next = NULL;
    }

    pthread_mutex_unlock(&lock);
}

LOG_RECORD* create_log_record(int log_level, char* message, void* metadata) {
    LOG_RECORD* record = allocate(sizeof(LOG_RECORD));

    if (record == NULL) 
        return NULL; // Log memory exhaustion and return NULL

    record->log_level = log_level;
    record->timestamp = time(NULL);
    record->message = strdup(message);
    record->metadata = metadata;

    if (append_record(record) != 0){ 
        // Log failed to append record and release allocated memory
        free(record); 
        return NULL;
    }
    return record;
}

void free_all() {
    pthread_mutex_lock(&lock);

    while (head != NULL) {
        LOG_RECORD* next = head->next;
        free(head->message); 
        free(head);
        head = next;
    }

    pthread_mutex_unlock(&lock);
}
```
