```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct dns_query {
    int id;
    char type[3];  // A, NS, MX etc
    char class[3];  // IN etc
    char* payload;  
    size_t length;
    struct dns_query *next;
} DNSQuery;

DNSQuery *initialize(int id, const char *type, const char *class, const char *payload) {
    DNSQuery *q = malloc(sizeof(*q));
    if (q == NULL) return NULL;  // handle memory allocation failure

    q->id = id;
    strncpy(q->type, type, sizeof(q->type)-1);
    strncpy(q->class, class, sizeof(q->class)-1);
    q->length = strlen(payload) + 1;  // including null terminator
    q->payload = malloc(q->length);
    if (q->payload == NULL) {
        free(q);
        return NULL;  // handle memory allocation failure
    }

    strncpy(q->payload, payload, q->length);
    q->next = NULL;
    return q;
}

void destroy(DNSQuery *q) {
    if (q == NULL) return;
    DNSQuery *curr, *next = q;

    while ((curr = next)) {  // traverse list and free memory for each element
        next = curr->next;
        free(curr->payload);
        free(curr);
    }
}
