static int nextFree = 0; // Index of the next available slot.

NFAPI_CRC_INDICATION_PDU_T* initNFAPI_CRC_INDICATION_PDU_T() {
    pthread_mutex_lock(&mutex);

    if (nextFree >= MAX_POOL_SIZE) {
        fprintf(stderr, "ERROR: Memory pool is full. Allocation failed.\n");
        pthread_mutex_unlock(&mutex);
        return NULL; // Return NULL on allocation failure.
    }

    NFAPI_CRC_INDICATION_PDU_T* newElement = &memoryPool[nextFree++];

    // Initialize the element here.
    newElement->RNTI = 0;
    newElement->VALID = 0;
    newElement->RX_UE_INFORMATION_TAG = 0;
    srand(time(NULL)); // Seed for randomness.
