```c
#include <stdlib.h>
#include <pthread.h>
#include <sys/time.h>
#include <string.h>
#include "packet_list.h"

// Structure to hold the packet data
typedef struct {
    int id;
    struct timeval timestamp;
    char *sourceIP;
    char *destinationIP;
    size_t payloadSize;
} Packet;

// Node structure for the linked list 
typedef struct node {
    Packet *packet;
    struct node *next;
} Node;

// Linked list to hold packets
typedef struct {
    pthread_mutex_t lock;
    Node *head;
    Node *tail;
    size_t maxCapacity;
    time_t ageThreshold;
} PacketList;

PacketList* packetListCreate(size_t maxCapacity, time_t ageThreshold) {
    PacketList *list = malloc(sizeof(PacketList));
    list->maxCapacity = maxCapacity;
    list->ageThreshold = ageThreshold;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void packetListAdd(PacketList *list, Packet *packet) {
    pthread_mutex_lock(&list->lock);

    if (list->maxCapacity > 0 && list->tail != NULL && list->maxCapacity <= listSize(list)) {
        packetListClearOlderThan(list, list->ageThreshold);
    }

    Node *node = malloc(sizeof(Node));
    node->packet = packet;
    node->next = NULL;

    if (list->tail == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        list->tail = node;
    }

    pthread_mutex_unlock(&list->lock);
}

void packetListClear(PacketList *list) {
    pthread_mutex_lock(&list->lock);

    Node *node = list->head;
    while (node != NULL) {
        Node *temp = node;
        node = node->next;

        free(temp->packet);
        free(temp);
    }

    list->head = NULL;
    list->tail = NULL;

    pthread_mutex_unlock(&list->lock);
}
```
Please note this is a simple example and does not include all the features such as updating packet fields, periodic resource freeing or advanced integration considerations. For a production system, one would need to handle more complex scenarios and use more sophisticated data structures and algorithms based on the requirements of the actual use case. 

