void allocateMemoryAndInitialize(size_t num_offsets, size_t num_records, int factor) {
    if (totalMemory + sizeof(long)*num_offsets + sizeof(int)*num_offsets + sizeof(record)*num_records > MAX_MEM){
        errorExit("Maximum memory limit reached.");
    }
    offsets = malloc(sizeof(long) * num_offsets);
    if (offsets == NULL) {
        errorExit("Failed to allocate offsets.");
    }
    keys = malloc(sizeof(int) * num_records);
    if (keys == NULL) {
        errorExit("Failed to allocate keys.");
    }
    records = malloc(sizeof(record) * num_records);
    if (records == NULL){
        errorExit("Failed to allocate records.");
    }
    totalMemory += sizeof(long)*num_offsets + sizeof(int)*num_offsets + sizeof(record)*num_records;

    for(size_t i = 0; i < num_offsets; ++i){
        offsets[i] = calculateOffset(i);
    }

    for(size_t j = 0; j < num_records; ++j){
