typedef struct {
    size_t max_size;
    size_t curr_size;
    pthread_mutex_t lock; // For thread safety
    PHY_TASK_T* tasks;
} TaskPool;

// Initialize task pool with maximum size
bool initTaskPool(TaskPool* pool, size_t max_size) {
    pool->max_size = max_size;
    pool->curr_size = 0;
    pthread_mutex_init(&pool->lock, NULL); // Initialize lock for thread safety

    // Allocate memory
    pool->tasks = malloc(max_size * sizeof(PHY_TASK_T)); 

    if (pool->tasks == NULL) {
        return false; // Out of memory
    }

    memset(pool->tasks, 0, max_size * sizeof(PHY_TASK_T));

    return true;
}

// Add task to pool with synchronization
bool addTaskToPool(TaskPool* pool, PHY_TASK_T* task) {
    pthread_mutex_lock(&pool->lock); // Lock for thread safety

    if (pool->curr_size >= pool->max_size) {
        pthread_mutex_unlock(&pool->lock); 
        return false; // Pool is full
    }

    memcpy(&pool->tasks[pool->curr_size], task, sizeof(PHY_TASK_T)); // Copy data into pool
    pool->curr_size++;

    pthread_mutex_unlock(&pool->lock); 

    return true;
}

// Clean up task pool memory and mutex
void cleanUpTaskPool(TaskPool* pool) {
    free(pool->tasks); // Free allocated memory
    pthread_mutex_destroy(&pool->lock); // Destroy lock for thread safety
}
```
