    newNode->next = head;

    head = newNode;

    pthread_mutex_unlock(&lock);
}

void removeElement(int rnti) {
    pthread_mutex_lock(&lock);

    Node** tracer = &head;
    while (*tracer != NULL) {
        if ((*tracer)->data->RNTI == rnti) {
