void add_ue(UE_CONTEXT_T ue) {
    pthread_mutex_lock(&lock);

    if (size < max_size) {
        Node *newNode = malloc(sizeof(Node));
        newNode->context = ue;
        newNode->next = head;
        head = newNode;
        size++;

        // Serialize and store in external database
        int result = external_database_store(&ue);
        if (result != 0) {
            printf("Error storing UE context to external database\n");
        }
    } else {
        printf("List is full. Unable to add UE.\n");
    }

    pthread_mutex_unlock(&lock);
}

void remove_ue(UE_CONTEXT_T ue) {
    pthread_mutex_lock(&lock);

    Node *temp = head, *prev = NULL;

    if (temp != NULL && temp->context.state_flag == ue.state_flag) {
        head = temp->next;
        free(temp);
        size--;

        // Remove from external database
        int result = external_database_remove(&ue);
        if (result != 0) {
            printf("Error removing UE context from external database\n");
        }

        return;
    }

    while (temp != NULL && temp->context.state_flag != ue.state_flag) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) {
       printf("Unable to find UE context\n");
       return;
    }

    prev->next = temp->next;
    size--;

    // Remove from external database
    int result = external_database_remove(&ue);
    if (result != 0) {
        printf("Error removing UE context from external database\n");
    }

    free(temp); 

    pthread_mutex_unlock(&lock);
}
```

