typedef struct _CELL_MEASUREMENT_REPORT_PDU {
    int cell_id;
    int measurement_period;
    int rsrp_value;
    time_t timestamp;
} CELL_MEASUREMENT_REPORT_PDU_T;

typedef struct _Node {
    struct _Node *next;
    CELL_MEASUREMENT_REPORT_PDU_T data;
} Node;

typedef struct _LinkedList {
    _Atomic(Node *) head;
    pthread_mutex_t mutex;
} LinkedList;

void initList(LinkedList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

CELL_MEASUREMENT_REPORT_PDU_T* getCellById(LinkedList *list, int cellId){
   Node* currNode = atomic_load(&list->head);
    while (currNode != NULL) {
        if(currNode->data.cell_id == cellId) return &currNode->data;
         currNode = currNode->next;
    } 
   return NULL; // not found
}

void addCellMeasurementReport(LinkedList *list, CELL_MEASUREMENT_REPORT_PDU_T data) {
    Node* newNode = malloc(sizeof(Node));
    newNode->data = data;

    pthread_mutex_lock(&list->mutex);
    newNode->next = atomic_load(&list->head);

    // Ensure that the list head remains valid even if other threads update it while this thread is adding a node.
    while(!atomic_compare_exchange_weak(&list->head, &newNode->next, newNode)) { 
        newNode->next = atomic_load(&list->head); 
    }

    pthread_mutex_unlock(&list->mutex);
}
```
