void processRecords(int num_records, int min_range, int max_range) {
    srand(time(NULL));
    long* offsets = NULL;
    int* keys = NULL;
    record* records = NULL;

    size_t total_size = 0;
    // Calculate required memory for each data structure 
    size_t offsets_size = num_records * sizeof(long);
    size_t keys_size = num_records * sizeof(int);
    size_t records_size = num_records * sizeof(record);

    // Validate total memory usage and allocate memory for each structure
    while (1) {
        if ((total_size + offsets_size + keys_size + records_size) > INT_MAX / 2) {
            fprintf(stderr, "Exceeded max allowed memory.\n");
            break;
        } else {
            // Try to allocate memory and initialize arrays
            offsets = (long*)malloc(offsets_size);
            keys = (int*)malloc(keys_size);
            records = (record*)calloc(num_records, sizeof(record));

            if (!offsets || !keys || !records) {
                fprintf(stderr, "Failed to allocate memory. Retrying...\n");

                // Reduce the number of records and try again
                num_records /= 2;
                continue;
            } else {
                break;
            }
        }
    }

    if (offsets && keys && records) {
        // Assign random values to each record's int field
        for (int i = 0; i < num_records; ++i) {
            int random_value = min_range + rand() % (max_range - min_range + 1);
            records[i].value = random_value;

            // Logging could be optimized by buffering and writing efficiently 
