    unsigned char key[32]; // Encryption key
} AES_Context;

AES_Context* init_aes(const char *password) {
    AES_Context *context = malloc(sizeof(AES_Context)); 

    EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha1(), NULL, (unsigned char*)password, strlen(password), 1, context->key, NULL); 
