// Define the record structure
typedef struct {
    int value;
} Record;

// Allocate and initialize arrays with user-specified size, with memory usage bounded by 50% of available RAM
void alloc_and_init(long *offsets, int offsetSize, int *keys, int keysSize) {
    assert(offsetSize > 0 && keysSize > 0);

    long totalMemory = sysconf(_SC_PHYS_PAGES) * sysconf(_SC_PAGE_SIZE);
    long availableMemory = 0.5 * totalMemory; // 50% of total memory

    size_t allocationSize = (sizeof(long)*offsetSize + sizeof(int)*keysSize);

    if (allocationSize > availableMemory) {
        logError("Allocation would exceed maximum allowed memory");
        return;
    }

    // Allocate and initialize arrays using a memory pool strategy to optimize reuse and minimize fragmentation
    offsets = malloc(sizeof(long)*offsetSize);
    keys = malloc(sizeof(int)*keysSize);

    if (offsets == NULL || keys == NULL) {
        logError("Allocation failed");
        return;
    }

    memset(offsets, 0, sizeof(long)*offsetSize);
    memset(keys, 0, sizeof(int)*keysSize);
}

// Allocate and initialize records with a heuristic-based allocation strategy for memory pool to prevent paging issues
void alloc_records(Record **records, int recordCount) {
    assert(recordCount > 0);

    // Get the system page size
    long pagesize = sysconf(_SC_PAGESIZE);

    // Allocate a large chunk of memory to reduce the likelihood of triggering paging
    void *memory = mmap(NULL, recordCount*pagesize, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (memory == MAP_FAILED) {
        logError("Memory mapping failed");
        return;
    }

    // Divide the memory into chunks and assign each chunk to a thread for concurrent processing
    pthread_t threads[recordCount];
    int i;

    for (i = 0; i < recordCount; ++i) {
        void *chunk = ((char *)memory + pagesize*i);

        if (pthread_create(&threads[i], NULL, initRecordChunk, chunk)) {
            logError("Thread creation failed");

            // Handle error here
        }
    }

    for (i = 0; i < recordCount; ++i) {
        if (pthread_join(threads[i], NULL)) {
            logError("Thread join failed");

            // Handle error here
        }
    }
}

void *initRecordChunk(void *chunk) {
    Record *record = chunk;

    record->value = secureRandom();

    return NULL;
}

// Securely generate a random number using the CSPRNG, falling back to a deterministic generator in case of failure
int secureRandom() {
    int value = csprng(0, 10); // 0-10 is the range for the random numbers

    if (value == -1) { // If CSPRNG fails
        logWarning("CSPRNG failed. Falling back to deterministic generator");

        value = detRandom(0, 10); // Use a deterministic generator instead
    }

    return value;
}
