#define MAX_RANDOM_VALUE 100       // Maximum random value for the Record array

// Function to read the configuration file and populate the Record array
int loadRecords(const char* filename, Record** records, size_t* numRecords) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening file");
        return -1;
    }

    // Read the file line by line using a buffer to handle large files efficiently
    char line[MAX_LINE_LENGTH];
    *numRecords = 0;
    while (fgets(line, MAX_LINE_LENGTH, file)) {
        long offset;
        int key;

        // Validate the line format and extract the offset and key values
        if (sscanf(line, "%ld %d", &offset, &key) != 2) {
            fprintf(stderr, "Invalid line: %s", line);
            continue;
        }

        // Increase the size of the records array and add the new record
        *records = realloc(*records, (*numRecords + 1) * sizeof(Record));
        if (*records == NULL) {
            perror("Error allocating memory for records");
            return -1;
        }

        Record* record = &((*records)[*numRecords]);
        record->offset = offset;
        record->key = key;
        ++(*numRecords);
    }

    fclose(file);
    return 0;
}

// Function to allocate and initialize memory for the secondary array
int createSecondaryArray(const char* filename, int** values, size_t minValue, size_t maxValue) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening file");
        return -1;
    }

    // Create an array of boolean flags to track which values have been encountered
    size_t numValues = maxValue - minValue + 1;
    char* exists = calloc(numValues, sizeof(char));
    if (exists == NULL) {
        perror("Error allocating memory for secondary array");
        return -1;
    }

    *values = malloc(sizeof(int) * numValues);
    if (*values == NULL) {
        perror("Error allocating memory for secondary array");
        free(exists);
        return -1;
    }

    size_t count = 0;
    int value;
    while (fscanf(file, "%d", &value) == 1 && count < numValues) {
        // Validate the value and add it to the secondary array if it's not a duplicate
        if (value >= minValue && value <= maxValue && !exists[value - minValue]) {
            exists[value - minValue] = 1;
            (*values)[count++] = value;
        }
    }

    free(exists);
    fclose(file);
    return 0;
}

// Function to create a shared memory region for inter-process communication
int* createSharedMemoryRegion(size_t size) {
    int fd = shm_open("/my_shared_memory", O_CREAT | O_RDWR, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        perror("Error creating shared memory region");
        return NULL;
    }

    // Set the size of the shared memory region using ftruncate
    if (ftruncate(fd, size * sizeof(int)) == -1) {
        perror("Error setting size of shared memory region");
        close(fd);
        shm_unlink("/my_shared_memory");
        return NULL;
    }

    // Map the shared memory region into our address space using mmap
    int* values = (int*)mmap(NULL, size * sizeof(int), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (values == MAP_FAILED) {
        perror("Error mapping shared memory region");
        close(fd);
        shm_unlink("/my_shared_memory");
        return NULL;
    }

    close(fd); // We can now safely close the file descriptor
    return values;
}

// Function to initialize a Record array with unique random values
int initializeRecords(Record* records, size_t numRecords) {
    int *usedValues = calloc((MAX_RANDOM_VALUE - MIN_RANDOM_VALUE + 1), sizeof(int));
    if (usedValues == NULL) {
        perror("Error allocating memory for used values");
        return -1;
    }

    srand(time(NULL)); // Seed the random number generator with current time
    for (size_t i = 0; i < numRecords; ++i) {
        int value;

        // Generate a unique random value within the specified range
        do {
            value = rand() % (MAX_RANDOM_VALUE - MIN_RANDOM_VALUE + 1) + MIN_RANDOM_VALUE;
        } while (usedValues[value - MIN_RANDOM_VALUE]);

        usedValues[value - MIN_RANDOM_VALUE] = 1;
        records[i].key = value;
    }

    free(usedValues); // Free the memory allocated for the used values array
    return 0;
}
```
