```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct record {
    int value;
} record_t;

struct data_context {
    long *offsets;
    int *keys;
    record_t **records;
    pthread_mutex_t lock;
};

void initialize(struct data_context* ctx, size_t num) {
    srand((unsigned int)time(NULL)); // Initialize random number generator.

    ctx->offsets = (long*)aligned_alloc(alignof(max_align_t), sizeof(long) * num);
    ctx->keys = (int*)aligned_alloc(alignof(max_align_t), sizeof(int) * num);
    ctx->records = (record_t**)malloc(sizeof(record_t*) * num); // We'll allocate each record separately.

    pthread_mutex_init(&ctx->lock, NULL); // Initialize the mutex for thread safety.
}

void set_value(struct data_context* ctx, size_t idx, int value) {
    if (idx >= _msize(ctx->keys) / sizeof(int)) return; 

    pthread_mutex_lock(&ctx->lock); // Lock the mutex.

    ctx->records[idx]->value = value;

    pthread_mutex_unlock(&ctx->lock); // Unlock the mutex.
}

int get_value(struct data_context* ctx, size_t idx) {
    if (idx >= _msize(ctx->keys) / sizeof(int)) return 0;

    pthread_mutex_lock(&ctx->lock); // Lock the mutex.

    int value = ctx->records[idx]->value;

    pthread_mutex_unlock(&ctx->lock); // Unlock the mutex.

    return value;
}

void deallocate(struct data_context* ctx) {
    free(ctx->offsets);
    free(ctx->keys);

    for (size_t i = 0; i < _msize(ctx->keys) / sizeof(int); ++i) {
        if (ctx->records[i]) free(ctx->records[i]);
    }
    free(ctx->records);

    pthread_mutex_destroy(&ctx->lock); // Destroy the mutex.
}
