  int32_t RNTI;
  bool CRCFLAG;
};

// Cache to store frequently accessed values.
std::map<uint16_t, NFAPI_CRC_INDICATION_PDU_T*> cache;

void processIntegersAndGenerateCRC(int *arr, size_t &size) {
  // Ensure the array is not null before proceeding.
  if (arr == nullptr) {
    std::cout << "Array pointer is null.\n";
    return;
  }

  // Initialize random number generator and distribution.
  std::random_device rd;
  std::mt19937 gen(rd());
  std::uniform_int_distribution<> dis(-20, 50);  // Replace with your desired range.

  // Populate the array with random integers within specified range.
  for (size_t i = 0; i < size; ++i) {
    arr[i] = dis(gen);
  }

  // Find and print the largest integer in the array.
  auto maxElement = std::max_element(arr, arr + size);
  std::cout << "The largest element is: " << *maxElement << '\n';

  // Allocate memory for NFAPI_CRC_INDICATION_PDU_T structures.
  auto pdu = new (std::nothrow) NFAPI_CRC_INDICATION_PDU_T[size];
  if (!pdu) {
    std::cout << "Failed to allocate memory.\n";
    return;
  }

  // Populate structures with random values.
  for (size_t i = 0; i < size; ++i) {
    pdu[i].RX_UE_INFORMATION_TAG = arr[i];
    gen();  // Discard unused value.
    pdu[i].CRCFLAG = dis(gen);

    // Update cache with frequently accessed values.
    if (cache.find(pdu[i].RX_UE_INFORMATION_TAG) == cache.end()) {
      cache[pdu[i].RX_UE_INFORMATION_TAG] = &pdu[i];
    }
  }

