public class ObjectPool<T> where T : new()
{
    private readonly List<T> _items;

    public ObjectPool(int size)
    {
        _items = Enumerable.Repeat(new T(), size).ToList();
    }

    public T GetObject()
    {
        if(_items.Count > 0){
            var item = _items[0];
            _items.RemoveAt(0);
            return item;
        }

        // If pool is empty, create a new object
        return new T();
    }

    public void ReturnObjectToPool(T item)
