['Below is an example implementation in C programming language. It includes necessary linked list operations for adding nodes, checking for duplicates and loading from a config file. It also uses pthread library for thread safety and error handling. Please note that this code assumes that you have defined `network_settings` struct with fields corresponding to MAC address, IP address, subnet mask and gateway details.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct network_settings {
    char mac[20];
    char ip[16];
    char subnet_mask[16];
    char gateway[16];
} network_settings;

typedef struct node {
    network_settings data;
    struct node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Node* head = NULL;

int is_duplicate(network_settings data) {
    Node* current = head;
    while (current != NULL) {
        if ((strcmp(current->data.mac, data.mac) == 0) && 
            (strcmp(current->data.ip, data.ip) == 0)) {
            return 1;
        }
        current = current->next;
    }
    return 0;
}

void push(network_settings data) {
    pthread_mutex_lock(&lock); // acquire lock before modification

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        printf("Memory allocation failed.\n");
        return;
    }

    newNode->data = data;
    newNode->next = NULL;

    // check for duplicates and add to list
    if (is_duplicate(data)) {
        printf("Duplicate entry detected. Not adding to the list.\n");
        free(newNode);
        pthread_mutex_unlock(&lock); 
        return;
    } else {
        newNode->next = head;
        head = newNode;
    }

    pthread_mutex_unlock(&lock); // release lock after modification
}

void populate_list(char* filename) {
    FILE *file = fopen (filename, "r");
    if (file == NULL) {
        printf("Could not open file\n");
        return;
    }

    network_settings data;

    while(!feof(file)) {
        int res = fscanf(file, "%s %s %s %s\n", data.mac, data.ip, data.subnet_mask, data.gateway); 

        // validate input and add to list
        if (res == 4) push(data);  
    }

    fclose(file);
}
```
This code optimizes for initialization speed by minimizing re-allocation of memory whenever possible, and handles potential race conditions with a mutex lock. However, it doesn't handle errors in the configuration file format or missing fields - that would require more complex error handling and data validation logic. The trade-offs between memory usage, initialization speed, and robustness of error handling depend on how critical these aspects are for your application.
']

