typedef struct data_entry {
    double dbl;
    int integer;
    char *str;
    long long lnglong;
} data_entry;

void allocate_arrays(size_t size) {

    // Allocate memory for each array
    double* doubles = (double*)malloc(sizeof(double)*size);
    char** strings = (char**)malloc(sizeof(char*)*size);
    data_entry** entries = (data_entry**)malloc(sizeof(data_entry*)*size);
    long long *longs = (long long *) malloc(sizeof(long long)*size);
    float *floats = (float *) malloc(sizeof(float)*size);

    if(!doubles || !strings || !entries || !longs || !floats) {
        printf("Memory allocation failed\n");
        return;
    }

    for(int i = 0; i < size; ++i){
        // Populate the arrays

        doubles[i] = (double)i / (size-1); 

        strings[i] = malloc(256);
        if(!strings[i]) {
            printf("Memory allocation failed\n");
            return;
        }
        sprintf(strings[i], "%.4f", doubles[i]);

        entries[i] = (data_entry*)malloc(sizeof(data_entry));
        if(!entries[i]) {
            printf("Memory allocation failed\n");
            return;
        }

        data_entry e = {doubles[i], i, strings[i], longs[i]};
        *entries[i] = e;

        floats[i] = sqrt(doubles[i]); 
    }

    // Clean up memory
    for (size_t i = 0; i < size; ++i) {
        free(strings[i]);
        free(entries[i]);
    }

    free(doubles);
    free(strings);
    free(entries);
    free(longs);
    free(floats);
}
```
