['```C
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* string;
    int key;
} CustomData;

typedef struct Node {
    CustomData data;
    struct Node *next;
} Node;

typedef struct Map {
    Node **table;
    size_t tableSize;
    pthread_mutex_t mutex;
} Map;

Map* createMap(size_t initialSize) {
    Map *map = malloc(sizeof(Map));
    if (!map) return NULL;

    map->table = calloc(initialSize, sizeof(Node*));
    if (!map->table) {
        free(map);
        return NULL;
    }

    map->tableSize = initialSize;
    pthread_mutex_init(&map->mutex, NULL);
    return map;
}

unsigned long hash(int key) {
    unsigned long hash = 5381;
    int c = key;
    while (c) {
        hash = ((hash << 5) + hash) + c; 
        c /= 26;
    }
    return hash;
}

int insert(Map *map, CustomData data) {
    pthread_mutex_lock(&map->mutex);

    unsigned long index = hash(data.key) % map->tableSize;
    Node *node = malloc(sizeof(Node));
    if (!node) {
        pthread_mutex_unlock(&map->mutex);
        return -1;
    }

    node->data = data;
    node->next = map->table[index];
    map->table[index] = node;

    // Resize if load factor exceeds threshold
    float loadFactor = 0.75f;  // Adjust this value as needed
    size_t count = 0;
    for (size_t i = 0; i < map->tableSize; ++i) {
        Node *node = map->table[i];
        while (node) {
            node = node->next;
            ++count;
        }
    }

    if (count > loadFactor * map->tableSize) {
        // Resize the hash table and rehash all elements. This is left as an exercise to the reader.
    }

    pthread_mutex_unlock(&map->mutex);
    return 0;
}

int delete(Map *map, int key) {
    pthread_mutex_lock(&map->mutex);

    unsigned long index = hash(key) % map->tableSize;
    Node **ppNode = &map->table[index];  // pointer to first node
    while (*ppNode) {
        if ((*ppNode)->data.key == key) {
            Node *nodeToDelete = *ppNode;
            *ppNode = nodeToDelete->next;
            free(nodeToDelete);

            pthread_mutex_unlock(&map->mutex);
            return 0;
        }

        ppNode = &(*ppNode)->next;
    }

    pthread_mutex_unlock(&map->mutex);
    return -1;   // Not found
}

CustomData* lookup(Map *map, int key) {
    unsigned long index = hash(key) % map->tableSize;
    Node *node = map->table[index];

    while (node) {
        if (node->data.key == key) return &node->data;

        node = node->next;
    }

    return NULL;   // Not found
}
```

Please note that this is a simplistic implementation and lacks many features such as error handling, resizing the hash table when it becomes too crowded, logging service integration, thread safety for concurrent access patterns, etc. Also, please take into account that creating a fully featured, production-ready code requires deep knowledge of C and data structures, system dependencies, performance considerations, trade-offs between memory usage, efficiency, robustness against race conditions, handling of external data sources delays, error handling, thread safety, logging service availability issues, resource constraints, high-performance environments etc.
