int run_background(void (*func)(void)){
    pid_t pid = fork();

    if (pid == 0){
        // Child process: execute the function
        func();
        exit(0);  // Exit child process gracefully, avoid leaving zombie processes.
    } else if(pid < 0) {
        return -1;  // Fork failed
    }

    // Parent process can wait for child process to finish using wait() or waitpid().
    int status;
    waitpid(pid, &status, 0);  // Wait for child process to finish

    if (WIFEXITED(status)) {
        return WEXITSTATUS(status);  // Return exit code of the child process.
    } else {
        return -1;  // Child process failed or was terminated abnormally
    }
}
