int initializeConnections() {
    pthread_t threads[MAX_CONNECTIONS];
    int i;

    connections = (NetworkFlowRecord**) malloc(sizeof(NetworkFlowRecord*) * MAX_CONNECTIONS);
    if (connections == NULL) return -1; // Out of memory

    for (i = 0; i < MAX_CONNECTIONS; ++i) {
        connections[i] = (NetworkFlowRecord*) malloc(sizeof(NetworkFlowRecord));
        if (connections[i] == NULL) return -1; // Out of memory
        ++allocated;
    }

    for (i = 0; i < MAX_CONNECTIONS; ++i) {
        pthread_create(&threads[i], NULL, handleConnection, &connections[used]);
        ++used;
        if(used % (MAX_CONNECTIONS / PACKETS_PER_SEC) == 0) sleep(1); // Adjust frequency of new connections
    }

    for (i = 0; i < MAX_CONNECTIONS; ++i) pthread_join(threads[i], NULL);

    return 0;
}
```

