['Here is a basic implementation of what you asked for in Python. It leverages the built-in `json` module for parsing/serializing JSON data. To validate JSON against schemas we use `jsonschema` library and `requests` to make HTTP requests:

```python
import json
from abc import ABC, abstractmethod
import requests
from jsonschema import Draft7Validator, validators
import copy

# define a base class for our objects
class BaseJsonObject(ABC):
    _registry = {}
    def __init__(self, id: str):
        self.id = id

    @abstractmethod
    def to_json(self) -> dict:
        pass

    @staticmethod
    def from_json(data: dict):
        if 'type' in data:
            factory = BaseJsonObject._registry.get(data['type'])
            if factory is not None:
                return factory(data)

        raise ValueError('Invalid JSON')

    @classmethod
    def register_factory(cls, id: str):
        def decorator(subclass):
            cls._registry[id] = subclass
            return subclass

        return decorator

# define a class that can be serialized to/from JSON
@BaseJsonObject.register_factory('mytype')
class MyType(BaseJsonObject):
    def __init__(self, id: str, field1: str, optional_field2=None):
        super().__init__(id)
        self.field1 = field1
        self.optional_field2 = optional_field2

    @staticmethod
    def from_json(data):
        schema = { "type": "object", "properties": {"type": {"const": "mytype"}, "id": {"type": "string"}, "field1": {"type": "string"}}, "required": ["type", "id", "field1"]}
        validator = Draft7Validator(schema)

        if not validator.is_valid(data):
            raise ValueError('Invalid JSON')

        return MyType(**{k: v for k,v in data.items() if k != 'type'})

    def to_json(self) -> dict:
        res = copy.deepcopy(self.__dict__)
        res['type'] = 'mytype'
        return res

# usage example:
obj = MyType('id1', 'field1_value')
print(obj.to_json())  # {'type': 'mytype', 'id': 'id1', 'field1': 'field1_value'}
print(MyType.from_json({'type': 'mytype', 'id': 'id2', 'field1': 'field2_value'}).__dict__)  # {'id': 'id2', 'field1': 'field2_value'}
```

