} DataArrays;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

DataArrays *initialize_data_arrays(size_t initial_size) {
    DataArrays *arrays = malloc(sizeof(DataArrays));
    arrays->current_size = 0;
    arrays->total_size = initial_size;

    arrays->offsets = malloc(initial_size * sizeof(long));
    arrays->keys = malloc(initial_size * sizeof(int));
    arrays->data_values = malloc(initial_size * sizeof(float));
    arrays->timestamps = malloc(initial_size * sizeof(time_t));
    arrays->records = malloc(initial_size * sizeof(Record*));

    return arrays;
}

void resize_data_arrays(DataArrays *arrays, size_t new_size) {
    pthread_mutex_lock(&lock);

    long *new_offsets = realloc(arrays->offsets, new_size * sizeof(long));
    int *new_keys = realloc(arrays->keys, new_size * sizeof(int));
    float *new_data_values = realloc(arrays->data_values, new_size * sizeof(float));
    time_t *new_timestamps = realloc(arrays->timestamps, new_size * sizeof(time_t));
    Record **new_records = realloc(arrays->records, new_size * sizeof(Record*));

    if (new_offsets != NULL) arrays->offsets = new_offsets;
    if (new_keys != NULL) arrays->keys = new_keys;
    if (new_data_values != NULL) arrays->data_values = new_data_values;
    if (new_timestamps != NULL) arrays->timestamps = new_timestamps;
    if (new_records != NULL) arrays->records = new_records;

    arrays->total_size = new_size;

    pthread_mutex_unlock(&lock);
}

void add_record(DataArrays *arrays, int key, float data_value) {
    if (arrays->current_size == arrays->total_size) {
        resize_data_arrays(arrays, 2 * arrays->total_size);
    }

    pthread_mutex_lock(&lock);

    size_t index = arrays->current_size;
    arrays->keys[index] = key;
    arrays->data_values[index] = data_value;
    arrays->offsets[index] = (long)&(arrays->keys[index]);

    Record *record = malloc(sizeof(Record));
    record->key = key;
    record->data_value = data_value;
    record->timestamp = time(NULL);

    arrays->records[index] = record;
    arrays->timestamps[index] = record->timestamp;

    arrays->current_size++;

    pthread_mutex_unlock(&lock);
}
``` 
