GHashTable** init_hash_tables(int size) {
   GHashTable ** hashTables = malloc(sizeof(GHashTable*) * 2);

   for (int i = 0; i < 2; i++) {
      hashTables[i] = g_hash_table_new(g_str_hash, g_str_equal);
   }

   return hashTables;
}

Item* create_item(char key, int value) {
   Item * new_item = malloc(sizeof(Item));

   if (new_item == NULL) {
      return NULL;  // Memory allocation failed
   }

   new_item->key = key;
   new_item->value = value;
   new_item->next_item = NULL;

   return new_item;
}

void populate_hash_table(GHashTable* table, Item * item) {
    gpointer oldValue;

    // Use g_strdup so we can store keys as const char*.
    if (g_hash_table_lookup_extended(table, g_strdup(&item->key), NULL, &oldValue)) {
        Item * existingItem = oldValue;

        // If the item already exists in the table, update its dependencies.
        while (existingItem->next_item != NULL) {
            existingItem = existingItem->next_item;
        }

        existingItem->next_item = item;
    } else {
        // If the item doesn't exist in the table, add it.
        g_hash_table_insert(table, g_strdup(&item->key), item);
    }
}
